-- Material de apoio ABRACAM (junho/2026) separado por tema, base para a geração de questões por IA.
INSERT INTO public.material_trechos (tema, ordem, titulo, conteudo, versao) VALUES
(3, 1, $mat$Organização do SFN, órgãos normativos e supervisores, hierarquia das normas (cap. 1)$mat$, $mat$1. Noções gerais sobre a organização do Sistema Financeiro
Nacional

O Sistema Financeiro Nacional abrange três Segmentos:

O primeiro deles é o de moeda, crédito, capitais e câmbio

   Esse segmento lida diretamente com quatro mercados, quais sejam:

- O mercado monetário: que fornece à economia papel-moeda e moeda
escritural, aquela depositada nas contas corrente;

- O mercado de crédito: fornece recursos para financiar o consumo das
pessoas e para o funcionamento das empresas;

[Página 5]

- O mercado de capitais: permite às empresas em geral captar recursos
de terceiros e, portanto, compartilhar ganhos e riscos;

- O mercado de câmbio: que permite, tanto às pessoas quanto às
empresas, a compra e a venda de moedas estrangeiras.

O segundo segmento é o de Seguros Privados:

É o segmento do Sistema Financeiro Nacional para quem busca seguros,
contratos de capitalização e previdência complementar aberta.

- O mercado de seguros privados é o mercado que oferece serviços de
proteção contra riscos.

- A previdência complementar aberta é um tipo de plano para
aposentadoria, poupança ou pensão. Ela funciona à parte do regime geral de
previdência e aceita a participação do público em geral.

- Os contratos de capitalização são acordos em que o contratante
deposita valores podendo recebê-los de volta com juros e concorrer a prêmios.

O terceiro e último segmento é a previdência fechada:

É o segmento dos fundos de pensão, voltados aos funcionários de
empresas e organizações. Trata dos planos de aposentadoria, poupança ou
pensão para funcionários de empresas, servidores públicos e integrantes de
associações ou entidades de classe.

Órgãos Normativos, Órgãos Supervisores e os Operadores

Os Órgãos Normativos são os que determinam as regras gerais para o
bom funcionamento do Sistema Financeiro Nacional. São eles:

O Conselho Monetário Nacional – CMN: é o principal órgão normativo
do Sistema Financeiro Nacional e tem a responsabilidade de formular a política
da moeda e do crédito, objetivando a estabilidade da moeda e o
desenvolvimento econômico e social do País. Ele foi criado pela Lei nº 4.595, de
31 de dezembro de 1964, e efetivamente instituído em 31 de março de 1965,
uma vez que a Lei só entrou em vigor 90 dias após a sua publicação.

[Página 6]

A composição do CMN vem sofrendo algumas alterações ao longo dos
anos. A atual é a seguinte:

-
Ministro da Fazenda, como seu Presidente;
-
Ministro do Planejamento e Orçamento; e
-
Presidente do Banco Central.
Os seus membros reúnem-se uma vez por mês, em calendário
previamente aprovado por eles, para deliberarem sobre assuntos relacionados
às suas competências. Em casos extraordinários pode acontecer mais de uma
reunião no mês. As matérias aprovadas são regulamentadas por meio de
Resoluções CMN, normativo de caráter público, sempre divulgado no Diário
Oficial da União e na página de normativos do Banco Central, e assinado pelo
Presidente do Banco Central.

O Banco Central desempenha o papel de Secretaria-Executiva do
Conselho Monetário, organizando e assessorando suas sessões deliberativas,
preparando os votos que são apreciados pelos Conselheiros, elaborando as atas,
mantendo o arquivo histórico e cuidando da publicação das Resoluções.

O segundo órgão normativo é o Conselho Nacional de Seguros
Privados – CNSP, responsável por fixar as diretrizes e normas da política de
seguros privados. Ele é composto por representantes do Ministério da Fazenda,
do Ministério da Justiça, do Ministério da Previdência Social, da
Superintendência de Seguros Privados, do Banco Central e da Comissão de
Valores Mobiliários. A presidência também é exercida pelo Ministro da Fazenda.

Dentre as funções do CNSP estão: regular a constituição, organização,
funcionamento e fiscalização dos entes que exercem atividades no segmento,
bem como a aplicação das penalidades previstas; fixar as características gerais
dos contratos de seguro, previdência privada aberta, capitalização e resseguro;
estabelecer as diretrizes gerais das operações de resseguro; prescrever os
critérios de constituição das Sociedades Seguradoras, de Capitalização,
Entidades de Previdência Privada Aberta e Resseguradores, com fixação dos
limites legais e técnicos das respectivas operações e disciplinar a corretagem de
seguros e a profissão de corretor.

E, por fim, o terceiro órgão normativo é o Conselho Nacional de
Previdência Complementar – CNPC, que tem a função de regular o regime de
previdência operado pelas entidades fechadas de previdência complementar.

O CNPC é presidido pelo Ministro da Previdência Social e composto por
representantes da Superintendência Nacional de Previdência Complementar

[Página 7]

(Previc), da Casa Civil da Presidência da República, do Ministério da Fazenda, do
Ministério da Gestão e da Inovação, das entidades fechadas de previdência
complementar, dos patrocinadores e instituidores de planos de benefícios das
entidades fechadas de previdência complementar e dos participantes e
assistidos de planos de benefícios das referidas entidades.

Os Órgãos Supervisores trabalham para que os integrantes do sistema
financeiro sigam as regras definidas pelos órgãos normativos.

São eles:

O Banco Central do Brasil - BCB, que também foi criado pela Lei 4.595
de 31 de dezembro de 1964, é o principal executor das orientações do Conselho
Monetário Nacional e responsável por garantir o poder de compra da moeda
nacional, tendo a seu cargo múltiplas atividades, tais como:

• Manter a inflação baixa e estável;

• Assegurar que o Sistema Financeiro seja sólido e eficiente;

• Ser o detentor das reservas internacionais do País;

• Ser o banco dos bancos, mantendo as contas de reserva bancária das
instituições financeiras, monitorando para que as transações financeiras
tenham fluidez e para que essas contas não fechem com saldo negativo;

• Ser o emissor da moeda, gerenciando o meio circulante de forma a
garantir à população o fornecimento adequado de dinheiro em espécie. O
Banco Central comanda a impressão de novas cédulas, que é feita pela
Casa da Moeda, retirando também de circulação as cédulas velhas ou
desgastadas, substituindo-as por novas.

A sede do Banco Central fica em Brasília, com representações nas capitais
dos Estados da Bahia, Ceará, Minas Gerais, Pará, Paraná, Pernambuco, Rio de
Janeiro, Rio Grande do Sul e São Paulo.
Na forma dos arts. 3º e 4º da Lei Complementar nº 179, de 2021, que
estabeleceu a autonomia do Banco Central, sua Diretoria Colegiada é composta
por 9 (nove) membros, sendo um deles o seu Presidente, todos indicados e
nomeados pelo Presidente da República, após aprovação pelo Senado Federal,
entre brasileiros idôneos, de reputação ilibada e de notória capacidade em
assuntos econômico-financeiros ou com comprovados conhecimentos que os
qualifiquem para a função.

[Página 8]

O mandato do Presidente tem duração de 4 (quatro) anos, com início no dia
1º de janeiro do terceiro ano do mandato do Presidente da República e os
mandatos dos Diretores também com duração de 4 (quatro) anos, observa
escalonamento próprio, de forma a evitar a troca simultânea de toda a Diretoria.
Na forma do art. 6º da mesma Lei Complementar, o Banco Central é
considerado uma autarquia de natureza especial, caracterizada pela ausência de
vinculação a Ministério, de tutela ou de subordinação hierárquica, pela autonomia
técnica, operacional, administrativa e financeira, pela investidura a termo de seus
dirigentes e pela estabilidade durante seus mandatos.

 A Missão do Banco Central

De acordo com o Planejamento Estratégico 2026/29, o Banco Central
tem como missão institucional “Garantir a estabilidade de preços, zelar por
um sistema financeiro sólido e eficiente, e fomentar o bem-estar econômico
da sociedade”.

A Comissão de Valores Mobiliários - CVM, criada em 7 de dezembro de
1976 pela Lei 6.385, tem o objetivo de fiscalizar, normatizar, disciplinar e
desenvolver o mercado de valores mobiliários no Brasil. A CVM é uma entidade
autárquica em regime especial, vinculada ao Ministério da Fazenda, com
personalidade jurídica e patrimônio próprios, dotada de autoridade
administrativa independente, ausência de subordinação hierárquica, mandato
fixo e estabilidade de seus dirigentes, e autonomia financeira e orçamentária.

A Superintendência de Seguros Privados – SUSEP, é responsável pelo
controle e fiscalização dos mercados de seguro, previdência privada aberta,
capitalização e resseguro. É uma autarquia, vinculada ao Ministério da Fazenda,
e foi criada pelo Decreto-lei nº 73, de 21 de novembro de 1966.

A Superintendência Nacional de Previdência Complementar - PREVIC
que é uma entidade governamental autônoma constituída sob a forma de
autarquia especial vinculada ao Ministério da Previdência Social, instituída em
2009 pela Lei nº 12.154, com a finalidade de fiscalizar e supervisionar as
entidades fechadas de previdência complementar e de executar políticas para o
regime de previdência complementar.

Os operadores do Sistema Financeiro Nacional, são as instituições
bancárias ou não bancárias, que lidam diretamente com o público, no papel de
intermediários financeiros. São exemplos de operadores: os bancos, as caixas
econômicas, as corretoras de câmbio, as corretoras e distribuidoras de valores
mobiliários, as cooperativas de crédito, as administradoras de consórcios, as

[Página 9]

instituições de pagamento e as bolsas de valores, de mercadorias e futuros.

A hierarquia das normas do Conselho Monetário Nacional e do Banco
Central:

As normas do Conselho Monetário e do Banco Central tiveram suas
nomenclaturas e hierarquia alteradas inicialmente pelo Decreto 10.139, de 2019,
posteriormente substituído pelo Decreto 12.002, de 2024, de forma a serem
consolidadas num único padrão, que teve como objetivo simplificar o arcabouço
regulatório, extinguir normas obsoletas e aumentar a transparência dos órgãos e
entidades do Poder Público.

▪
As Resoluções CMN, traduzem as decisões do Conselho Monetário. Elas
são assinadas pelo Presidente do Banco Central, uma vez que como citado
ele exerce a Secretaria Executiva do Conselho.

▪
As Resoluções BCB, traduzem decisões da Diretoria Colegiada do Banco
Central, normalmente regulamentando as decisões do Conselho
Monetário.

[Página 10]

▪
As Instruções Normativas, regulamentam as Resoluções BCB.

▪
As Portarias BCB, esclarecem dúvidas e prestam informações operacionais
ao Sistema Financeiro Nacional. e

▪
As Resoluções, Portarias e Instruções Normativas Conjuntas, traduzem
decisões conjuntas nesses mesmos níveis.$mat$, 'junho/2026'),
(3, 2, $mat$Resolução BCB 350/2023: atuação do Banco Central no mercado de câmbio$mat$, $mat$Resolução BCB nº 350, de 8 de novembro de 2023
Dispõe sobre a atuação do Banco Central do Brasil no mercado de câmbio.

Art. 1º  A atuação do Banco Central do Brasil no mercado de câmbio observará o
disposto nesta Resolução.
Parágrafo único.  Aplica-se o disposto nesta Resolução às intervenções realizadas
com o uso de instrumentos de atuação do Banco Central do Brasil no mercado de
câmbio brasileiro para fins de implementação da política cambial de que trata a
Resolução BCB nº 76, de 23 de fevereiro de 2021.

Art. 2º  O processo de deliberação para a atuação referida no art. 1º será pautado
pelos princípios da eficiência e da informalidade administrativa, prestigiando-se a
tempestividade e a eficácia das intervenções e a certeza e segurança quanto ao
conteúdo das deliberações.

Parágrafo único.  As comunicações entre as autoridades responsáveis pela atuação
referida no art. 1º adotarão formas simples, suficientes para propiciar adequado

[Página 97]

grau de certeza e segurança, a exemplo de contatos telefônicos, mensagens
eletrônicas e interações presenciais.

Art. 3º  Os Departamentos das Reservas Internacionais (Depin) e de Operações do
Mercado Aberto (Demab) manterão permanente monitoramento dos mercados,
visando a subsidiar a tomada de decisões para a atuação prevista no art. 1º.
Parágrafo único.  Eventuais condições adversas ou disfuncionalidades detectadas
pelo Depin ou pelo Demab nas condições de liquidez e de formação de preços no
mercado de câmbio, incluindo fortes movimentos na cotação do real, acionamento
de mecanismos de limitação de perdas por participantes do mercado (stop-loss) ou
atingimento de limites máximos de oscilação intradiária (circuit breaker), entre
outros, deverão ser comunicadas de imediato ao Diretor de Política Monetária.
Art. 4º  O Diretor de Política Monetária, no exercício de suas atribuições
regimentais, fixará os parâmetros para as intervenções do Banco Central do Brasil
no mercado de câmbio, observando eventuais diretrizes estratégicas formuladas
pela Diretoria Colegiada.
§ 1º  As intervenções referidas neste artigo serão autorizadas caso a caso pelo
Diretor de Política Monetária e iniciadas mediante a expedição de comunicado, na
forma das atribuições regimentais.
§ 2º  Após o recebimento das propostas de intervenção conduzidas pelo Banco
Central do Brasil, o Diretor de Política Monetária tomará as decisões necessárias
para a apuração do resultado, a exemplo de montantes a serem contratados,
distribuição de montantes por vencimento e taxas de corte, adotando as cautelas
devidas para preservar sigilo sobre a identidade dos participantes.
§ 3º  Após a apuração, os resultados das intervenções serão divulgados por meio
de comunicados, além de informados à Diretoria Colegiada por meio de mensagem
eletrônica.

Art. 5º  Ao identificar condições adversas ou disfuncionalidades nas condições de
liquidez e de formação de preços no mercado de câmbio, incluindo fortes
movimentos na cotação do real, acionamento de mecanismos de limitação de
perdas por participantes do mercado (stop-loss) ou atingimento de limites
máximos de oscilação intradiária (circuit breaker), entre outros, o Diretor de
Política Monetária poderá solicitar ao Presidente a convocação de reunião
extraordinária da Diretoria Colegiada, objetivando discutir a adoção de medidas
necessárias ao funcionamento regular do mercado de câmbio.

Art. 6º  O Diretor de Política Monetária deverá informar ao Presidente sempre que
o montante para as intervenções do Banco Central do Brasil, ao longo de cinco dias
úteis, se aproximar de 2,5% (dois inteiros e cinco décimos por cento) do estoque
total de reservas internacionais apurado no último balancete do Banco Central do
Brasil, o qual convocará reunião extraordinária da Diretoria Colegiada a fim de

[Página 98]

discutir a adoção de medidas necessárias ao funcionamento regular do mercado
de câmbio.

Art. 7º  Na hipótese de impedimento do Diretor de Política Monetária, ainda que
circunstancial, sem que haja substituto designado, as comunicações referidas
nesta Resolução serão dirigidas ao Diretor de Política Econômica ou a seu
substituto designado, competindo-lhe adotar as decisões e providências
necessárias para a tempestiva e eficaz atuação do Banco Central do Brasil no
mercado de câmbio, enquanto perdurar o impedimento do Diretor de Política
Monetária.
Parágrafo único.  Havendo impedimento simultâneo dos Diretores de Política
Monetária e de Política Econômica e de seus substitutos, o Presidente designará
outro membro da Diretoria Colegiada para os propósitos deste artigo.$mat$, 'junho/2026'),
(3, 3, $mat$Resolução BCB 519/2025: processos de autorização de corretoras, DTVMs e SPSAVs$mat$, $mat$Resolução BCB n° 519, de 10 de novembro de 2025

Disciplina os processos de autorização relacionados ao funcionamento das
sociedades corretoras de câmbio, das sociedades corretoras de títulos e valores
mobiliários, das sociedades distribuidoras de títulos e valores mobiliários e das
sociedades prestadoras de serviços de ativos virtuais.

CAPÍTULO I
DO OBJETO E DO ÂMBITO DE APLICAÇÃO
Art. 1º  Esta Resolução disciplina os processos de autorização relacionados ao
funcionamento das seguintes instituições:
I - sociedades corretoras de câmbio;
II - sociedades corretoras de títulos e valores mobiliários;
III - sociedades distribuidoras de títulos e valores mobiliários; e
IV - sociedades prestadoras de serviços de ativos virtuais.
CAPÍTULO II
DOS REQUISITOS

Art. 2º  São requisitos para as autorizações de que trata esta Resolução:
I - capacidade econômico-financeira dos controladores, de forma isolada ou em
conjunto, compatível com o capital necessário à estruturação e à operação da
instituição, bem como às contingências decorrentes da dinâmica do mercado;

[Página 99]

II - origem lícita dos recursos utilizados na integralização do capital social, na
aquisição de controle e de participação qualificada;
III - viabilidade econômico-financeira do empreendimento;
IV - compatibilidade da infraestrutura de tecnologia da informação com a
complexidade e os riscos do negócio;
V - compatibilidade da estrutura de governança corporativa com a complexidade e
os riscos do negócio;
VI - reputação ilibada dos administradores, dos controladores e dos detentores de
participação qualificada, no caso de pessoas naturais;
VII - conhecimento, pela administração, do ramo do negócio, do segmento em que
a instituição pretende operar, da dinâmica de mercado, das fontes de recursos
operacionais, do gerenciamento das atividades e dos riscos a elas associados;
VIII - capacitação técnica dos administradores, compatível com as funções a serem
exercidas no curso do mandato;
IX - atendimento aos requerimentos mínimos de capital e de patrimônio previstos
na regulamentação em vigor; e
X - informação do endereço das instalações físicas da sede da instituição.
§ 1º  Para fins do disposto nesta Resolução, a administração compreende os sócios
administradores, os diretores e os membros do conselho de administração, se
houver.
§ 2º  Na comprovação do requisito referido no inciso I do caput, o Banco Central
do Brasil poderá considerar, subsidiariamente, nos pedidos de autorização de
sociedade prestadora de serviços de ativos virtuais em atividade, o patrimônio
líquido, a obtenção de lucro recorrente realizado nos últimos cinco anos e outras
situações, a critério dessa Autarquia.
§ 3º  A instituição interessada na autorização deve elaborar e manter, à disposição
do Banco Central do Brasil, plano de negócios atualizado.
§ 4º  O Banco Central do Brasil poderá exigir, antes ou depois da expedição das
autorizações disciplinadas nesta Resolução, a apresentação, no todo ou em parte,
do plano de negócios referido no § 3º.
§ 5º  Na comprovação dos requisitos referidos no caput, o Banco Central do Brasil
poderá requerer certificação técnica ou avaliação emitida por empresa qualificada
independente.
§ 6º  O endereço de que trata o inciso X do caput deve ser de uso efetivo e exclusivo
da instituição, sendo vedada a indicação de endereço de coworking, de escritório
virtual ou de outro espaço compartilhado como sede da instituição, exceto no caso
de instituições que integrem o mesmo conglomerado.

[Página 100]

CAPÍTULO III
DAS AUTORIZAÇÕES
Art. 3º  Dependem de autorização do Banco Central do Brasil:
I - o funcionamento da instituição, condicionado ao cumprimento dos requisitos
previstos no art. 2º;
II - a mudança de modalidade de sociedade prestadora de serviços de ativos
virtuais, condicionada ao cumprimento dos requisitos previstos no art. 2º, caput,
incisos III, IV, V, VII e IX;
III - a transferência ou alteração de controle societário, condicionada ao
cumprimento dos requisitos previstos no art. 2º, caput, incisos I, II e VI, e das
condições previstas nos Capítulos IV e V, bem como do requisito previsto no art.
2º, caput, inciso III, nos casos de mudança de natureza estratégica ou operacional;
IV - a fusão, cisão ou incorporação de instituição relacionada no art. 1º,
condicionadas ao cumprimento dos requisitos previstos no art. 2º, caput, incisos III
e IX;
V - a transformação societária;
VI - a posse e o exercício de eleitos ou nomeados para cargos de administração,
condicionados ao cumprimento dos requisitos previstos no art. 2º, caput, incisos VI
e VIII, e das condições previstas no Capítulo V;
VII - a alteração do valor do capital social, condicionada ao cumprimento do
requisito previsto no art. 2º, caput, inciso II, em caso de aumento, ou dos requisitos
previstos no art. 2º, caput, incisos III e IX, em caso de redução do capital;
VIII - a mudança da denominação social; e
IX - a mudança de objeto social para algum tipo de instituição previsto nesta
Resolução, condicionada ao cumprimento dos requisitos previstos no art. 2º, caput,
incisos III e IX, observada a regulamentação aplicável ao tipo de instituição
resultante, conforme o caso.
§ 1º  A autorização prevista no inciso VII do caput não se aplica aos aumentos de
capital integralizados com recursos originários de:
I - lucros acumulados;
II - reservas de capital e de lucros; ou
III - créditos a acionistas a título de remuneração do capital.
§ 2º  O Banco Central do Brasil, para avaliação do cumprimento dos requisitos
previstos no art. 2º, caput, incisos I, II e VI, poderá requerer aos integrantes do
grupo de controle, aos detentores de participação qualificada e aos eleitos ou
nomeados para cargos de administração, autorização expressa para:

[Página 101]

I - a Secretaria da Receita Federal do Brasil fornecer ao Banco Central do Brasil as
cópias das declarações de rendimentos, de bens e direitos e de dívidas e ônus reais
relativas aos três últimos exercícios fiscais, para uso exclusivo no processo de
autorização de que trata o caput; e
II - o Banco Central do Brasil acessar informações a seu respeito constantes de
qualquer sistema público ou privado de cadastro e informações, inclusive
processos e procedimentos judiciais ou administrativos e inquéritos policiais.
§ 3º  O Banco Central do Brasil poderá condicionar as autorizações de que tratam
os incisos II e IX do caput à liquidação das operações passivas não autorizadas para
a modalidade pretendida.
§ 4º  A exigência de autorização prevista no inciso III do caput não se aplica às
transferências de controle societário para pessoas jurídicas em que não ocorra
alteração no quadro de controladores finais da instituição.
Art. 4º  O Banco Central do Brasil, considerando o objeto da autorização, o porte
da instituição e a complexidade do negócio, divulgará os procedimentos, os
documentos e as informações exigidos nos processos de autorização de que trata
esta Resolução, bem como os respectivos prazos, tendo em vista o atendimento
aos requisitos relacionados a cada processo de autorização específico.
Art. 5º  O Banco Central do Brasil, antes ou depois da expedição das autorizações
previstas no art. 3º, poderá:
I - requisitar quaisquer documentos e informações adicionais que julgar
necessários, bem como solicitá-los a outros órgãos da administração pública e a
autoridades no exterior; e
II - convocar para entrevista os controladores, os detentores de participação
qualificada e os administradores.
Art. 6º  O Banco Central do Brasil divulgará, com vistas a possibilitar a
manifestação do público em geral quanto a eventuais objeções, as seguintes
informações referentes a pedidos de interesse da instituição:
I - o nome:
a) das pessoas interessadas em assumir a condição de controlador; e
b) dos eleitos ou nomeados para cargos de administração; e
II - os pedidos de cancelamento de autorização para funcionamento.
§ 1º  A divulgação de que trata o inciso I do caput será restrita às pessoas cujo
nome não tenha sido anteriormente aprovado pelo Banco Central do Brasil.
§ 2º  Considerando a natureza e o porte da instituição, bem como a complexidade
e os riscos envolvidos na autorização, o Banco Central do Brasil poderá divulgar
informações adicionais às previstas neste artigo, inclusive as relativas às pessoas
cujo nome tenha sido anteriormente aprovado pelo Banco Central do Brasil.

[Página 102]

§ 3º  Os prazos para apresentação de objeções por parte do público em decorrência
da divulgação das informações de que trata o caput serão definidos pelo Banco
Central do Brasil em ato normativo complementar.
CAPÍTULO IV
DO CONTROLE SOCIETÁRIO E DA PARTICIPAÇÃO QUALIFICADA
Art. 7º  Para os fins desta Resolução, entende-se como:
I - controlador: pessoa que, individualmente ou em conjunto com demais
integrantes de grupo de controle de que participe, detenha direitos de sócio
correspondentes à maioria do capital votante da instituição:
a) no caso de pessoa natural, de forma direta ou indireta; ou
b) no caso de pessoa jurídica, de forma direta ou, se de forma indireta, desde que:
1. figure no último nível dos ramos da cadeia de controle da instituição; e
2. seus controladores não sejam passíveis de identificação na forma prevista neste
inciso;
II - grupo de controle: grupo de pessoas vinculadas por acordo de votos ou sob
controle comum que assumem a condição de controlador da instituição, na forma
definida no inciso I;
III - cadeia de controle: conjunto de pessoas jurídicas por intermédio do qual o
controle da instituição é exercido;
IV - integrante da cadeia de controle: pessoa jurídica integrante do conjunto de
pessoas por intermédio do qual o controle da instituição é exercido, exceto a
pessoa jurídica referida no inciso I, alínea “b”; e
V - detentor de participação qualificada: fundo de investimento ou pessoa natural
ou jurídica, não controladora e não integrante da cadeia de controle da instituição,
que detenha:
a) participação direta equivalente a 15% (quinze por cento) ou mais do capital
votante da instituição, de pessoa jurídica controladora ou de integrante da cadeia
de controle da instituição;
b) participação direta equivalente a 10% (dez por cento) ou mais do capital total
da instituição, de pessoa jurídica controladora ou de integrante da cadeia de
controle da instituição, quando esse capital não consistir integralmente de capital
votante; ou
c) controle de pessoa jurídica detentora da participação prevista na alínea "a" ou
na alínea "b".
§ 1º  Considera-se no último nível de ramo da cadeia de controle da instituição, nos
casos de participação direta ou indireta, a instituição financeira ou assemelhada
sediada no exterior responsável pela consolidação global do grupo financeiro.

[Página 103]

§ 2º  As definições de controlador e de detentor de participação qualificada
aplicam-se aos usufrutuários do direito de voto.
§ 3º  Nos casos em que o controle da sociedade não seja identificado segundo os
critérios mencionados nos incisos I, II e III do caput, o Banco Central do Brasil
poderá utilizar outros elementos para identificar os controladores, entre eles:
I - a maioria de votos nas deliberações da reunião ou assembleia e o poder de eleger
a maioria dos administradores; ou
II - a efetividade na condução dos negócios sociais.
§ 4º  No caso de participação qualificada detida por fundo de investimento, as
disposições aplicáveis à pessoa natural ou jurídica detentora de participação
qualificada previstas nesta Resolução poderão ser extensíveis aos quotistas do
fundo de investimento que efetivamente detenham poderes para condução de sua
atuação, nos termos estabelecidos pelo Banco Central do Brasil.
§ 5º  O Banco Central do Brasil poderá exigir a celebração de acordo de acionistas
ou de quotistas, contemplando a expressa definição do controle societário, direto
ou indireto.
§ 6º  Para fins do disposto neste artigo, será considerada a eventual atribuição de
voto plural a uma ou mais classes de ações ordinárias.
§ 7º  Não são admitidos fundos de investimento como controladores ou
integrantes de grupo de controle das instituições referidas no art. 1º.
Art. 8º  A participação societária direta que implique controle das instituições
referidas no art. 1º somente poderá ser exercida por:
I - pessoas naturais;
II - instituições autorizadas a funcionar pelo Banco Central do Brasil;
III - instituições financeiras ou assemelhadas sediadas no exterior; ou
IV - pessoas jurídicas sediadas no país que tenham por objeto social exclusivo a
participação societária em instituições autorizadas a funcionar pelo Banco Central
do Brasil.
§ 1º  Admite-se a participação, no controle das instituições de que trata o art. 1º,
de pessoas jurídicas sem fins lucrativos que, na data de entrada em vigor desta
Resolução, já participem do controle de instituições autorizadas a funcionar pelo
Banco Central do Brasil.
§ 2º  O disposto no caput deste artigo não se aplica às instituições de que trata o
art. 1º, caput, incisos I, II e III, constituídas antes de 28 de novembro de 2002,
enquanto perdurar a estrutura de controle existente naquela data.

[Página 104]

CAPÍTULO V
DA POSSE E DO EXERCÍCIO DE CARGOS DE ADMINISTRAÇÃO E DA ASSUNÇÃO
DA CONDIÇÃO DE INTEGRANTE DO GRUPO DE CONTROLE OU DE DETENTOR DE
PARTICIPAÇÃO QUALIFICADA
Art. 9º  Na comprovação do cumprimento do requisito de reputação ilibada,
mencionado no art. 2º, caput, inciso VI, deverá ser considerada a existência de:
I - processo criminal ou inquérito policial;
II - processo judicial ou administrativo que tenha relação com o Sistema Financeiro
Nacional, o Sistema de Consórcios, o Sistema de Pagamentos Brasileiro ou a
prestação de serviços de ativos virtuais;
III - processo relativo à insolvência, liquidação, intervenção, falência ou
recuperação judicial;
IV - inadimplemento de obrigações; e
V - outras situações, ocorrências ou circunstâncias análogas.
Parágrafo único.  Na análise das situações e ocorrências previstas no caput, serão
consideradas a relevância, a gravidade, a recorrência e as circunstâncias de cada
caso.
Art. 10.  A comprovação do atendimento do requisito de capacitação técnica dos
administradores, mencionado no art. 2º, caput, inciso VIII, envolve as
competências e as qualificações necessárias ao exercício das funções, compatíveis
com a natureza, o porte, a complexidade e os riscos incorridos pela instituição.
Parágrafo único.  A comprovação de capacitação técnica mencionada no caput é
dispensada nos casos de administrador com mandato em vigor na própria
instituição ou em outra instituição integrante de conglomerado prudencial de que
participe, desde que anteriormente autorizado pelo Banco Central do Brasil, salvo
determinação contrária dessa Autarquia.
Art. 11.  São condições para o exercício dos cargos de administração e para a
assunção da condição de controlador ou de detentor de participação qualificada
nas instituições referidas no art. 1º, além de outras exigidas pela legislação e pela
regulamentação em vigor:
I - ser residente no país, para os cargos de direção;
II - não estar impedido por lei especial, nem condenado por crime falimentar, de
sonegação fiscal, de prevaricação, de corrupção ativa ou passiva, de concussão, de
peculato, contra a economia popular, a fé pública, a propriedade ou o Sistema
Financeiro
Nacional,
nem
condenado
a
pena
que
vede,
ainda
que
temporariamente, o acesso a cargos públicos;
III - não estar declarado inabilitado ou suspenso para o exercício de cargos em
órgãos estatutários ou contratuais em instituições autorizadas a funcionar pelo

[Página 105]

Banco Central do Brasil ou em entidades de previdência complementar, sociedades
seguradoras, sociedades de capitalização, companhias abertas ou entidades
sujeitas à supervisão da Comissão de Valores Mobiliários;
IV - não estar declarado falido ou insolvente; e
V - não ter seu nome sido objeto de prévia decisão de indeferimento ou de revisão
de decisão autorizativa em razão da apresentação de declaração falsa, omissa ou
discrepante dos correspondentes fatos em pedido de autorização perante o Banco
Central do Brasil, nos três anos anteriores à instrução do pedido de autorização em
análise.
Art. 12.  As instituições referidas no art. 1º que forem constituídas sob a forma de
sociedade limitada devem prever em seu contrato social que o mandato dos
administradores eleitos ou nomeados:
I - será por prazo determinado, não superior a quatro anos, admitida a recondução;
e
II - se estenderá até a posse dos seus substitutos.
Art. 13.  Caso o eleito ou nomeado para cargo de administração não seja
autorizado pelo Banco Central do Brasil, inclusive após a posse ou início do
exercício, a sociedade deverá, no prazo de trinta dias, contado da data em que a
decisão de indeferimento se tornar definitiva, realizar a eleição ou a nomeação do
substituto da pessoa não aprovada.
Parágrafo único.  A determinação prevista no caput fica dispensada no caso de ser
atendida a quantidade mínima de membros para os respectivos cargos prevista no
estatuto ou contrato social.
Art. 14.  O afastamento temporário de ocupantes de cargos de administração
determinado antes da instauração ou durante a tramitação de processo
administrativo sancionador não exclui o afastado do alcance das vedações
aplicáveis aos ocupantes em exercício.
Art. 15.  O Banco Central do Brasil poderá determinar o afastamento de
administradores com mandato em vigor, caso sejam constatadas, a qualquer
tempo, circunstâncias que caracterizem o descumprimento do requisito referido
no art. 2º, caput, inciso VI, e das condições previstas no art. 11 desta Resolução.
CAPÍTULO VI
DO ARQUIVAMENTO, DO INDEFERIMENTO E DA REVISÃO DAS AUTORIZAÇÕES
Art. 16.  Com relação aos pedidos de autorização de que trata esta Resolução, o
Banco Central do Brasil poderá:
I - arquivar, sem apreciação do mérito do pedido, se:

[Página 106]

a) verificar que o objeto ou os elementos que servem de base para o pedido foram
alterados no curso do processo;
b) houver descumprimento dos prazos previstos na regulamentação em vigor;
c) identificar que não foram atendidas as exigências para complementar a
instrução do processo no prazo estabelecido;
d) deixarem os controladores, os detentores de participação qualificada ou os
administradores de atender a convocação do Banco Central do Brasil para
entrevista; ou
e) estiver a instrução em desacordo com o formato exigido na regulamentação
vigente; ou
II - indeferir, se vier a apurar:
a) circunstância que possa afetar a reputação dos administradores, dos
controladores ou dos detentores de participação qualificada;
b) falsidade ou omissão nas declarações e nos documentos apresentados na
instrução dos processos ou discrepância entre eles e os fatos ou dados apurados
na análise; ou
c) não atendimento a qualquer dos requisitos ou condições estabelecidas nesta
Resolução ou a não comprovação, pelos interessados, do atendimento desses
requisitos ou condições.
Parágrafo único.  Nos casos de que trata o inciso II do caput, o Banco Central do
Brasil, antes da decisão, poderá conceder prazo aos interessados para
manifestação.
Art. 17.  O Banco Central do Brasil poderá rever a decisão de aprovação ou de
autorização, considerando a relevância dos fatos, tendo por base as circunstâncias
de cada caso e o interesse público, caso verifique:
I - falsidade ou omissão nas declarações e nos documentos apresentados na
instrução dos processos ou discrepância entre eles e os fatos ou dados apurados;
ou
II - circunstâncias preexistentes à decisão capazes de afetar a avaliação relativa ao
atendimento dos requisitos e das condições para as aprovações e autorizações.
§ 1º  No caso de transferência de controle, de reorganização societária, da
assunção da condição de controlador ou de detentor de participação qualificada e
na ocorrência das situações previstas no caput, o Banco Central do Brasil poderá
determinar que a operação seja regularizada, inclusive mediante o seu
desfazimento ou a alienação da participação.
§ 2º  Nas hipóteses descritas no caput, o Banco Central do Brasil deverá notificar a
instituição para se manifestar sobre a irregularidade apurada.
§ 3º  O órgão de registro competente será comunicado da medida adotada pelo
Banco Central do Brasil.

[Página 107]

Art. 18.  No caso de indeferimento ou de arquivamento do pedido de autorização
para funcionamento ao qual não caiba mais recurso, a sociedade prestadora de
serviços de ativos virtuais que já esteja prestando serviços de ativos virtuais deverá,
no prazo de trinta dias contados a partir do recebimento da notificação da decisão
do Banco Central do Brasil:
I - cessar a prestação de serviços de ativos virtuais e de outros serviços sujeitos a
autorização do Banco Central do Brasil;
II - comunicar o encerramento da prestação de serviços de ativos virtuais a clientes,
usuários e demais partes interessadas por meio dos mesmos canais habitualmente
empregados para a publicidade de seus serviços e produtos, com indicação clara e
destacada dos procedimentos e prazos para a devolução de ativos virtuais e a
liquidação de operações;
III - devolver os ativos virtuais de seus clientes e usuários, transferindo-os para
instituições habilitadas a prestar serviços de ativos virtuais no Brasil, indicadas e
em nome dos respectivos clientes e usuários; e
IV - devolver os recursos financeiros de seus clientes e usuários, transferindo-os
para contas de pagamento ou contas de depósito de titularidade desses clientes e
usuários mantidas em instituições autorizadas a funcionar pelo Banco Central do
Brasil.
CAPÍTULO VII
DO CANCELAMENTO DE AUTORIZAÇÕES
Art. 19.  O cancelamento de autorização para funcionamento ocorrerá nas
seguintes hipóteses:
I - a pedido da instituição; e
II - de ofício, pelo Banco Central do Brasil.
§ 1º  Na hipótese de extinção da instituição decorrente de fusão, cisão total ou
incorporação, ficam dispensados os procedimentos relativos ao cancelamento de
autorização para funcionamento, desde que a sociedade resultante ou sucessora
seja instituição autorizada a funcionar pelo Banco Central do Brasil.
§ 2º  O Banco Central do Brasil poderá condicionar o cancelamento de que trata o
inciso I do caput à liquidação ou transferência das operações privativas ou
permitidas à instituição em razão da respectiva autorização.
§ 3º  A dissolução da sociedade ou a mudança de seu objeto social que resulte na
sua descaracterização como instituição autorizada a funcionar pelo Banco Central
do Brasil implica o cancelamento da respectiva autorização para funcionamento,
na forma do inciso I do caput.

[Página 108]

Art. 20.  A sociedade deve divulgar a seus clientes, por meio de seu sítio na
internet, aplicativo em dispositivos móveis e em suas dependências, conforme
aplicável, que pretende ingressar com pedido de cancelamento de autorização
para funcionamento, com antecedência mínima de trinta dias da data do referido
pedido.
Art. 21.  O Banco Central do Brasil poderá efetuar o cancelamento de que trata o
art. 19, caput, inciso II, quando constatada, a qualquer tempo, uma ou mais das
seguintes situações:
I - falta de prática habitual da atividade objeto da autorização;
II - não localização da instituição no endereço informado ao Banco Central do
Brasil;
III - interrupção, por mais de quatro meses, sem justificativa, do envio ao Banco
Central do Brasil dos demonstrativos, mapas e informações exigidos pela
regulamentação em vigor; e
IV - descumprimento do plano de negócios durante o seu período de abrangência,
de forma insuficientemente justificada, a critério do Banco Central do Brasil.
§ 1º  O Banco Central do Brasil, previamente ao cancelamento previsto neste
artigo, deverá:
I - divulgar ao público sua intenção de cancelar a respectiva autorização, com vistas
à eventual apresentação de objeções no prazo de trinta dias;
II - notificar a instituição para se manifestar sobre a intenção de cancelamento; e
III - considerar os riscos do cancelamento para a estabilidade do Sistema Financeiro
Nacional, para o Sistema de Pagamentos Brasileiro, para a prestação de serviços
de ativos virtuais, para a poupança popular e para os credores operacionais da
instituição.
§ 2º  Efetivado o cancelamento de que trata este artigo, o Banco Central do Brasil
comunicará esse fato ao órgão de registro competente.
§ 3º  No caso de instituição submetida ao regime de liquidação extrajudicial, o
cancelamento previsto neste artigo ocorrerá no encerramento do regime, exceto
na hipótese de transferência do controle societário da instituição.
CAPÍTULO VIII
DAS COMUNICAÇÕES
Art. 22.  Devem ser comunicados ao Banco Central do Brasil:
I - a assunção da condição de detentor de participação qualificada;
II - a alteração da estrutura de cargos de administração prevista no estatuto ou
contrato social da sociedade; e

[Página 109]

III - os aumentos de capital de que trata o art. 3º, § 1º.
§ 1º  Na ocorrência da situação descrita no inciso I do caput, o Banco Central do
Brasil poderá, no prazo de sessenta dias da comunicação, exigir a comprovação do
cumprimento dos requisitos previstos no art. 2º, caput, incisos II e VI, e das
condições de que trata o art. 11.
§ 2º  Examinados os aspectos da situação referida no inciso I do caput e constatado
o descumprimento dos requisitos aplicáveis, o Banco Central do Brasil poderá
determinar o seu desfazimento ou a alienação da participação qualificada.
CAPÍTULO IX
DISPOSIÇÕES GERAIS
Art. 23.  O Banco Central do Brasil, na análise dos processos de que trata esta
Resolução, considerando as circunstâncias de cada caso concreto e o contexto dos
fatos, poderá dispensar, excepcionalmente e diante de interesse público
devidamente justificado, o cumprimento dos requisitos e das condições
estabelecidas para o ingresso na condição de controlador das instituições de que
trata o art. 1º ou para o exercício dos cargos de administração.
Art. 24.  As instituições referidas no art. 1º que forem constituídas sob a forma de
sociedade limitada devem prever, em seu contrato social, a observância supletiva
da Lei nº 6.404, de 15 de dezembro de 1976, nos termos do parágrafo único do art.
1.053 da Lei nº 10.406, de 10 de janeiro de 2002 – Código Civil, inclusive no que
diz respeito à retenção de lucros e à constituição, à reversão e à utilização de
reservas.
Art. 25.  O Banco Central do Brasil poderá realizar inspeção pré-operacional na
requerente ou interessada, a fim de avaliar a compatibilidade entre a estrutura
organizacional implementada e os requisitos previstos no art. 2º, caput, incisos III
a V.
Parágrafo único.  Constatada incompatibilidade entre a estrutura organizacional
existente e os requisitos previstos no art. 2º, caput, incisos III a IV, o Banco Central
do Brasil determinará prazo para correção, após o qual, em caso de
desatendimento, indeferirá o pedido.
Art. 26.  O processo de autorização para funcionamento da sociedade prestadora
de serviços de ativos virtuais que, na data da entrada em vigor desta Resolução,
estiver em atividade nos termos do art. 9º da Lei nº 14.478, de 21 de dezembro de
2022, será conduzido em duas fases, estruturadas da seguinte forma:
I - fase 1:
a) análise da comprovação de que a sociedade referida no caput estava em
atividade na data da entrada em vigor desta Resolução e da disciplina específica

[Página 110]

que trata da constituição e do funcionamento das sociedades prestadoras de
serviços de ativos virtuais;
b) análise do atendimento ao requisito previsto no art. 2º, caput, inciso VI, e às
condições previstas no Capítulo V desta Resolução, relativamente aos
controladores e aos detentores de participação qualificada; e
c) análise do atendimento ao requisito previsto no art. 2º, caput, inciso IX, desta
Resolução.
II - fase 2: análise do atendimento aos demais requisitos dispostos no art. 2º desta
Resolução.
§ 1º  Para fins do disposto no inciso I, alínea “c”, do caput, o Banco Central do
Brasil poderá exigir a apresentação de demonstrações financeiras auditadas da
requerente ou interessada.
§ 2º Na fase 2 de que trata o inciso II do caput, o Banco Central do Brasil poderá
solicitar a atualização dos documentos que comprovem o atendimento dos
requisitos e condições mencionados no inciso I, alíneas “b” e "c", do caput, com
vistas à análise da manutenção desse atendimento no curso do processo.
Art. 27.  Aplica-se o disposto nesta Resolução aos pedidos de autorização
protocolizados no Banco Central do Brasil a partir de sua vigência.
CAPÍTULO X
DISPOSIÇÕES FINAIS
Art. 28.  Esta Resolução entra em vigor em 2 de fevereiro de 2026.$mat$, 'junho/2026'),
(2, 1, $mat$Sigilo bancário: Lei Complementar 105/2001 (cap. 2)$mat$, $mat$2. O sigilo bancário (uma questão muito importante e que precisa
ser bem compreendida por todos que trabalham em instituições
financeiras):

O sigilo bancário é regido pela Lei Complementar nº 105, de 10 de janeiro
de 2001:

Art. 1º As instituições financeiras conservarão sigilo em suas operações ativas e
passivas e serviços prestados (Pela Resolução CMN 5.280, de 27/02/26, as
SPSAVs são consideradas instituições financeiras para os fins desta Lei).
.....
§ 3º Não constitui violação do dever de sigilo:

I – a troca de informações entre instituições financeiras, para fins cadastrais,
inclusive por intermédio de centrais de risco, observadas as normas baixadas
pelo Conselho Monetário Nacional e pelo Banco Central do Brasil;

II - o fornecimento de informações constantes de cadastro de emitentes de
cheques sem provisão de fundos e de devedores inadimplentes, a entidades de
proteção ao crédito, observadas as normas baixadas pelo Conselho Monetário
Nacional e pelo Banco Central do Brasil;

III – o fornecimento das informações de que trata o § 2º do art. 11 da Lei no
9.311, de 24 de outubro de 1996;

IV – a comunicação, às autoridades competentes, da prática de ilícitos penais
ou administrativos, abrangendo o fornecimento de informações sobre
operações que envolvam recursos provenientes de qualquer prática criminosa;

V – a revelação de informações sigilosas com o consentimento expresso dos
interessados;

[Página 11]

VI – a prestação de informações nos termos e condições estabelecidos nos
artigos 2º, 3º, 4º, 5º, 6º, 7º e 9 desta Lei Complementar.

VII – o fornecimento de dados financeiros e de pagamentos, relativos a
operações de crédito e obrigações de pagamento adimplidas ou em andamento
de pessoas naturais ou jurídicas, a gestores de bancos de dados, para formação
de histórico de crédito, nos termos de lei específica.
§ 4º A quebra de sigilo poderá ser decretada, quando necessária para apuração
de ocorrência de qualquer ilícito, em qualquer fase do inquérito ou do processo
judicial, e especialmente nos seguintes crimes:

I – de terrorismo;
II – de tráfico ilícito de substâncias entorpecentes ou drogas afins;
III – de contrabando ou tráfico de armas, munições ou material destinado
a sua produção;
IV – de extorsão mediante sequestro;
V – contra o sistema financeiro nacional;
VI  - contra a Administração Pública;
VII – contra a ordem tributária e a previdência social;
VIII - lavagem de dinheiro ou ocultação de bens, direitos e valores;
IX – praticado por organização criminosa.

Art. 2º O dever de sigilo é extensivo ao Banco Central do Brasil, em relação às
operações que realizar e às informações que obtiver no exercício de suas
atribuições.

§ 1º O sigilo, inclusive quanto a contas de depósitos, aplicações e investimentos
mantidos em instituições financeiras, não pode ser oposto ao Banco Central do
Brasil:

I – no desempenho de suas funções de fiscalização, compreendendo a apuração,
a qualquer tempo, de ilícitos praticados por controladores, administradores,
membros de conselhos estatutários, gerentes, mandatários e prepostos de
instituições financeiras;

II – ao proceder a inquérito em instituição financeira submetida a regime
especial.

§ 2º As comissões encarregadas dos inquéritos a que se refere o inciso II do § 1o
poderão examinar quaisquer documentos relativos a bens, direitos e obrigações
das instituições financeiras, de seus controladores, administradores, membros

[Página 12]

de conselhos estatutários, gerentes, mandatários e prepostos, inclusive contas
correntes e operações com outras instituições financeiras.

§ 3º O disposto neste artigo aplica-se à Comissão de Valores Mobiliários, quando
se tratar de fiscalização de operações e serviços no mercado de valores
mobiliários, inclusive nas instituições financeiras que sejam companhias abertas.

§ 4º O Banco Central do Brasil e a Comissão de Valores Mobiliários, em suas
áreas de competência, poderão firmar convênios:

I - com outros órgãos públicos fiscalizadores de instituições financeiras,
objetivando a realização de fiscalizações conjuntas, observadas as respectivas
competências;

II - com bancos centrais ou entidades fiscalizadoras de outros países, objetivando:

a) a fiscalização de filiais e subsidiárias de instituições financeiras
estrangeiras, em funcionamento no Brasil e de filiais e subsidiárias, no exterior,
de instituições financeiras brasileiras;

b) a cooperação mútua e o intercâmbio de informações para a
investigação de atividades
ou
operações
que
impliquem
aplicação,
negociação, ocultação ou transferência de ativos financeiros e de valores
mobiliários relacionados com a prática de condutas ilícitas.

§ 5º O dever de sigilo de que trata esta Lei Complementar estende-se aos órgãos
fiscalizadores mencionados no § 4º e a seus agentes.

§ 6º O Banco Central do Brasil, a Comissão de Valores Mobiliários e os demais
órgãos de fiscalização, nas áreas de suas atribuições, fornecerão ao Conselho de
Controle de Atividades Financeiras – COAF, de que trata o art. 14 da Lei no 9.613,
de 3 de março de 1998, as informações cadastrais e de movimento de valores
relativos às operações previstas no inciso I do art. 11 da referida Lei.

Art. 3º Serão prestadas pelo Banco Central do Brasil, pela Comissão de Valores
Mobiliários e pelas instituições financeiras as informações ordenadas pelo Poder
Judiciário, preservado o seu caráter sigiloso mediante acesso restrito às partes,
que delas não poderão servir-se para fins estranhos à lide.

§ 1º Dependem de prévia autorização do Poder Judiciário a prestação de
informações e o fornecimento de documentos sigilosos solicitados por comissão
de inquérito administrativo destinada a apurar responsabilidade de servidor
público por infração praticada no exercício de suas atribuições, ou que tenha

[Página 13]

relação com as atribuições do cargo em que se encontre investido.

§ 2º Nas hipóteses do § 1o, o requerimento de quebra de sigilo independe da
existência de processo judicial em curso.

§ 3º Além dos casos previstos neste artigo o Banco Central do Brasil e a Comissão
de Valores Mobiliários fornecerão à Advocacia-Geral da União as informações e
os documentos necessários à defesa da União nas ações em que seja parte.

Art. 4º O Banco Central do Brasil e a Comissão de Valores Mobiliários, nas áreas
de suas atribuições, e as instituições financeiras fornecerão ao Poder Legislativo
Federal as informações e os documentos sigilosos que, fundamentadamente, se
fizerem
necessários ao
exercício
de
suas
respectivas competências
constitucionais e legais.

§ 1º As comissões parlamentares de inquérito, no exercício de sua competência
constitucional e legal de ampla investigação, obterão as informações e
documentos sigilosos de que necessitarem, diretamente das instituições
financeiras, ou por intermédio do Banco Central do Brasil ou da Comissão de
Valores Mobiliários.

§ 2º As solicitações de que trata este artigo deverão ser previamente aprovadas
pelo Plenário da Câmara dos Deputados, do Senado Federal, ou do plenário de
suas respectivas comissões parlamentares de inquérito.

Art. 5º O Poder Executivo disciplinará, inclusive quanto à periodicidade e aos
limites de valor, os critérios segundo os quais as instituições financeiras
informarão à administração tributária da União, as operações financeiras
efetuadas pelos usuários de seus serviços.

§ 1º Consideram-se operações financeiras, para os efeitos deste artigo:

I – depósitos à vista e a prazo, inclusive em conta de poupança;
II – pagamentos efetuados em moeda corrente ou em cheques;
III – emissão de ordens de crédito ou documentos assemelhados;
IV – resgates em contas de depósitos à vista ou a prazo, inclusive de
poupança;
V – contratos de mútuo;
VI – descontos de duplicatas, notas promissórias e outros títulos de
crédito;
             VII – aquisições e vendas de títulos de renda fixa ou variável;
            VIII - aplicações em fundos de investimentos;
IX – aquisições de moeda estrangeira;

[Página 14]

X – conversões de moeda estrangeira em moeda nacional;
XI – transferências de moeda e outros valores para o
exterior;
XII – operações com ouro, ativo financeiro;
XIII - operações com cartão de crédito;
XIV - operações de arrendamento mercantil; e
XV – quaisquer outras operações de natureza semelhante que venham a
ser autorizadas pelo Banco Central do Brasil, Comissão de Valores Mobiliários
ou outro órgão competente.

§ 2º As informações transferidas na forma do caput deste artigo restringir-se-ão
a informes relacionados com a identificação dos titulares das operações e os
montantes globais mensalmente movimentados, vedada a inserção de qualquer
elemento que permita identificar a sua origem ou a natureza dos gastos a partir
deles efetuados.

§ 3º Não se incluem entre as informações de que trata este artigo as operações
financeiras efetuadas pelas administrações direta e indireta da União, dos
Estados, do Distrito Federal e dos Municípios.

§ 4º Recebidas as informações de que trata este artigo, se detectados indícios de
falhas, incorreções ou omissões, ou de cometimento de ilícito fiscal, a
autoridade interessada poderá requisitar as informações e os documentos de
que necessitar, bem como realizar fiscalização ou auditoria para a adequada
apuração dos fatos.

§ 5º As informações a que refere este artigo serão conservadas sob sigilo fiscal, na
forma da legislação em vigor.

Art. 6º As autoridades e os agentes fiscais tributários da União, dos Estados, do
Distrito Federal e dos Municípios somente poderão examinar documentos, livros
e registros de instituições financeiras, inclusive os referentes a contas de
depósitos e aplicações financeiras, quando houver processo administrativo
instaurado ou procedimento fiscal em curso e tais exames sejam considerados
indispensáveis pela autoridade administrativa competente.

Parágrafo único. O resultado dos exames, as informações e os documentos a que
se refere este artigo serão conservados em sigilo, observada a legislação
tributária.

Art. 7º Sem prejuízo do disposto no § 3º do art. 2º, a Comissão de Valores
Mobiliários, instaurado inquérito administrativo, poderá solicitar à autoridade
judiciária competente o levantamento do sigilo junto às instituições financeiras
de informações e documentos relativos a bens, direitos e obrigações de pessoa

[Página 15]

física ou jurídica submetida ao seu poder disciplinar.

Parágrafo único. O Banco Central do Brasil e a Comissão de Valores Mobiliários,
manterão permanente intercâmbio de informações acerca dos resultados das
inspeções que realizarem, dos inquéritos que instaurarem e das penalidades que
aplicarem, sempre que as informações forem necessárias ao desempenho de
suas atividades.

Art. 8º O cumprimento das exigências e formalidades previstas nos artigos 4º, 6º
e 7º, será expressamente declarado pelas autoridades competentes nas
solicitações dirigidas ao Banco Central do Brasil, à Comissão de Valores
Mobiliários ou às instituições financeiras.

Art. 9º Quando, no exercício de suas atribuições, o Banco Central do Brasil e a
Comissão de Valores Mobiliários verificarem a ocorrência de crime definido em
lei como de ação pública, ou indícios da prática de tais crimes, informarão ao
Ministério Público, juntando à comunicação os documentos necessários à
apuração ou comprovação dos fatos.

§ 1º A comunicação de que trata este artigo será efetuada pelos Presidentes do
Banco Central do Brasil e da Comissão de Valores Mobiliários, admitida
delegação de competência, no prazo máximo de quinze dias, a contar do
recebimento do processo, com manifestação dos respectivos serviços jurídicos.

§ 2º Independentemente do disposto no caput deste artigo, o Banco Central do
Brasil e a Comissão de Valores Mobiliários comunicarão aos órgãos públicos
competentes as irregularidades e os ilícitos administrativos de que tenham
conhecimento, ou indícios de sua prática, anexando os documentos pertinentes.

Art. 10. A quebra de sigilo, fora das hipóteses autorizadas nesta Lei
Complementar, constitui crime e sujeita os responsáveis à pena de reclusão, de
um a quatro anos, e multa, aplicando-se, no que couber, o Código Penal, sem
prejuízo de outras sanções cabíveis.

Parágrafo único. Incorre nas mesmas penas quem omitir, retardar
injustificadamente ou prestar falsamente as informações requeridas nos termos
desta Lei Complementar.

Art. 11. O servidor público que utilizar ou viabilizar a utilização de qualquer
informação obtida em decorrência da quebra de sigilo de que trata esta Lei
Complementar responde pessoal e diretamente pelos danos decorrentes, sem
prejuízo da responsabilidade objetiva da entidade pública, quando comprovado
que o servidor agiu de acordo com orientação oficial.

