Pena - Reclusão, de 2 (dois) a 6 (seis) anos, e multa.

Parágrafo único. Incorre na mesma pena quem, a qualquer título, promove, sem
autorização legal, a saída de moeda ou divisa para o exterior, ou nele mantiver
depósitos não declarados à repartição federal competente.

[Página 17]

4. Principais conceitos envolvidos nas
operações no mercado de câmbio

O câmbio sacado

Para viabilizar as liquidações de suas transações financeiras externas, as
instituições financeiras bancárias ou não bancárias necessitam manter contas
em moeda estrangeira, nas diferentes moedas, em instituições financeiras
localizadas em países com os quais mantém relacionamento. Isso se dá por meio
de uma rede de correspondentes no exterior onde, além da manutenção da
conta em moeda estrangeira, as instituições nacionais transitam as ordens de
transferências de recursos e os documentos para cobrança.

O que se denomina câmbio sacado são as transações cuja liquidação se
viabiliza mediante débitos e créditos nessas contas, propiciando o recebimento
ou entrega da moeda estrangeira no exterior, na forma negociada pelo banco
com seus clientes aqui no país. A liquidação de uma transação externa ocorre
sempre em estabelecimento bancário situado no país que emitiu a moeda
estrangeira envolvida.

Sob a forma de câmbio sacado, são geralmente liquidadas as principais e
mais volumosas operações de câmbio, com destaque para as operações
comerciais de bens e serviços, as relativas aos créditos e investimentos externos
e a totalidade das operações do mercado interbancário.

                                  O câmbio manual

São consideradas operações de câmbio manual aquelas cuja entrega da
moeda estrangeira se dá diretamente pelo vendedor ao comprador, em mãos,
no ato da negociação. Do ponto de vista conceitual, são consideradas apenas
aquelas efetuadas em espécie (papel-moeda) ou em cheques de viagem, os
chamados “traveller’s cheques” já pouco utilizados. Por isso, é comum vincular
câmbio manual às viagens internacionais, do Brasil para o exterior ou vice-versa.

É bom lembrar que na forma da Instrução Normativa RFB nº 2.117, de 25 de
novembro de 2022, passou a ser obrigatória a prestação de declaração à repartição
aduaneira, na entrada ou saída do País, do porte de valores em espécie, cheques e
cheques de viagem de valor igual ou superior ao equivalente a US$ 10.000,00 (dez
mil dólares dos Estados Unidos).
Basta, no entanto, declarar o porte de valores acima desse limite, não
havendo restrição quanto ao montante a ser conduzido pelo viajante. Valores
acima do limite e não declarados à autoridade aduaneira podem ser apreendidos,

[Página 18]

havendo, inclusive, previsão de sua perda a favor do Tesouro Nacional, após o
devido processo legal.

A fundamentação econômica

Fundamentação econômica significa que qualquer operação realizada no
mercado de câmbio precisa ter lastro numa transação real, firme e consistente,
com razoabilidade econômica levando-se em conta a conexão da operação com
atividades comerciais, empresariais ou interesses pessoais do cliente envolvido,
não pressupondo dissimulações ou planejamentos financeiros que busquem
exclusivamente caracterizar débitos e créditos fictícios.

As transferências unilaterais

São gastos que não têm contrapartida em prestação de serviços ou em
aquisição de produtos. São exemplos de transferências unilaterais: a
manutenção de residentes e familiares, as doações e outros.

Os gastos com viagens no exterior

São gastos pessoais vinculados diretamente à viagem, efetuados no
exterior, como por exemplo saques e pagamentos de despesas no país de
destino relativas a deslocamentos, hotéis, lazer etc.

5. A Legislação cambial

A Lei 14.286, que entrou em vigor no início de 2023, revogou diversas leis,
decretos e normativos esparsos, cerca de 40 dispositivos ao todo, removendo
muitas amarras e unificando as regras para o mercado de câmbio brasileiro e para
os capitais estrangeiros, de forma concisa, simples e principiológica. O
detalhamento da Lei, feito em regulamentação infralegal, editada tanto pelo
Conselho Monetário quanto pelo Banco Central, permite que eventuais mudanças
sejam feitas de forma rápida, técnica e segura.

Os principais objetivos dessa nova Lei foram:

• Consolidar, modernizar e simplificar a legislação cambial;
• Permitir a conversibilidade do Real;
• Fomentar novos nichos de negócios;
• Garantir segurança jurídica;
• Permitir o alinhamento às melhores práticas  internacionais.

[Página 19]

Segue o texto da Lei 14.286:

CAPÍTULO I
                                            DISPOSIÇÕES PRELIMINARES

Art. 1º Esta Lei dispõe sobre o mercado de câmbio brasileiro, o capital brasileiro
no exterior, o capital estrangeiro no País e a prestação de informações ao Banco
Central do Brasil, para fins de compilação de estatísticas macroeconômicas oficiais.
Parágrafo único. Para fins do disposto nesta Lei, observado o regulamento a ser
editado pelo Banco Central do Brasil, considera-se:
I - residente: a pessoa física ou jurídica residente, domiciliada ou com sede no
Brasil;
II - não residente: a pessoa física ou jurídica residente, domiciliada ou com sede no
exterior.
CAPÍTULO II
DO MERCADO DE CÂMBIO

Art. 2º As operações no mercado de câmbio podem ser realizadas livremente, sem
limitação de valor, observados a legislação, as diretrizes estabelecidas pelo
Conselho Monetário Nacional e o regulamento a ser editado pelo Banco Central do
Brasil.
Parágrafo único. A taxa de câmbio é livremente pactuada entre as instituições
autorizadas a operar no mercado de câmbio e entre as referidas instituições e seus
clientes.

Art. 3º As operações no mercado de câmbio podem ser realizadas somente por
meio de instituições autorizadas a operar nesse mercado pelo Banco Central do
Brasil, na forma do regulamento a ser editado por essa autarquia.

Art. 4º A instituição autorizada a operar no mercado de câmbio é responsável:

I - pela identificação e pela qualificação de seus clientes;

II - por assegurar o processamento lícito de operações no mercado de câmbio.
§ 1º A instituição de que trata o caput deste artigo adotará medidas e controles
destinados a prevenir a realização de operações no mercado de câmbio para a
prática de atos ilícitos, incluídos a lavagem de dinheiro e o financiamento do

[Página 20]

terrorismo, nos termos da Lei nº 9.613, de 3 de março de 1998, observado o
regulamento a ser editado pelo Banco Central do Brasil.
§ 2º É de responsabilidade do cliente a classificação da finalidade da operação no
mercado de câmbio, na forma prevista no regulamento a ser editado pelo Banco
Central do Brasil.
§ 3º As instituições autorizadas a operar no mercado de câmbio prestarão
orientação e suporte técnico, inclusive por meio virtual, para os clientes que
necessitarem de apoio para a correta classificação de finalidade da operação no
mercado de câmbio, de que trata o § 2º deste artigo.
Art. 5º Compete ao Banco Central do Brasil:
I - regulamentar o mercado de câmbio e suas operações, incluídas as operações
de swaps, e dispor sobre os tipos e as características de produtos, as formas, os
limites, as taxas, os prazos e outras condições;
II - disciplinar a constituição, o funcionamento e a supervisão de instituições
autorizadas a operar no mercado de câmbio, inclusive quando envolverem
participação de não residente;
III - autorizar a constituição, o funcionamento, a transferência de controle, a fusão,
a cisão e a incorporação de instituições autorizadas a operar no mercado de
câmbio, inclusive quando envolverem participação de não residente;
IV - autorizar instituições em funcionamento a operar no mercado de câmbio,
inclusive quando envolverem participação de não residente;
V - cancelar, de ofício ou a pedido, nos termos do regulamento a ser editado pelo
Banco Central do Brasil, as autorizações de que tratam os incisos III e IV deste
caput;
VI - autorizar, nos termos do regulamento a ser editado pelo Banco Central do
Brasil, a posse e o exercício nos órgãos de administração ou nos órgãos previstos
no estatuto ou no contrato social de instituições autorizadas a operar no mercado
de câmbio;
VII - supervisionar as instituições autorizadas a operar no mercado de câmbio, para
fins do disposto nesta Lei, e aplicar-lhes as sanções cabíveis de que trata o art. 20
desta Lei;
VIII - regulamentar as contas em reais de titularidade de não residentes, inclusive
quanto aos requisitos e aos procedimentos para sua abertura e sua movimentação;
IX - regulamentar as contas em moeda estrangeira no País, inclusive quanto aos
requisitos e aos procedimentos para sua abertura e sua movimentação;

[Página 21]

X - manter as contas de depósito e de compensação, liquidação e custódia, em
reais e em moeda estrangeira, de titularidade de organismos internacionais,
observados os limites, os prazos, as formas e as condições estabelecidos no
regulamento a ser editado pelo Banco Central do Brasil;
XI - manter as contas de depósito e de compensação, liquidação e custódia, em
reais, de titularidade de bancos centrais estrangeiros ou de instituições
domiciliadas ou com sede no exterior que prestem serviços de compensação,
liquidação e custódia no mercado internacional, observados os limites, os prazos,
as formas e as condições estabelecidos no regulamento a ser editado pelo Banco
Central do Brasil.
§ 1º No exercício das atividades de supervisão de que trata este artigo, o Banco
Central do Brasil poderá exigir das instituições autorizadas a operar no mercado de
câmbio a disponibilização de dados e informações e a exibição de documentos e
livros de escrituração, mantidos em meio físico ou digital, inclusive para a avaliação
de suas operações ativas e passivas e dos riscos assumidos, considerada a negativa
de atendimento como embaraço à fiscalização, sujeita às sanções aplicáveis de que
trata o art. 20 desta Lei.
§ 2º Os ativos de organismos internacionais e de bancos centrais estrangeiros
mantidos nas contas de que tratam os incisos X e XI do caput deste artigo são
impenhoráveis e imunes à execução quando utilizados no desempenho de suas
funções próprias e não poderão ser objeto de arresto, de sequestro, de busca e
apreensão ou de outro ato de constrição judicial.
§ 3º Aplica-se o disposto no art. 6º da Lei nº 10.214, de 27 de março de 2001, aos
ativos de instituições domiciliadas ou com sede no exterior que prestem serviços
de compensação, liquidação e custódia no mercado internacional, mantidos nas
contas de que trata o inciso XI do caput deste artigo.
§ 4º As contas em reais de titularidade de não residentes de que trata o inciso VIII
do caput deste artigo terão o mesmo tratamento das contas em reais de
titularidade de residentes, excetuados os requisitos e os procedimentos que o
Banco Central do Brasil vier a estabelecer, inclusive em relação a movimentações
realizadas na forma prevista pelo art. 6º desta Lei.
Art. 6º Na forma do regulamento a ser editado pelo Banco Central do Brasil, os
bancos autorizados a operar no mercado de câmbio poderão dar cumprimento a
ordens de pagamento em reais recebidas do exterior ou enviadas para o exterior,
por meio da utilização de contas em reais mantidas nos bancos, de titularidade de
instituições domiciliadas ou com sede no exterior e que estejam sujeitas à
regulação e à supervisão financeira em seu país de origem.
Parágrafo único. No âmbito das relações de correspondência bancária
internacional em reais, os bancos de que trata o caput deste artigo devem obter

[Página 22]

informação sobre a instituição domiciliada ou com sede no exterior, para
compreender plenamente a natureza de sua atividade, sua reputação e a qualidade
da supervisão financeira a que está sujeita e avaliar seus controles internos em
matéria de combate à lavagem de dinheiro e ao financiamento do terrorismo.
Art. 7º O cancelamento ou a baixa na posição de câmbio referentes aos contratos
de compra de moeda estrangeira que amparem adiantamentos em reais sujeitam
o vendedor de moeda estrangeira ao recolhimento ao Banco Central do Brasil de
encargo financeiro não superior a 100% (cem por cento) do valor do adiantamento.
§ 1º A instituição autorizada a operar no mercado de câmbio compradora da moeda
estrangeira é responsável pelo recolhimento ao Banco Central do Brasil do encargo
financeiro de que trata o caput deste artigo.
§ 2º O Conselho Monetário Nacional regulamentará o disposto neste artigo e
disporá sobre a forma de cálculo do encargo financeiro de que trata o caput deste
artigo e sobre as hipóteses em que seu recolhimento será dispensado, vedado o
estabelecimento de tratamento diferenciado em razão da natureza do vendedor
da moeda estrangeira ou do seu setor produtivo.

CAPÍTULO III
  DO CAPITAL BRASILEIRO NO EXTERIOR E DO CAPITAL ESTRANGEIRO NO PAÍS

Art. 8º Para fins do disposto nesta Lei, consideram-se:
I - capitais brasileiros no exterior: os valores, os bens, os direitos e os ativos de
qualquer natureza detidos fora do território nacional por residentes;
II - capitais estrangeiros no País: os valores, os bens, os direitos e os ativos de
qualquer natureza detidos no território nacional por não residentes.
Parágrafo único. Fica o Banco Central do Brasil autorizado a dispor sobre as
hipóteses em que, considerada a natureza das operações:
I - capitais de residentes, mantidos no território nacional em favor de não
residentes, serão equiparados a capitais brasileiros no exterior;
II - capitais de não residentes, mantidos no exterior em favor de residentes, serão
equiparados a capitais estrangeiros no País.
Art. 9º Ao capital estrangeiro no País será dispensado tratamento jurídico idêntico
ao concedido ao capital nacional em igualdade de condições.
Art. 10. Compete ao Banco Central do Brasil:
I - regulamentar e monitorar os capitais brasileiros no exterior e os capitais
estrangeiros no País quanto a seus fluxos e estoques;

[Página 23]

II - estabelecer procedimentos para as remessas referentes ao capital estrangeiro
no País, observadas a legislação, a fundamentação econômica das operações e as
condições usualmente observadas nos mercados internacionais;
III - requisitar, a seu critério, informações sobre os capitais brasileiros no exterior e
os capitais estrangeiros no País, observada a regulamentação a ser editada pelo
Banco Central do Brasil, que poderá dispor, inclusive, sobre os responsáveis, as
formas, os prazos e os critérios para a prestação de informações e as situações em
que ela será dispensada.
Parágrafo único. As infrações à regulamentação de que trata o caput deste artigo
sujeitam os responsáveis às penalidades aplicáveis pelo Banco Central do Brasil, na
forma do parágrafo único do art. 20 desta Lei.
CAPÍTULO IV
DAS INFORMAÇÕES PARA A COMPILAÇÃO DE ESTATÍSTICAS
MACROECONÔMICAS OFICIAIS PELO BANCO CENTRAL DO BRASIL
Art. 11. Fica o Banco Central do Brasil autorizado a requerer aos residentes as
informações necessárias para a compilação das estatísticas macroeconômicas
oficiais.
§ 1º Sem prejuízo do atendimento às requisições de informações formuladas para
fins de apuração de crimes e outras irregularidades pelas autoridades
competentes, nos termos da legislação em vigor, o Banco Central do Brasil e seus
agentes guardarão sigilo sobre as informações individuais obtidas na forma deste
artigo, admitida a sua utilização exclusivamente para fins de compilação de
estatísticas ou para os fins previstos no § 2º deste artigo.
§ 2º Informações individuais obtidas na forma deste artigo, tratadas de modo a não
permitir, direta ou indiretamente, a identificação de seu titular, poderão ser
disponibilizadas pelo Banco Central do Brasil para subsidiar estudos e pesquisas,
mediante apresentação de requisição fundamentada e assinatura de termo de
compromisso por parte do interessado.
§ 3º O Banco Central do Brasil regulamentará o disposto neste artigo e poderá
dispor sobre as condições, o detalhamento, a frequência e a periodicidade para a
prestação de informações e sobre as condições para acesso a informações nos
termos do § 2º deste artigo.
§ 4º A regulamentação de que trata o § 3º deste artigo considerará o padrão
estatístico adotado pelo Banco Central do Brasil, as melhores práticas
internacionais em matéria de padrões estatísticos e a razoabilidade do custo de
sua observância para as pessoas físicas e jurídicas obrigadas ao fornecimento de
informações.

[Página 24]

§ 5º As infrações à regulamentação de que trata este artigo sujeitam os
responsáveis às penalidades aplicáveis pelo Banco Central do Brasil, na forma do
parágrafo único do art. 20 desta Lei.
CAPÍTULO V
DISPOSIÇÕES GERAIS
Art. 12. Fica autorizada a realização de compensação privada de créditos ou de
valores entre residentes e não residentes, nas hipóteses previstas em regulamento
do Banco Central do Brasil.
§ 1º No regulamento de que trata o caput deste artigo, o Banco Central do Brasil
poderá exigir que residentes prestem informações sobre a realização de
compensação privada, observados os prazos, as formas e as demais condições nele
previstas.
§ 2º As infrações ao disposto neste artigo e no regulamento a ser editado pelo
Banco Central do Brasil sujeitam os responsáveis às penalidades aplicáveis pelo
Banco Central do Brasil, na forma do parágrafo único do art. 20 desta Lei.
Art. 13. A estipulação de pagamento em moeda estrangeira de obrigações
exequíveis no território nacional é admitida nas seguintes situações:
I - nos contratos e nos títulos referentes ao comércio exterior de bens e serviços,
ao seu financiamento e às suas garantias;
II - nas obrigações cujo credor ou devedor seja não residente, incluídas as
decorrentes de operações de crédito ou de arrendamento mercantil, exceto nos
contratos de locação de imóveis situados no território nacional;
III - nos contratos de arrendamento mercantil celebrados entre residentes, com
base em captação de recursos provenientes do exterior;
IV - na cessão, na transferência, na delegação, na assunção ou na modificação das
obrigações referidas nos incisos I, II e III do caput deste artigo, inclusive se as
partes envolvidas forem residentes;
V - na compra e venda de moeda estrangeira;
VI - na exportação indireta de que trata a Lei nº 9.529, de 10 de dezembro de 1997;
VII - nos contratos celebrados por exportadores em que a contraparte seja
concessionária, permissionária, autorizatária ou arrendatária nos setores de
infraestrutura;
VIII - nas situações previstas na regulamentação editada pelo Conselho Monetário
Nacional, quando a estipulação em moeda estrangeira puder mitigar o risco
cambial ou ampliar a eficiência do negócio;

[Página 25]

IX - em outras situações previstas na legislação.
Parágrafo único. A estipulação de pagamento em moeda estrangeira feita em
desacordo com o disposto neste artigo é nula de pleno direito.
Art. 14. O ingresso no País e a saída do País de moeda nacional e estrangeira devem
ser realizados exclusivamente por meio de instituição autorizada a operar no
mercado de câmbio, à qual caberá a identificação do cliente e do destinatário ou
do remetente.
§ 1º O disposto no caput deste artigo não se aplica ao porte, em espécie, de
valores:
I - até US$ 10.000,00 (dez mil dólares dos Estados Unidos da América) ou seu
equivalente em outras moedas; e
II - cuja entrada no País ou saída do País seja comprovada na forma do regulamento
de que trata o § 4º deste artigo.
§ 2º Observadas as diretrizes do Conselho Monetário Nacional, o Banco Central do
Brasil regulamentará as disposições do caput deste artigo e poderá dispor sobre:
I - a forma, os limites e as condições de ingresso no País e saída do País de moeda
nacional ou estrangeira;
II - os tipos de instituições autorizadas a operar no mercado de câmbio que não
poderão efetuar o ingresso no País e a saída do País de moeda nacional ou
estrangeira, considerados o porte, a natureza e o modelo de negócio das
instituições.
§ 3º O descumprimento do disposto neste artigo acarretará, após o devido processo
legal, o perdimento do valor excedente aos limites referidos no § 1º deste artigo
em favor do Tesouro Nacional, além das sanções penais previstas na legislação
específica.
§ 4º Compete à Secretaria da Receita Federal do Brasil do Ministério da Fazenda
regulamentar o disposto no § 1º deste artigo e aplicar a penalidade de perdimento
de que trata o § 3º deste artigo, na forma dos §§ 1º, 2º, 3º, 4º, 5º e 6º do art. 89 da
Medida Provisória nº 2.158-35, de 24 de agosto de 2001, e de demais disposições
constantes da legislação aplicável.
Art. 15. As instituições financeiras e as demais instituições autorizadas a funcionar
pelo Banco Central do Brasil, observadas as atividades que lhes são permitidas pela
legislação, poderão alocar, investir e destinar para operação de crédito e de
financiamento, no País e no exterior, os recursos captados no País e no exterior,
observados os requisitos regulatórios e prudenciais estabelecidos pelo Conselho
Monetário Nacional e pelo Banco Central do Brasil.

[Página 26]

Art. 16. O disposto na alínea “a” do art. 4º da Lei nº 1.521, de 26 de dezembro de
1951, não se aplica às operações de câmbio efetuadas na forma desta Lei.
Art. 17. O Banco Central do Brasil poderá firmar convênios para compartilhamento
de informações com órgãos e entidades da administração pública federal,
consoante suas áreas de competência, observada a legislação sobre o sigilo
bancário e sobre o sigilo fiscal.
Art. 18. Na regulamentação desta Lei, o Banco Central do Brasil:
I - poderá estabelecer exigências e procedimentos diferenciados, segundo critério
de proporcionalidade, considerando aspectos como o valor, o risco e as demais
características da operação no mercado de câmbio, do capital brasileiro no exterior
ou do capital estrangeiro no País;
II - poderá, considerando a abrangência de atuação da instituição interessada em
operar no mercado de câmbio, o volume, a natureza, a capacidade de inovação e
os riscos de seu negócio:
a) estabelecer requerimentos diferenciados e proporcionais para a constituição e o
funcionamento de instituições autorizadas a operar no mercado de câmbio;
b) dispensar a autorização para constituição e funcionamento das instituições de
que trata a alínea “a” deste inciso.
Art. 19. O disposto nesta Lei não se aplica a operações de compra ou venda de
moeda estrangeira em espécie, no valor de até US$ 500,00 (quinhentos dólares dos
Estados Unidos da América) ou seu equivalente em outras moedas, realizadas no
País, de forma eventual e não profissional, entre pessoas físicas.
CAPÍTULO VI
DISPOSIÇÕES FINAIS
Art. 20. Aplica-se o disposto no Capítulo II e no art. 36 da Lei nº 13.506, de 13 de
novembro de 2017, às infrações a esta Lei e aos regulamentos a serem editados
pelo Conselho Monetário Nacional e pelo Banco Central do Brasil.
Parágrafo único. Para fins do disposto no caput deste artigo, às infrações às
normas legais e regulamentares de que tratam os arts. 10, 11 e 12 desta Lei não se
aplicam os arts. 2º, 3º e 4º e os incisos I, III, V e VI do caput do art. 5º da Lei nº
13.506, de 13 de novembro de 2017.
Art. 21. O art. 6º-A do Decreto nº 23.258, de 19 de outubro de 1933, passa a vigorar
com a seguinte redação:

[Página 27]

“Art. 6º-A O Conselho Monetário Nacional disciplinará o disposto no art. 3º deste
Decreto e poderá estabelecer a gradação da multa a que se refere o caput do art.
6º deste Decreto.” (NR)
Art. 22. O art. 9º da Lei nº 4.131, de 3 de setembro de 1962, passa a vigorar com
