das sociedades distribuidoras de títulos e valores mobiliários;
II - autorizar a constituição e o funcionamento e supervisionar as atividades das
sociedades corretoras de títulos e valores mobiliários, das sociedades corretoras
de câmbio e das sociedades distribuidoras de títulos e valores mobiliários.
Parágrafo único. Para os fins deste artigo, aplica-se o disposto na Lei nº 4.595, de
31 de dezembro de 1964, na Lei nº 6.024, de 13 de março de 1974, no Decreto-Lei
