II - aos administradores e aos membros da diretoria, do conselho de administração,
do conselho fiscal, do comitê de auditoria e de outros órgãos previstos no estatuto
social ou no contrato social das sociedades referidas no inciso I deste parágrafo;
III - às pessoas físicas e jurídicas e aos administradores e responsáveis técnicos de
pessoas jurídicas que prestem serviço de auditoria independente às sociedades
referidas no inciso I deste parágrafo.”

[Página 28]

Art. 24. O art. 50 da Lei nº 8.383, de 30 de dezembro de 1991, passa a vigorar com
as seguintes alterações:
“Art. 50. As despesas referidas na alínea “b” do parágrafo único do art. 52 e
no item 2 da alínea “e” do parágrafo único do art. 71 da Lei nº 4.506, de 30 de
novembro de 1964, decorrentes de contratos que, posteriormente a 31 de
dezembro de 1991, sejam assinados e averbados no Instituto Nacional da
