Art. 27. A instituição autorizada a operar no mercado de câmbio não poderá exigir
do cliente documentos, dados ou certidões que estiverem disponíveis em suas
bases de dados ou em bases de dados públicas e privadas de acesso amplo.
Parágrafo único. Independentemente do disposto no caput deste artigo, é
facultado ao cliente optar pela apresentação dos documentos, dados ou certidões
de que trata o caput deste artigo.
Art. 28. Revoga uma série de dispositivos legais (Leis, Decretos-Leis Medidas
Provisórias, que se encontram enumerados na própria Lei).
Art. 29. Esta Lei entra em vigor após decorrido 1 (um) ano de sua publicação oficial.
(A Lei foi publicada em 30.12.2021).

