Resolução CMN n° 5.042, de 25 de novembro de 2022:

Estabelece as diretrizes que devem ser observadas para a realização das operações
no mercado de câmbio.

Art. 1º  Esta Resolução estabelece as diretrizes que devem ser observadas para a
realização das operações no mercado de câmbio.
Parágrafo único.  O disposto nesta Resolução também compreende as diretrizes
sobre o ingresso no País ou a saída do País de reais ou de moeda estrangeira por
meio de instituição autorizada a operar no mercado de câmbio.
Art. 2º  Para realizarem operações no mercado de câmbio, as instituições
financeiras e demais instituições autorizadas a funcionar pelo Banco Central do
Brasil devem obter autorização prévia do Banco Central do Brasil.
Art. 3º  São princípios que norteiam o funcionamento regular do mercado de
câmbio:
I - a competição para a prestação de serviços ao público relacionados às operações
do mercado de câmbio;
II - o atendimento das necessidades do público, em especial liberdade de escolha,
privacidade, transparência e acesso a informações claras e completas sobre as
condições das operações do mercado de câmbio;
III - a eficiência das operações realizadas no mercado de câmbio;
IV - o estímulo à inovação, considerando a legalidade das operações, e à
diversidade de modelos de negócio;
V - a redução de custos de transação no mercado de câmbio;
VI - a inclusão financeira;
VII - a confiabilidade e a qualidade dos produtos e serviços ofertados no mercado
de câmbio; e
VIII - a integridade, a conformidade, a segurança e o sigilo das operações de câmbio
ou das movimentações de valores.

[Página 30]

Art. 4º  A realização de operações no mercado de câmbio e o ingresso no País ou a
saída do País de reais ou de moeda estrangeira por meio de instituição autorizada
a operar no mercado de câmbio devem observar as seguintes diretrizes gerais:
I - livre pactuação da taxa de câmbio;
II - livre realização de operações no mercado de câmbio, sem limitação de valor,
observadas a legislação, as diretrizes deste artigo e a regulamentação do Banco
Central do Brasil;
III - adequação dos produtos e serviços ofertados ou recomendados às
necessidades, aos interesses e aos objetivos dos clientes;
IV - prestação, de forma clara e precisa, das informações necessárias à livre escolha
e à tomada de decisões por parte de clientes, explicitando, inclusive, direitos e
deveres, responsabilidades, custos ou ônus, penalidades e eventuais riscos
existentes na realização de operações de câmbio ou nas movimentações de
valores;
V - utilização, em ofertas, contratos e recibos, de redação clara, objetiva e
adequada à natureza e à complexidade dos serviços a serem prestados em relação
a operações de câmbio ou a movimentação de valores;
VI - cumprimento da legislação e da regulamentação do Banco Central do Brasil,
inclusive sobre:
a) os procedimentos e a política para identificação e qualificação de clientes,
inclusive aqueles destinados à prevenção de ilícitos;
b) o funcionamento e a supervisão de instituições autorizadas a operar no mercado
de câmbio;
c) os tipos e as características das operações de câmbio, inclusive as formas, os
limites, as taxas, os prazos e outras condições; e
d) os requisitos e os procedimentos para abertura e movimentação das contas em
reais de titularidade de não residentes e das contas em moeda estrangeira no País;
VII - a previsão das características mínimas que as operações realizadas no
mercado de câmbio deverão ter para assegurar a comprovação de consenso
negocial entre as partes sobre as condições pactuadas; e
VIII - o tratamento do ouro como instrumento cambial e a sujeição das operações
com ouro às regras aplicáveis às operações de compra e de venda de moeda
estrangeira.

[Página 31]

Art. 5º  O relacionamento financeiro entre instituições autorizadas a operar no
mercado de câmbio e instituições domiciliadas ou com sede no exterior deve ser
mantido com aquelas sujeitas à regulação e à supervisão financeira no respectivo
país de origem.
Art. 6º  As instituições financeiras e as demais instituições autorizadas a funcionar
pelo Banco Central do Brasil, observadas as atividades que lhes são permitidas pela
legislação, poderão alocar, investir e destinar para operação de crédito e de
financiamento, no País e no exterior, os recursos captados no País e no exterior,
observados os requisitos regulatórios e prudenciais estabelecidos pelo Conselho
Monetário Nacional e pelo Banco Central do Brasil.
Art. 7º  Os tipos e as características das operações de câmbio, inclusive as formas,
os limites, as taxas, os prazos e outras condições, poderão ser definidos com base
em critério de proporcionalidade, considerando a complexidade e os riscos
associados.
Art. 8º  Ficam revogados:
I - a Circular nº 24, de 25 de fevereiro de 1966;
II - a Resolução nº 4.033, de 30 de novembro de 2011; e
III - o art. 3º da Resolução CMN nº 4.948, de 30 de setembro de 2021.
Art. 9º  Esta Resolução entra em vigor em 31 de dezembro de 2022.

Resolução BCB nº 277, de 31 de dezembro de 2022:

TÍTULO I
DISPOSIÇÕES GERAIS
CAPÍTULO ÚNICO

Art. 1º Esta Resolução regulamenta a Lei nº 14.286, de 29 de dezembro de 2021,
em relação aos aspectos de competência do Banco Central do Brasil referentes ao
mercado de câmbio, que compreende:

I - as compras e as vendas de moeda estrangeira;

II - os pagamentos e as transferências internacionais realizados por meio de serviço
de pagamento ou transferência internacional;

[Página 32]

III - as contas em reais de titularidade de não residentes;

IV - as contas em moeda estrangeira mantidas no Brasil;

V - as operações com ouro-instrumento cambial; e

VI - a prestação de serviços de ativos virtuais prevista nesta Resolução (Inciso
incluído pela Resolução BCB 521, de 10/11/2025).

Art. 2º É livre a forma de celebração de operação de câmbio.

Parágrafo único. No caso de operação com cliente, a instituição autorizada a
operar no mercado de câmbio deve ser capaz de comprovar que as partes
consentem com as condições pactuadas.

Art. 3º As informações mínimas que fazem parte da operação de câmbio estão no
Anexo I a esta Resolução.

Art. 4º Para fins de classificação da finalidade da operação de câmbio, cuja
responsabilidade é do cliente, a instituição autorizada a operar no mercado de
câmbio deve apresentar ou tornar disponível ao cliente, em livre formato que
permita o claro entendimento pelo cliente, os códigos constantes:

I - no Anexo III para indicação da finalidade da operação de câmbio de até
US$50.000,00 (cinquenta mil dólares dos Estados Unidos), ou seu equivalente em
outras moedas (Redação dada pela Resolução BCB 337, de 22/08/2023);

II - no Anexo IV para indicação da finalidade da operação de câmbio superior a
US$50.000,00 (cinquenta mil dólares dos Estados Unidos), ou seu equivalente em
outras moedas (Redação dada pela Resolução BCB 337, de 22/08/2023);

III - no Anexo V para a indicação da finalidade da operação de câmbio,
independentemente de seu valor, relativa a serviço de transferências postais
internacionais ou a serviço de pagamento ou transferência internacional (eFX)
(Redação dada pela Resolução BCB 337, de 22/08/2023).

§ 1º Devem também ser prestadas as informações constantes do:

I - Anexo VI, com a indicação efetuada pelo cliente, sobre o pagador ou recebedor
no exterior e sua relação de vínculo com o cliente no caso das situações previstas
nos incisos II e III do caput; e

II - Anexo VII, com a indicação efetuada pela instituição autorizada a operar no
mercado de câmbio, sobre a forma de entrega da moeda estrangeira.

[Página 33]

§ 2º A pedido do cliente:

I - é facultada a utilização da lista de códigos constante do Anexo IV para operação
de câmbio de até US$50.000,00 (cinquenta mil dólares dos Estados Unidos), ou seu
equivalente em outras moedas, mediante concordância da instituição autorizada a
operar no mercado de câmbio;

II - a instituição autorizada a operar no mercado de câmbio deve ajustar informação
já prestada pelo cliente relativa à operação de câmbio (Redação dada pela
Resolução BCB 337, de 22/08/2023).

§ 3º As instituições autorizadas a operar no mercado de câmbio prestarão
orientação e suporte técnico, inclusive por meio virtual, para os clientes que
necessitarem de apoio para a correta classificação de finalidade da operação no
mercado de câmbio.

Art. 5º A instituição autorizada a operar no mercado de câmbio deve utilizar as
listas dos códigos constantes:

I - nos Anexos IV, V, VI e VII para a classificação de operação de câmbio própria,
com instituição no exterior, com o Banco Central do Brasil, com outra instituição
autorizada a operar no mercado de câmbio, ou de operação especial (Redação dada
pela Resolução BCB 337, de 22/08/2023); e

II - no Anexo VIII para a classificação complementar, exclusivamente para envio ao
Banco Central do Brasil (Redação dada pela Resolução BCB 337, de 22/08/2023).

III - (Revogado pela Resolução BCB 337, de 22/08/2023).

Art. 6º Para a devolução de valores não aplicados na finalidade ou na forma
originalmente indicada ou ainda para a devolução de valores indevidamente
transferidos, deve ser utilizada a classificação correspondente à mesma finalidade
indicada na operação original.

Art. 7º A instituição autorizada a operar no mercado de câmbio pode requisitar ou
dispensar, conforme sua avaliação, informações e documentos comprobatórios,
considerando a avaliação do cliente e as características da operação.

Parágrafo único. As disposições sobre os critérios a serem adotados em relação às
informações e aos documentos comprobatórios para fins de prevenção à lavagem de
dinheiro e de combate ao financiamento ao terrorismo estão na Circular nº 3.978, de
23 de janeiro de 2020.

Art. 8º A instituição autorizada a operar no mercado de câmbio deve manter à
disposição do Banco Central do Brasil e conservar pelo período mínimo de dez

[Página 34]

anos, contados do término do exercício em que ocorra o evento de contratação,
ou se houver, de liquidação, cancelamento ou baixa da operação de câmbio:

I - a comprovação do consentimento do cliente às condições pactuadas;

II - as informações sobre a operação e os documentos comprobatórios que tenham
sido coletados.

Art. 9º As instituições autorizadas a operar no mercado de câmbio e os prestadores
de serviço de pagamento ou transferência internacional devem cumprir a
legislação e a regulamentação referente ao mercado de câmbio.

Art. 10. No caso de operação de câmbio realizada com a participação de
correspondente no País, a instituição autorizada a operar no mercado de câmbio
deve manter em seu poder a cópia da documentação de identificação do cliente.

Art. 11. Para efeitos desta Resolução, as referências à compra ou à venda de
moeda estrangeira significam que a instituição autorizada a operar no mercado de
câmbio é a compradora ou a vendedora, respectivamente.

Art. 12. O ingresso no País ou a saída do País de reais ou de moeda estrangeira em
espécie superior a US$10.000,00 (dez mil dólares dos Estados Unidos), ou seu
equivalente em outras moedas, seja em reais seja em moeda estrangeira, somente
pode ser realizado por instituição autorizada a operar no mercado de câmbio com
a participação de banco autorizado a operar no mercado de câmbio, ressalvada a
situação relativa a porte de valores prevista no inciso II do § 1º do art. 14 da Lei nº
14.286, de 2021.

Parágrafo único. As instituições de pagamento autorizadas a operar no mercado de
câmbio não podem realizar o ingresso e a saída de moeda de que trata o caput.

Art. 13. O pagamento ao exterior ou recebimento do exterior deve ser realizado
por meio de instituição autorizada a operar no mercado de câmbio ou por outra
forma prevista na legislação, devendo a instituição autorizada a operar no mercado
de câmbio utilizar meio que assegure que a respectiva instrução de pagamento seja
acompanhada das informações relativas ao remetente e ao beneficiário dos
recursos.

Parágrafo único. No caso de remessa de recursos para o exterior, a respectiva
instrução de pagamento deve ser acompanhada das seguintes informações:

I - relativas ao remetente: nome, número do documento de identificação, endereço
e identificador da conta ou número de inscrição no Cadastro de Pessoas Físicas
(CPF) ou no Cadastro Nacional da Pessoa Jurídica (CNPJ), no caso de pessoa

[Página 35]

obrigada de inscrição em referidos cadastros, e forma de entrega da moeda pelo
remetente diferente de débito em conta;

II - relativas ao beneficiário: nome e identificador da conta ou identificador único
da transação.

Art. 14. Relativamente a ordens de pagamento em moeda estrangeira:

I - a instituição autorizada a operar no mercado de câmbio deve comunicar
imediatamente ao beneficiário o recebimento de ordem de pagamento oriunda do
exterior a seu favor, informando-o de que a ordem pode ser negociada de forma
integral ou parcelada;

II - a ordem de pagamento não cumprida no exterior deve ser objeto de realização
de operação de câmbio com o remetente da ordem, cabendo à instituição
comunicar o fato ao referido remetente no prazo de até três dias úteis, contados a
partir da data em que a instituição recebeu a informação do não cumprimento da
ordem.

Art. 15. As operações de câmbio podem ser contratadas para liquidação pronta ou
futura e, no caso de operações interbancárias, para liquidação a termo, observado
que:

I - nas operações para liquidação pronta ou futura, a taxa de câmbio deve refletir
exclusivamente o preço da moeda negociada para a data da contratação da
operação de câmbio, sendo facultada a pactuação de prêmio ou bonificação nas
operações para liquidação futura;

II - nas operações para liquidação a termo, a taxa de câmbio é livremente pactuada
entre as partes e deve espelhar o preço negociado da moeda estrangeira para a
data da liquidação da operação de câmbio.

Art. 16. Sujeita-se às penalidades e demais sanções previstas na legislação e
regulamentação em vigor a compra ou a venda de moeda estrangeira a taxas que
se situem em patamares destoantes daqueles praticados pelo mercado ou que
possam configurar evasão cambial, formação artificial ou manipulação de preços.

Art. 17. Para fins da determinação da equivalência em dólares dos Estados Unidos
das operações de câmbio cursadas em outras moedas estrangeiras deve ser
utilizada a informação sobre taxas de câmbio mais recentemente disponível para a
data do evento divulgada pelo Banco Central do Brasil.

[Página 36]

Art. 18. O Valor Efetivo Total (VET), expresso em reais por unidade de moeda
estrangeira, é calculado considerando a taxa de câmbio, os tributos que incidem
sobre a operação de câmbio e as tarifas eventualmente cobradas.

Parágrafo único. Para as operações de câmbio com clientes para liquidação pronta
de até US$100.000,00 (cem mil dólares dos Estados Unidos), ou o seu equivalente
em outras moedas, as instituições autorizadas a operar no mercado de câmbio
devem:

I - informar o VET a seu cliente ou usuário previamente à realização da operação
de câmbio;

II - incluir o VET entre as informações constantes do Anexo I a esta Resolução que
devem ser conhecidas pelas partes.

Art. 19. Na operação de compra ou de venda de moeda estrangeira, o recebimento
ou entrega do seu contravalor em reais deve ser realizado a partir de crédito ou de
débito à conta de depósito ou de pagamento do cliente mantida em instituições
financeiras e demais instituições autorizadas a funcionar pelo Banco Central do
Brasil ou em instituições de pagamento que, em virtude de sua adesão ao Pix,
integrem o Sistema de Pagamentos Brasileiro (SPB).

§ 1º O recebimento ou a entrega do contravalor em reais de que trata o caput pode
ser realizado também por meio de cheque, na forma de sua regulamentação.

§ 2º A utilização de conta de pagamento pós-paga é limitada às operações de
venda de moeda estrangeira.

§ 3º Quando não ultrapassar R$10.000,00 (dez mil reais), o recebimento ou a
entrega do contravalor em reais de que trata o caput pode ser realizado por
qualquer meio de pagamento em uso no mercado financeiro, inclusive em espécie,
observado o § 2º.

Art. 20. A instituição autorizada a operar no mercado de câmbio, em seu
relacionamento com prestador de serviços postais, conforme o art. 2º da Lei nº
6.538, de 22 de junho de 1978, deve ser capaz de comprovar para o Banco Central
do Brasil que se certificou de que referido prestador:

I - adota política, procedimentos e controles internos para cumprir os deveres e as
obrigações previstos nesta Resolução, inclusive com vista a evitar a compensação
entre os pagamentos de seu interesse; e

II - realiza recebimentos e pagamentos para fins de prestação do serviço de vale
postal internacional de até US$50.000,00 (cinquenta mil dólares dos Estados

[Página 37]

Unidos), ou o seu equivalente em outras moedas, referentes a negócios que não
necessitem ser vinculados a operações de capitais estrangeiros informados em
sistema do Banco Central do Brasil, com entrega de comprovante ao seu cliente
contendo a identificação do cliente, do pagador ou recebedor no exterior, a
finalidade do negócio, a moeda estrangeira, a taxa de conversão, os valores em
moeda estrangeira e em moeda nacional, o valor referente a eventuais tarifas e o
valor referente a eventuais tributos.

Art. 21. Para a operação de câmbio referente a pagamento ou a recebimento
antecipado:

I - no caso de pagamento antecipado, a instituição autorizada a operar no mercado
de câmbio deve informar o cliente de que, caso não venha a se concretizar a
operação que respaldou a transferência, o comprador da moeda estrangeira deve
providenciar o retorno ao País dos recursos correspondentes;

II - no caso de recebimento antecipado relativo a negócio não concretizado de
acordo com a finalidade originalmente indicada, a instituição autorizada a operar
no mercado de câmbio deve informar o cliente de que o valor pode ser devolvido
para o exterior em até trezentos e sessenta dias ou, mediante anuência prévia do
pagador no exterior, ser convertido para outra finalidade, observada a
regulamentação tributária aplicável.

Art. 22. Não são admitidos fracionamentos de operações de câmbio para fins de
utilização de prerrogativa concedida nos termos desta Resolução.

Art. 23. As instituições autorizadas a operar no mercado de câmbio podem
converter entre si ou com instituições financeiras do exterior moeda estrangeira
em espécie em moeda estrangeira escritural e moeda estrangeira escritural em
moeda estrangeira em espécie.

Art. 24. A contratação de operação de câmbio e a movimentação em conta de não
residente em reais sujeita à prestação de informações na forma do Anexo II
relativas aos pagamentos ao exterior e aos recebimentos do exterior devem ser
realizadas separadamente pelo total de valores que tenham a mesma finalidade
informada.

Art. 25. Nas operações de câmbio, nas movimentações em contas de não
residentes em reais sujeitas à prestação de informações na forma do Anexo II ou
nas operações de prestação de serviços de ativos virtuais prevista nesta Resolução,
com liquidação de operação de câmbio, com movimentação em conta ou com
movimentação de ativo virtual na mesma data, respectivamente, a realização dos
negócios deve ser informada ao Banco Central do Brasil pelos valores integrais,

[Página 38]

podendo a movimentação dos recursos, do e para o exterior, ser efetuada pelo
valor líquido (Nova redação conferida pela Resolução BCB 521, de 10/11/2025).

Art. 26. É permitido às instituições autorizadas a operar no mercado de câmbio
receber ordem de pagamento em moeda estrangeira para ingresso de recursos do
exterior relacionados a transferências unilaterais, realizar a conversão para reais
de tais valores e direcionar os recursos resultantes a pessoas naturais, observado
nesses casos o seguinte:

I - a sensibilização da posição de câmbio da instituição autorizada a operar no
mercado de câmbio ocorre pelo registro no Sistema Câmbio de operação de
compra para liquidação pronta, devendo ser observada classificação própria;

II - a instituição autorizada a operar no mercado de câmbio, no tocante à entrega
dos reais à pessoa natural destinatária final dos recursos, deve observar que:

a) as condições da ordem de pagamento são pactuadas pelo remetente no exterior,
incluindo o preestabelecimento do valor em reais a ser integralmente recebido
pela pessoa natural destinatária final no Brasil;

b) após o recebimento da ordem de pagamento em moeda estrangeira, a
instituição autorizada a operar no mercado de câmbio deve entregar em até três
dias úteis o valor em reais preestabelecido no exterior para a pessoa natural
destinatária final, em espécie ou mediante crédito a conta de depósito ou de
pagamento pré-paga da pessoa natural mantida em instituições financeiras e
demais instituições autorizadas a funcionar pelo Banco Central do Brasil ou em
instituições de pagamento que, em virtude de sua adesão ao Pix, integrem o SPB;

c) o valor da entrega é limitado a R$10.000,00 (dez mil reais), por operação; e

d) no caso de entrega dos reais em espécie, a instituição autorizada a operar no
mercado de câmbio deve adotar em relação à pessoa natural destinatária final
dos recursos os procedimentos destinados a clientes previstos nesta Resolução,
bem como manter em seu poder cópia da documentação de identificação da
pessoa natural.

Art. 27. Para alienação de moeda estrangeira em espécie apreendida de que trata
o § 1º do art. 60-A da Lei nº 11.343, de 23 de agosto de 2006, o vendedor da moeda
estrangeira na operação de câmbio é a União, o Estado ou o Distrito Federal,
conforme o caso, representado pelo órgão judicial que tenha determinado a
conversão da moeda apreendida em moeda nacional.

Parágrafo único. O limite de valor previsto na alínea “a” do inciso II do art. 29 não
se aplica à operação de câmbio de que trata o caput deste artigo.

[Página 39]

Art. 28. As contas em moeda estrangeira no exterior tituladas pelas instituições
autorizadas a operar no mercado de câmbio e destinadas à liquidação de suas
operações devem ser mantidas em instituição sujeita a efetiva supervisão
prudencial e de conduta na sua respectiva jurisdição ou integrante de grupo
financeiro sujeito a efetiva supervisão consolidada, cabendo à instituição
autorizada a operar no mercado de câmbio certificar-se dessa qualificação da
instituição depositária de seus recursos no exterior, inclusive para fins de
comprovação perante o Banco Central do Brasil.

TÍTULO II
INSTITUIÇÕES AUTORIZADAS A OPERAR NO MERCADO DE CÂMBIO
CAPÍTULO ÚNICO

Art. 29. As autorizações para operar no mercado de câmbio podem ser concedidas
para as instituições abaixo indicadas realizarem as seguintes operações:

I - bancos e a Caixa Econômica Federal: todas as operações do mercado de câmbio,
ressalvado que as operações de prestação de serviços de ativos virtuais previstas
nesta Resolução são permitidas apenas para as instituições que atuem como
prestadoras de serviços de ativos virtuais, na forma da regulamentação sobre o
assunto (Redação dada pela Resolução BCB 521, de 10/11/2025);

II - sociedades corretoras de títulos e valores mobiliários, sociedades distribuidoras
de títulos e valores mobiliários, sociedades corretoras de câmbio, sociedades de
crédito, financiamento e investimento e agências de fomento:

a) operações de câmbio com clientes para liquidação pronta de até US$500.000,00
(quinhentos mil dólares dos Estados Unidos) ou o seu equivalente em outras
moedas, não sendo permitidas transferências referentes a negociação de
instrumentos financeiros derivativos no exterior;

b) operações para liquidação pronta no mercado interbancário, arbitragens no país
e arbitragens com o exterior; e

c) operações de prestação de serviços de ativos virtuais previstas nesta Resolução
somente para as instituições que atuem como prestadoras de serviços de ativos
virtuais, na forma da regulamentação sobre o assunto, observado que o pagamento
ou transferência internacional com ativos virtuais quando a contraparte não for
instituição autorizada a operar no mercado de câmbio é limitado ao valor
equivalente a US$500.000,00 (quinhentos mil dólares dos Estados Unidos) (Alínea
incluída pela Resolução BCB 521, de 10/11/2025).

III - instituições de pagamento autorizadas a funcionar pelo Banco Central do Brasil
que prestem serviço como emissor de moeda eletrônica, emissor de instrumento

[Página 40]

de pagamento pós-pago ou credenciador, vedadas a condução de operações com
correspondentes e operações envolvendo moedas em espécie, nacional ou
estrangeira:

a) operações de câmbio com clientes para liquidação pronta de até
US$100.000,00 (cem mil dólares dos Estados Unidos) ou o seu equivalente
em outras moedas, não sendo permitidas transferências referentes a
negociação de instrumentos financeiros derivativos no exterior;

b) operações para liquidação pronta no mercado interbancário, arbitragens no
País e arbitragens com o exterior.

IV - sociedades prestadoras de serviços de ativos virtuais: operações de prestação
de serviços de ativos virtuais previstas nesta Resolução, vedadas operações
envolvendo moedas em espécie, nacional ou estrangeira, observado que o
pagamento ou transferência internacional com ativos virtuais quando a
contraparte não for instituição autorizada a operar no mercado de câmbio é
limitado ao valor equivalente a US$100.000,00 (cem mil dólares dos Estados
Unidos) (Inciso incluído pela Resolução BCB 521, de 10/11/2025).

§ 1º Os limites de valor estabelecidos neste artigo:

I - não impedem a realização de operação de câmbio relativa a parcelas de
pagamento ou de recebimento previstas em programação de desembolso de
negócio com valor total superior aos citados limites;

II - não se aplicam quando a instituição autorizada a operar em câmbio for a
compradora e a vendedora da moeda estrangeira e esteja atuando para o
cumprimento de obrigações decorrentes das operações de seus clientes.

§ 2º A instituição autorizada a operar no mercado de câmbio deve indicar diretor
responsável pelas operações de que trata esta Resolução.

§ 3º As instituições autorizadas a operar no mercado de câmbio podem conduzir
operações de câmbio por meio de posto de atendimento, observada a regulamentação
sobre o assunto.

§ 4º O disposto no § 3º não é aplicável às instituições de pagamento e às sociedades
prestadoras de serviços de ativos virtuais (Redação dada pela Resolução BCB 521, de
10/11/2025).

§ 5º As sociedades prestadoras de serviços de ativos virtuais que, na data da entrada
em vigor da resolução BCB que disciplina sua constituição e seu funcionamento,
estiverem em atividade nos termos do art. 9º da Lei nº 14.478, de 21 de dezembro de
2022, podem continuar realizando as operações de prestação de serviços de ativos

[Página 41]

virtuais previstas nesta Resolução, desde que observem os prazos e condições
previstos na regulamentação para solicitação, ao Banco Central do Brasil, de
autorização para funcionamento, observado que referida solicitação deve incluir
pedido para operar no mercado de câmbio (Parágrafo introduzido pela Resolução BCB
521, de 10/11/2025).

Art. 30. São requisitos para as autorizações de que trata o art. 29:

I - viabilidade econômico-financeira do empreendimento;

II - atendimento aos requerimentos mínimos de capital e de patrimônio previstos na
regulamentação em vigor;

III - compatibilidade da infraestrutura de tecnologia da informação com a
complexidade e os riscos do negócio; e

IV - compatibilidade da estrutura de governança corporativa com a complexidade e os
riscos do negócio (Incisos III e IV adicionados pela Resolução BCB 521, de 10/11/2025).

§ 1º Na comprovação do requisito referido no inciso I do caput, o Banco Central do
Brasil poderá exigir a apresentação de plano de negócio.

§ 2º Na comprovação dos requisitos do caput, o Banco Central do Brasil poderá
requerer certificação técnica ou avaliação emitida por empresa qualificada
independente (Parágrafo incluído pela Resolução BCB 521, de 10/11/2025).

Art. 31. O Banco Central do Brasil, antes ou depois da expedição das autorizações
previstas no art. 29, poderá:

I - requisitar quaisquer documentos e informações adicionais que julgar necessários,
bem como solicitá-los a outros órgãos da administração pública e a autoridades no
exterior;

II - convocar para entrevista administrador da instituição; e

III - exigir a implementação de medidas de ajuste consideradas cabíveis.

Art. 32. Com relação aos pedidos de autorização de que trata o art. 29, o Banco
Central do Brasil poderá:

I - arquivar, sem apreciação do mérito do pedido, quando:

a) verificar que o objeto ou os elementos que servem de base para o pedido
foram alterados no curso do processo;

[Página 42]

b) houver descumprimento dos prazos previstos na regulamentação em
vigor;

c)identificar que não foram atendidas as exigências para complementar a
instrução do processo, no prazo estabelecido;

d) o administrador deixar de atender a convocação do Banco Central do Brasil
para entrevista; ou

e) estiver a instrução em desacordo com o formato exigido na regulamentação
vigente.

II - indeferir, caso venha a apurar:

a) falsidade ou omissão nas declarações e nos documentos apresentados na
instrução dos processos ou discrepância entre eles e os fatos ou dados
apurados na análise; ou

b) não atendimento aos requisitos estabelecidos nesta Resolução, ou a não
comprovação de seu atendimento pelos interessados.

Parágrafo único. Nos casos de que trata o inciso II do caput, o Banco Central do
Brasil, antes da decisão, poderá conceder prazo aos interessados para
manifestação.

Art. 33. O Banco Central do Brasil poderá rever a decisão de autorização,
considerando a relevância dos fatos, tendo por base as circunstâncias de cada caso
e o interesse público, caso verifique:

I - falsidade ou omissão nas declarações e nos documentos apresentados na
instrução dos processos ou discrepância entre eles e os fatos ou dados apurados;
ou

II - circunstâncias preexistentes à decisão capazes de afetar a avaliação relativa ao
atendimento aos requisitos para as autorizações.

Parágrafo único. Nas hipóteses descritas no caput, o Banco Central do Brasil deverá
notificar a instituição para se manifestar sobre a irregularidade apurada.

Art. 34. O cancelamento de autorização ocorrerá nas seguintes hipóteses:

I - a pedido da instituição; e

II - de ofício, pelo Banco Central do Brasil.

[Página 43]

§ 1º O Banco Central do Brasil poderá condicionar o cancelamento de que trata o
inciso I do caput à liquidação ou transferência das operações no mercado de
câmbio privativas ou permitidas à instituição em razão da respectiva autorização.

§ 2º O Banco Central do Brasil poderá efetuar o cancelamento de que trata o inciso
II do caput quando constatada, a qualquer tempo, uma ou mais das seguintes
situações:

I - falta de prática habitual da realização de operações no mercado de câmbio;

II - descumprimento do plano de negócio durante o seu período de abrangência,
de forma insuficientemente justificada, a critério do Banco Central do Brasil.

§ 3º O Banco Central do Brasil, previamente ao cancelamento previsto no inciso II
do caput, deverá notificar a instituição para se manifestar sobre a intenção de
cancelamento.

Art. 35. O Banco Central do Brasil definirá os procedimentos, os documentos e as
informações exigidos nos processos de autorização previstos no art. 29, bem como
os respectivos prazos, tendo em vista o atendimento aos requisitos estabelecidos
no art. 30.

TÍTULO III
OPERAÇÃO DE CÂMBIO
CAPÍTULO I
ADIANTAMENTO SOBRE A OPERAÇÃO DE CÂMBIO

Art. 36. O adiantamento sobre operação de câmbio constitui antecipação parcial
ou total em função do preço em moeda nacional da moeda estrangeira comprada
para entrega futura, podendo ser concedido a qualquer tempo, a critério das
partes.

Art. 37. No caso de operação de câmbio de exportação, deve haver, no meio
escolhido entre as partes para sua formalização, averbação contendo a informação
sobre o valor adiantado e a informação de que referido valor serve para os fins e
efeitos do art. 75 da Lei nº 4.728, de 14 de julho de 1965, podendo ser indicados
adicionalmente a instituição do exterior fornecedora do crédito e seu país.

Parágrafo único. Nos casos de falência, liquidação extrajudicial ou intervenção na
instituição financeira que concedeu o adiantamento, para fins de satisfação das
obrigações decorrentes da utilização de créditos obtidos no exterior para
financiamento da exportação:

[Página 44]

I - os pagamentos devem ser realizados com base nos recursos recebidos e oriundos
das operações de câmbio de exportação, objeto dos adiantamentos concedidos,
observada a proporcionalidade em relação ao total dos créditos tomados;

II - os recursos recebidos do exportador devem ser utilizados no pagamento do
respectivo crédito tomado no exterior, quando houver averbação, observado que,
se houver caracterização de inadimplência do exportador, o pagamento à
instituição fornecedora do crédito ocorre na forma do inciso I.

CAPÍTULO II
LIQUIDAÇÃO, ALTERAÇÃO, PRORROGAÇÃO, CANCELAMENTO OU BAIXA DE
OPERAÇÃO DE CÂMBIO

Art. 38. A liquidação da operação de câmbio ocorre quando da entrega de ambas
as moedas, nacional e estrangeira, objeto da contratação ou de títulos que as
representem e pode ser:

I - pronta, ou seja, em até dois dias úteis da data da contratação, excluídos os dias
não úteis em pelo menos uma das praças das moedas envolvidas;

II - futura, com prazo de até mil e quinhentos dias; ou

III - a termo para operações interbancárias, com prazo de até mil e quinhentos dias.

§ 1º Caso as partes estejam de acordo, é admitida liquidação em data anterior à
data originalmente acordada, salvo em caso de vedação estabelecida nesta
Resolução.

§ 2º A liquidação no mesmo dia da contratação de câmbio é obrigatória para a
compra ou venda de moeda estrangeira em espécie, em cheques de viagem e para
o aporte e a retirada de recursos em moeda estrangeira em cartão ou outro meio
de pagamento eletrônico de uso internacional.

§ 3º O prazo mínimo para liquidação de operação de venda de moeda estrangeira
a título de doação de valor igual ou superior a R$100.000,00 (cem mil reais) é de
um dia útil.

§ 4º Se a liquidação de operação de câmbio de exportação ocorrer após a data do
embarque da mercadoria ou da prestação do serviço, o prazo máximo entre tais
eventos é de mil e quinhentos dias.

§ 5º Para fins do disposto no § 4º, considera-se data de embarque:

I - a data de emissão do conhecimento de transporte internacional;

[Página 45]

II - a data de averbação do despacho, caso não esteja disponível a data de emissão
do conhecimento de transporte internacional; ou

III - a data do documento equivalente ao conhecimento de transporte
internacional, caso a mercadoria seja admitida em regime aduaneiro especial.

Art. 39. A regularização de operação de câmbio pode ocorrer mediante
prorrogação, liquidação, cancelamento ou baixa, observados os prazos e demais
condições estabelecidas na regulamentação.

Art. 40. A instituição autorizada a operar no mercado de câmbio deve poder
comprovar a concordância do cliente para alteração de condição pactuada em
operação de câmbio, observado que é vedada a alteração do comprador, do
vendedor, do valor em moeda estrangeira, do valor em moeda nacional, da moeda
estrangeira e da taxa de câmbio.

Art. 41. O cancelamento da operação de câmbio ocorre mediante consenso das
partes, que devem declarar o desfazimento da relação jurídica anterior, com a
observância aos princípios de ordem legal e regulamentar aplicáveis.

Parágrafo único. Nos casos em que não houver consenso para o cancelamento, a
instituição autorizada a operar no mercado de câmbio pode proceder à baixa da
operação de câmbio de sua posição cambial, que representa operação contábil e
não implica rescisão unilateral do negócio nem alteração da relação contratual
existente entre as partes, observado que o contravalor em moeda nacional da baixa
é calculado com base na mesma taxa de câmbio aplicada à operação baixada.

CAPÍTULO III
PROCEDIMENTOS PARA RECOLHIMENTO DO ENCARGO FINANCEIRO

Art. 42. O comprador da moeda estrangeira receberá notificação do Banco Central
do Brasil sobre o valor do encargo financeiro de que trata o art. 7º da Lei nº 14.286,
de 2021, e o art. 1º da Resolução CMN nº 5.056, de 15 de dezembro de 2022, a ser
recolhido ao Banco Central do Brasil por meio do Sistema de Lançamentos do
Banco Central (SLB) ou por outro meio que assegure o recebimento.

§ 1º O prazo para o comprador da moeda estrangeira apresentar contestação da
cobrança é de até quinze dias a partir do recebimento da notificação de que trata
o caput.

§ 2º Não havendo contestação da cobrança, o prazo para o comprador da moeda
estrangeira efetuar o recolhimento do encargo financeiro é de até trinta dias a
partir do recebimento da notificação de que trata o caput.

[Página 46]

§ 3º Havendo contestação, e caso a decisão do Banco Central do Brasil ratifique a
cobrança de encargo financeiro, o prazo para o comprador da moeda estrangeira
efetuar o recolhimento é de até quinze dias a partir do recebimento da notificação
dessa decisão.

§ 4º O valor recolhido após o prazo de que trata o § 2º ou o § 3º, conforme o caso,
é acrescido de juros de mora e multa de mora, nos termos do art. 37 da Lei nº
10.522, de 19 de julho de 2002.

§ 5º O não pagamento do encargo acarreta a inscrição do débito na Dívida Ativa do
Banco Central do Brasil, bem como a inscrição do devedor no Cadastro Informativo
de Créditos não Quitados do Setor Público Federal (Cadin), na forma da legislação
e regulamentação em vigor.

Art. 43. Não tendo ocorrido o recolhimento do encargo financeiro em decorrência
de decretação de falência do vendedor da moeda estrangeira ou de intervenção ou
de liquidação extrajudicial do comprador da moeda estrangeira, aplicam-se os
procedimentos a seguir indicados:

I - nos casos de falência do vendedor da moeda estrangeira, cumpre ao comprador
da moeda estrangeira:

a) na data do cancelamento ou da baixa da operação de câmbio, comunicar ao
síndico da massa falida a existência de débito referente ao encargo financeiro,
identificando a operação de câmbio, o vendedor da moeda estrangeira, se houve
cancelamento ou baixa, o valor em reais a ser recolhido, a data do cancelamento
ou baixa e a legislação e regulamentação aplicáveis, encaminhando ao Banco
Central do Brasil cópia da correspondência e comprovação de recebimento pelo
destinatário;

b) quando do recebimento do valor do encargo, informar ao Banco Central do
Brasil, até o dia útil seguinte, para fins do recolhimento do encargo financeiro.

II - nos casos de intervenção ou de liquidação extrajudicial do comprador da moeda
estrangeira, cumpre ao interventor ou ao liquidante:

a) na data do cancelamento ou da baixa da operação de câmbio, providenciar a
cobrança do encargo ao vendedor da moeda estrangeira, identificando a operação
de câmbio, se houve cancelamento ou baixa, o valor em reais a ser recolhido, a
data do cancelamento ou baixa e a legislação e regulamentação aplicáveis;

b) informar ao vendedor da moeda estrangeira que o pagamento do encargo
financeiro deve ser efetuado ao comprador da moeda estrangeira e que, na
impossibilidade de o pagamento ser efetuado ao comprador da moeda estrangeira,

[Página 47]

o encargo deve ser recolhido diretamente ao Banco Central do Brasil, observado
que deve ser encaminhada ao Banco Central do Brasil cópia da correspondência
com comprovação de recebimento pelo destinatário;

c) na hipótese de vir a ser decretada a falência do vendedor da moeda estrangeira,
comunicar ao síndico da massa falida, na data do cancelamento ou da baixa da
operação de câmbio, a existência de débito referente ao encargo financeiro,
identificando a operação de câmbio, o vendedor da moeda estrangeira, se houve
cancelamento ou baixa, o valor em reais a ser recolhido, a data do cancelamento
ou baixa e a legislação e regulamentação aplicável, encaminhando ao Banco
Central do Brasil cópia da correspondência com comprovação de recebimento pelo
destinatário;

d) quando do recebimento do valor do encargo, informar ao Banco Central do
Brasil, até o dia útil seguinte, para fins do recolhimento do encargo financeiro na
forma constante deste Capítulo, ou para repasse direto ao Banco Central do Brasil
do valor recebido.

III - nos casos previstos nos incisos I ou II, o Banco Central do Brasil, após receber
comunicação do comprador da moeda estrangeira sobre o recebimento do valor
do encargo financeiro, poderá reapresentar a notificação por intermédio do SLB,
ou por outro meio que assegure o recebimento, sendo, nesse caso, assegurado o
prazo de um dia útil, que se inicia na data do recebimento da notificação, para o
recolhimento do encargo financeiro ou a dispensa da reapresentação da
notificação, nos casos de repasse direto.

Art. 44. No caso de intervenção ou liquidação extrajudicial do comprador da
moeda estrangeira sem a decretação de falência do vendedor da moeda
estrangeira, há o acréscimo de juros de mora e multa de mora, nos termos do art.
37 da Lei nº 10.522, de 2002, implicando, quando for o caso, a inscrição do débito
na Dívida Ativa do Banco Central do Brasil, e do nome do devedor no Cadin.

Parágrafo único. Na impossibilidade de pagamento ao comprador sob intervenção
ou em liquidação extrajudicial, o devedor do encargo deve fazer o recolhimento
diretamente ao Banco Central do Brasil, hipótese em que o comprador fica
desobrigado do recolhimento do encargo financeiro.

CAPÍTULO IV
POSIÇÃO DE CÂMBIO E LIMITE OPERACIONAL

Art. 45. A posição de câmbio é representada pelo saldo das operações de câmbio
(compra e venda de moeda estrangeira, de títulos e documentos que as
representem e de ouro-instrumento cambial), registradas no Sistema Câmbio.

[Página 48]

§ 1º Para todos os fins e efeitos a posição de câmbio é sensibilizada na data da
informação ao Banco Central do Brasil da contratação da operação de câmbio, à
exceção das operações interbancárias a termo, nas quais a posição de câmbio é
sensibilizada a partir do segundo dia útil anterior à sua liquidação.

§ 2º A equivalência em dólares dos Estados Unidos é apurada com aplicação das
cotações para contabilidade das paridades disponíveis no Sistema de Informações
Banco Central (Sisbacen) do dia útil anterior, observando-se que:

I - para moedas do tipo “A”, deve ser utilizada a paridade de venda da seguinte
forma: valor na moeda estrangeira dividido pela paridade;

II - para moedas do tipo “B”, deve ser utilizada a paridade de compra da seguinte
forma: valor na moeda estrangeira multiplicado pela paridade.

§ 3º Relativamente a limites para posição de câmbio:

I - não há limite para as posições de câmbio comprada ou vendida dos bancos e
caixas econômicas autorizados a operar no mercado de câmbio;

II - não há limite para a posição de câmbio comprada das demais instituições
autorizadas a funcionar pelo Banco Central do Brasil, sendo a posição de câmbio
vendida limitada a zero.

TÍTULO IV
OPERAÇÕES COM CLIENTES
CAPÍTULO ÚNICO

Art. 46. As receitas de exportação podem ser ingressadas ou recebidas no Brasil
em reais ou em moeda estrangeira, independentemente da moeda constante da
negociação comercial, prévia ou posteriormente ao embarque da mercadoria ou à
prestação dos serviços, observadas as disposições gerais sobre o ingresso e o
recebimento de recursos no Brasil.

§ 1º O recebimento do valor da exportação pode ocorrer, entre outras formas,
mediante crédito em conta mantida no exterior por instituição autorizada a operar
no mercado de câmbio no País, a critério das partes.

§ 2º A operação de câmbio de exportação pode ser celebrada prévia ou
posteriormente ao embarque da mercadoria ou da prestação do serviço,
observados os prazos estabelecidos nesta Resolução.

[Página 49]

Art. 47. O pagamento de importação pode ser realizado em reais ou em moeda
estrangeira, observado que a antecipação desse pagamento pode ocorrer em até
trezentos e sessenta dias anteriores à data prevista para:

I - o embarque, nos casos de mercadorias importadas diretamente do exterior em
caráter definitivo, inclusive sob o regime de drawback, ou quando destinadas a
admissão na Zona Franca de Manaus, em Área de Livre Comércio ou em Entreposto
Industrial;

II - a nacionalização de mercadorias que tenham sido admitidas sob outros regimes
aduaneiros especiais ou atípicos.

Parágrafo único. O pagamento antecipado de importação pode ser efetuado com
antecipação de até mil e oitocentos dias em relação às datas indicadas nos incisos
I e II do caput nos casos de:

I - máquinas e equipamentos com longo ciclo de produção ou de fabricação sob
encomenda, desde que compatível com o ciclo de produção ou de comercialização
do bem; ou

II - comprovação de impossibilidade de embarque ou de nacionalização do bem por
fatores alheios à vontade do importador.

Art. 48. Ao não residente transitoriamente no País é permitido o recebimento de
moeda estrangeira em espécie sem realização de operação de câmbio referente a
ordem de pagamento a seu favor.

TÍTULO V
SERVIÇO DE PAGAMENTO OU TRANSFERÊNCIA INTERNACIONAL (eFX)
(Denominação alterada pela Resolução BCB 337, de 22/08/2023)

CAPÍTULO I
DISPOSIÇÕES GERAIS

Art. 49. Para efeitos desta Resolução, é considerado eFX o serviço de pagamento
ou transferência internacional que, por meio de operação de câmbio ou mediante
movimentação em conta em reais de não residente realizada na forma prevista
nesta Resolução, viabiliza:

I - aquisição de bens e serviços, no País ou no exterior, que ocorra:

a) de forma presencial; ou

[Página 50]

b) mediante solução de pagamento digital oferecida pelo prestador de eFX e
integrada a plataforma de comércio eletrônico.

II - transferência unilateral, limitada a US$10.000,00 (dez mil dólares dos Estados
Unidos) ou o seu equivalente em outras moedas;

III - transferência de recursos entre conta no País e conta no exterior de mesma
titularidade, limitada a US$10.000,00 (dez mil dólares dos Estados Unidos) ou o
seu equivalente em outras moedas, com as seguintes características:

a) conta de depósito ou conta de pagamento pré-paga mantida no País em
instituições financeiras e demais instituições autorizadas a funcionar pelo Banco
Central do Brasil ou em instituições de pagamento que, em virtude de sua adesão
ao Pix, integrem o SPB; e

b) conta de depósito ou conta de pagamento mantida em instituição no exterior
sujeita a efetiva supervisão prudencial e de conduta ou integrante de grupo
financeiro sujeito a efetiva supervisão consolidada.

IV - saque no País ou no exterior.

§ 1º Não são admitidos fracionamentos de operações realizadas mediante
prestação de eFX para fins de utilização de prerrogativa prevista neste Capítulo.

§ 2º Podem atuar como prestadores de eFX:

I - bancos múltiplos, bancos comerciais, caixas econômicas, bancos de
investimento, bancos de desenvolvimento, bancos de câmbio, agências
defomento, sociedades de crédito, financiamento e investimento, sociedades
corretoras de títulos e valores mobiliários, sociedades distribuidoras de títulos e
valores mobiliários, sociedades corretoras de câmbio e instituições de pagamento
autorizadas a funcionar pelo Banco Central do Brasil que prestem serviço como
emissor de moeda eletrônica, emissor de instrumento de pagamento pós-pago ou
credenciador, independentemente de autorização para operar no mercado de
câmbio, para viabilizar as atividades previstas nos incisos I a IV do caput;

II - instituições de pagamento não previstas no inciso I deste parágrafo, para
viabilizar:

a) as atividades previstas na alínea “a” do inciso I e no inciso IV do caput, sem
limitação de valor, quando estiverem atuando na qualidade de emissor de moeda
eletrônica, de emissor de instrumento de pagamento pós-pago ou de credenciador
no âmbito de arranjo de pagamento autorizado pelo Banco Central do Brasil;

[Página 51]

b) a aquisição de bens e serviços constante na alínea “b” do inciso I do caput,
limitado a US$10.000,00 (dez mil dólares dos Estados Unidos) ou o seu equivalente
em outras moedas, desde que não haja impedimento legal, regulamentar ou
próprio para que tais pessoas jurídicas prestem esse serviço.

III - outras pessoas jurídicas exclusivamente para viabilizar a aquisição de bens e
serviços constante na alínea “b” do inciso I do caput, limitado a US$10.000,00 (dez
mil dólares dos Estados Unidos) ou o seu equivalente em outras moedas, desde que
não haja impedimento legal, regulamentar ou próprio para que tais pessoas
jurídicas prestem esse serviço.

Art. 50. As operações de câmbio e as movimentações em contas em reais de não
residentes para viabilizar pagamentos, recebimentos e transferências de clientes
de prestadores de eFX são realizadas de forma individualizada ou consolidada, na
forma prevista nesta Resolução, e devem observar classificação própria, quando
requerida (Redação dada pela Resolução BCB 337, de 22/08/2023).

§ 1º É vedado qualquer tipo de compensação envolvendo os pagamentos e os
recebimentos referidos no caput.

§ 2º A instituição autorizada a operar no mercado de câmbio, no seu
relacionamento com prestador de eFX não autorizado a funcionar pelo Banco
Central do Brasil, deve:

I - manter os dados cadastrais da instituição não autorizada; e

II - ser capaz de comprovar perante o Banco Central do Brasil que se certificou de
que o prestador de eFX não autorizado adota política, procedimentos e controles
internos para cumprir os deveres e as obrigações previstos nesta Resolução.

§ 3º As informações e os documentos necessários ao cumprimento do disposto no
§ 2º devem ser mantidos pela instituição autorizada a operar em câmbio à
disposição do Banco Central do Brasil pelo prazo de dez anos contados a partir da
operação de compra ou venda de moeda estrangeira realizada por meio da referida
instituição ou da movimentação em conta em reais de não residente (Redação dada
pela Resolução BCB 337, de 22/08/2023).

Art. 51. O prestador de eFX deve assegurar-se de que seu cliente no País foi
informado de forma clara e tempestiva sobre:

I - as responsabilidades do prestador de eFX quanto ao serviço;

II - a natureza e as condições do serviço prestado; e

[Página 52]

III - as condições específicas relacionadas aos direitos do cliente de acordo com o
instrumento de pagamento utilizado para a entrega dos reais ao prestador de eFX.
Parágrafo único. O prestador de eFX deve ser capaz de comprovar a ciência e a
concordância prévia do cliente em relação às responsabilidades e condições de que
trata o caput.

Art. 52. O prestador de eFX deve assegurar-se de que seu cliente tenha acesso a
demonstrativo ou fatura das operações, contendo, no mínimo, a discriminação da
operação, incluindo sua data, as partes envolvidas, o valor em moeda nacional,
eventual tarifa cobrada pela operação, além dos subtotais relativos aos saques,
aos pagamentos e às transferências realizadas.

Parágrafo único. Deve ser observado adicionalmente em relação às operações
denominadas em moeda estrangeira que:

I - o demonstrativo ou fatura deve conter a identificação da moeda estrangeira e o
valor na referida moeda da operação;

II - no caso de saque no exterior ou de aquisição de bens e serviços do exterior
efetuados com cartão de uso internacional, o prestador de eFX deve, ainda,
discriminar no demonstrativo ou fatura das operações de que trata o caput
(Redação dada pela Resolução BCB 337, de 22/08/2023):

a) o valor equivalente em dólar dos Estados Unidos na data de cada operação;

b) a taxa de conversão do dólar dos Estados Unidos para reais na data de cada
operação; e

c) o valor equivalente em reais, resultante da conversão do valor da alínea “a”,
utilizando a taxa de conversão de que trata a alínea “b”.

Art. 53. Aplicam-se as seguintes regras ao cartão e aos outros meios de pagamento
eletrônico de uso internacional com valores em moeda estrangeira previamente
aportados no País:

I - as operações de saque e de pagamento são condicionadas à existência de
recursos previamente aportados;

II - é permitido o aporte de valores denominados em mais de uma moeda
estrangeira; e

III - é dispensada a prestação de informação ao Banco Central do Brasil sobre a
conversão, entre moedas estrangeiras, de saldo previamente aportado.

[Página 53]

CAPÍTULO II
ENTREGA E RECEBIMENTO DE REAIS NO PAÍS

Art. 54. O pagamento ou o recebimento no País decorrente de operação realizada
por meio de prestador de eFX deve ser realizado exclusivamente em reais.

§ 1º O valor em reais de que trata o caput é final, sendo vedada qualquer indexação
a moeda estrangeira ou conversão subsequente.

§ 2º A taxa de conversão para reais da operação ou de eventual devolução de
recursos deve referir-se à data do respectivo evento, observado que, se o
pagamento de reais pelo cliente ao prestador de eFX ocorrer posteriormente à data
da operação, o prestador de eFX pode ofertar ao seu cliente a possibilidade de
conversão das obrigações pelo valor equivalente em reais no dia do respectivo
pagamento, condicionada à expressa aceitação do cliente.

Art. 55. Nos pagamentos ou transferências internacionais a partir do País, a
entrega de reais pelo cliente ao prestador de eFX deve ser realizada a partir de:

I - conta de depósito ou de pagamento de titularidade do cliente mantida em
instituições financeiras e demais instituições autorizadas a funcionar pelo Banco
Central do Brasil ou em instituições de pagamento que, em virtude de sua adesão
ao Pix, integrem o SPB; ou

II - boleto de pagamento tendo como pagador o cliente no País e como beneficiário
o prestador de eFX.

Art. 56. Nos pagamentos ou transferências internacionais a partir do exterior, a
entrega de reais pelo prestador de eFX ao seu cliente deve ser realizada mediante
crédito à conta de depósito ou de pagamento pré-paga de titularidade do cliente
mantida em instituições financeiras e demais instituições autorizadas a funcionar
pelo Banco Central do Brasil ou em instituições de pagamento que, em virtude de
sua adesão ao Pix, integrem o SPB.

Parágrafo único. Excetuam-se do disposto no caput as operações de saque de
recursos realizadas no País utilizando cartão ou outro meio de pagamento
eletrônico de uso internacional emitido no exterior.

TÍTULO VI
OPERAÇÕES ENTRE INSTITUIÇÕES AUTORIZADAS E COM INSTITUIÇÕES
FINANCEIRAS NO EXTERIOR
CAPÍTULO I
OPERAÇÕES ENTRE INSTITUIÇÕES AUTORIZADAS A OPERAR NO MERCADO DE
CÂMBIO

[Página 54]

Art. 57. As operações realizadas no mercado interbancário são aquelas realizadas
entre instituições autorizadas a operar no mercado de câmbio.

§ 1º As operações no mercado interbancário podem ser celebradas para liquidação
pronta, futura ou a termo, havendo vedação para seu cancelamento, baixa,
prorrogação ou liquidação antecipada.

§ 2º A entrega dos reais nas operações de câmbio de que trata este Capítulo é
efetuada por meio de comando próprio no Sistema de Transferência de Reservas
(STR).

§ 3º Para as operações de câmbio interbancárias a termo, a taxa de câmbio é
livremente pactuada entre as partes e deve espelhar o preço negociado da moeda
estrangeira para a data da liquidação da operação de câmbio, observado que, em
referida data, há a entrega efetiva e simultânea das moedas, nacional e
estrangeira, não sendo admitidos adiantamentos das moedas.

§ 4º A compra e a venda de moeda estrangeira por arbitragem são registradas com
atribuição, às moedas compradas e vendidas, do mesmo contravalor em reais.

§ 5º As operações no mercado interbancário são realizadas com ou sem
intermediação de câmara ou prestador de serviços de compensação e de liquidação
cujo sistema tenha sido autorizado pelo Banco Central do Brasil para liquidação de
operações de câmbio.

Art. 58. A formalização da operação de câmbio ocorre com:

I - no caso de operação realizada no País sem intermediação de câmara ou
prestador de serviços de compensação e de liquidação, a confirmação, pela
instituição vendedora da moeda estrangeira, dos dados da operação registrados no
Sistema Câmbio pela instituição compradora da moeda estrangeira;

II - no caso de operação realizada por intermédio de câmara ou de prestador de
serviços de compensação e de liquidação:

a) a confirmação no Sistema Câmbio, pela câmara ou prestador de serviços de
compensação e de liquidação, dos dados da operação registrados pela instituição
compradora da moeda estrangeira e confirmados pela instituição vendedora da
moeda estrangeira, quando não houver uso de sistemas de negociação sem
identificação da contraparte (tela cega);

b) a verificação da identidade, no Sistema Câmbio, das chaves contidas nas
mensagens enviadas pela instituição compradora e pela instituição vendedora com
a chave enviada pela câmara ou prestador de serviços de compensação e de

[Página 55]

liquidação, quando houver uso de sistemas de negociação sem identificação da
contraparte (tela cega).

III - no caso de arbitragem no País, a confirmação, pela instituição contraparte da
operação, dos dados registrados no Sistema Câmbio pela outra instituição parte da
operação;

IV - no caso de operação realizada com instituição no exterior, o registro, pela
instituição no País, dos dados no Sistema Câmbio;

V - no caso de operação realizada com o Banco Central do Brasil, o registro
realizado de forma automática no Sistema Câmbio dispensa confirmação pela
contraparte.

Art. 59. No caso de operação realizada sem intermediação de câmara ou prestador
de serviços de compensação e de liquidação, a confirmação da operação no
Sistema Câmbio pela instituição vendedora da moeda estrangeira implica a
formalização de duas operações de câmbio onde figuram como partes a instituição
compradora e a instituição vendedora da moeda estrangeira.

Art. 60. No caso de operação realizada por intermédio de câmara ou prestador de
serviços de compensação e de liquidação, a confirmação ou a verificação da
identidade no Sistema Câmbio implica a formalização de quatro operações de
câmbio, da seguinte forma:

I - um par de operações de câmbio em que figuram como partes a instituição
compradora da moeda estrangeira e a câmara ou prestador de serviços de
compensação e de liquidação; e

II - um par de operações de câmbio em que figuram como partes a instituição
vendedora da moeda estrangeira e a câmara ou prestador de serviços de
compensação e de liquidação.

Art. 61. No caso de operação de câmbio realizada sem intermediação de câmara
ou prestador de serviços de compensação e de liquidação:

I - a instituição compradora da moeda estrangeira registra os dados da operação
no Sistema Câmbio, devendo efetuar tal registro em até trinta minutos após o
ajuste das condições com a instituição vendedora da moeda estrangeira;

II - a instituição vendedora da moeda estrangeira confirma no Sistema Câmbio os
dados e elementos da operação no decorrer dos primeiros trinta minutos, que se
iniciam com o registro feito pela instituição compradora da moeda estrangeira;

[Página 56]

III - duas operações de câmbio são registradas sem liquidação automática pelo
Sistema Câmbio;

IV - as instituições compradora e vendedora da moeda estrangeira devem registrar
a liquidação das operações no Sistema Câmbio;

V - a operação registrada pela instituição compradora da moeda estrangeira e não
confirmada pela instituição vendedora da moeda estrangeira no prazo indicado no
inciso II é bloqueada pelo sistema, ficando a reativação do registro no Sistema
Câmbio a cargo da instituição compradora da moeda estrangeira;

VI - no caso de operação com o Banco Central do Brasil, a informação à instituição
contraparte sobre o registro é prestada pelo Sistema Câmbio.

Art. 62. No caso de operação de câmbio realizada por intermédio de câmara ou
prestador de serviços de compensação e de liquidação quando não houver uso de
sistemas de negociação sem identificação da contraparte (tela cega):

I - a instituição compradora da moeda estrangeira registra os dados da operação
no Sistema Câmbio, devendo efetuar tal registro em até trinta minutos após o
ajuste das condições com o banco vendedor da moeda estrangeira;

II - a instituição vendedora da moeda estrangeira confirma os dados e elementos
da operação no decorrer dos primeiros trinta minutos, que se iniciam com o
registro feito pela instituição compradora da moeda estrangeira, devendo ser
observado, nos casos em que a confirmação seja devida após o fechamento da
grade horária do mercado interbancário, o horário de fechamento da grade
adicionado de quinze minutos para tal providência, respeitado o prazo máximo de
trinta minutos;

III - a câmara ou prestador de serviços de compensação e de liquidação confirma
os dados e elementos da operação no decorrer dos primeiros trinta minutos, que
se iniciam com a confirmação feita pela instituição vendedora da moeda
estrangeira, devendo ser observado, nos casos em que a confirmação seja devida
após o fechamento da grade horária do mercado interbancário, o horário de
fechamento da grade adicionado de trinta minutos para tal providência, respeitado
o prazo máximo de trinta minutos;

IV - quatro operações de câmbio são registradas no Sistema Câmbio e o evento de
liquidação de cada operação de câmbio é efetuado automaticamente pelo Sistema
Câmbio;

V - a operação registrada pela instituição compradora da moeda estrangeira e não
confirmada pela instituição vendedora da moeda estrangeira no prazo indicado no

[Página 57]

inciso II é bloqueada pelo sistema, ficando a reativação do registro no Sistema
Câmbio a cargo da instituição compradora da moeda estrangeira;

VI - a operação confirmada pela instituição vendedora da moeda estrangeira e não
confirmada pela câmara ou prestador de serviços de compensação e de liquidação
no prazo indicado no inciso III é bloqueada pelo sistema, ficando a reativação do
registro no Sistema Câmbio a cargo da instituição compradora da moeda
estrangeira e as respectivas confirmações a cargo da instituição vendedora da
moeda estrangeira e da câmara ou prestador de serviços de compensação e de
liquidação.

Art. 63. No caso de operação de câmbio realizada por intermédio de câmara ou
prestador de serviços de compensação e de liquidação com uso de sistemas de
negociação sem identificação da contraparte (tela cega):

I - a câmara ou prestador de serviços de compensação e de liquidação,
imediatamente após o fechamento da operação no sistema de negociação, pelas
instituições compradora e vendedora da moeda estrangeira, registra os dados da
operação no Sistema Câmbio e os informa às instituições compradora e vendedora;

II - as instituições compradora e vendedora, após recebimento da informação da
câmara ou prestador de serviços de compensação e de liquidação, confirmam os
dados da operação, em até trinta minutos, no sistema Câmbio, observado o prazo
limite de trinta minutos após o fechamento da grade horária do mercado
interbancário;

III - quatro operações de câmbio são registradas no Sistema Câmbio e o evento de
liquidação de cada operação de câmbio é efetuado automaticamente pelo Sistema
Câmbio;

IV - a inobservância do contido no inciso II implica o expurgo das referidas
operações do Sistema Câmbio, as quais serão consideradas inexistentes.

Art. 64. No caso de operação de arbitragem no País, a confirmação no Sistema
Câmbio pela instituição contraparte implica a celebração de dois pares de
operações de câmbio, em que figuram como partes contratantes a instituição
compradora e a instituição vendedora das moedas estrangeiras, sendo cada par de
operações relativo a cada moeda arbitrada, observado que:

I - uma instituição parte registra os dados da operação no Sistema Câmbio,
devendo efetuar tal registro em até trinta minutos após o ajuste das condições com
a instituição contraparte da operação;

[Página 58]

II - a instituição contraparte da operação confirma no Sistema Câmbio os dados e
elementos da operação no decorrer dos primeiros trinta minutos, que se iniciam
com o registro feito pela outra instituição parte da operação;

III - quatro operações de câmbio são registradas no Sistema Câmbio conforme o
caput, que não são liquidadas de forma automática pelo Sistema Câmbio;

IV - as instituições parte e contraparte da operação devem liquidar as operações
no Sistema Câmbio.

Parágrafo único. A operação registrada pela instituição parte e não confirmada
pela instituição contraparte no prazo indicado no inciso II é bloqueada pelo
sistema, ficando a reativação do registro no Sistema Câmbio a cargo da instituição
parte da operação.

CAPÍTULO II
OPERAÇÕES COM INSTITUIÇÕES FINANCEIRAS NO EXTERIOR

Art. 65. A instituição autorizada a operar no mercado de câmbio pode realizar
operações com instituição do exterior sujeita à regulação e à supervisão financeira
em seu país de origem.

§ 1º A compra e a venda de moeda estrangeira por arbitragem devem ser
registradas na forma estabelecida pelo Banco Central do Brasil, atribuindo-se às
moedas compradas e vendidas o mesmo contravalor em reais.

§ 2º A instituição bancária autorizada a operar no mercado de câmbio pode realizar
operação de compra ou de venda de moeda estrangeira com instituição do exterior
sujeita à regulação e à supervisão financeira em seus país de origem, em
contrapartida a reais em espécie recebidos do ou enviados para o exterior, na forma
da regulamentação em vigor, sendo obrigatório:

I - conduzir as operações em apenas uma agência previamente registrada no
Sistema Câmbio pelo diretor responsável pelas operações de que trata esta
Resolução;

II - manter prova de que a entrada ou a saída dos recursos no ou do País foi objeto
de declaração na forma da regulamentação em vigor;

III - obter previamente o CNPJ da instituição do exterior sujeita à regulação e à
supervisão financeira em seus país de origem contraparte na operação; e

[Página 59]

IV - utilizar cédulas novas para envio ao exterior, observado que a instituição
bancária responsável pela remessa de cédulas ao exterior também é responsável
pela manutenção de registro e controle da numeração das cédulas enviadas.

CAPÍTULO III
OPERAÇÕES COM OURO

Art. 66. O ouro classificado como instrumento cambial consta da posição de
câmbio de instituição autorizada a operar no mercado de câmbio e decorre de
operação:

I - de compra de ouro-ativo financeiro da própria instituição;

II - de compra ou de venda de ouro do ou ao Banco Central do Brasil com essa
finalidade;

III - de compra ou de venda de ouro-instrumento cambial de outra instituição
autorizada a operar no mercado de câmbio; ou

IV - de arbitragem com outra instituição autorizada a operar no mercado de câmbio
ou com instituição do exterior sujeita à regulação e à supervisão financeira em seu
país de origem, na forma prevista nesta Resolução.

§ 1º As disposições normativas relativas às operações com ouro-instrumento
cambial são as mesmas das operações de compra e de venda de moeda estrangeira,
inclusive no tocante à composição e aos limites de posição de câmbio e à
possibilidade de operações de arbitragem.

§ 2º Uma vez incorporado à posição de câmbio da instituição, o ouro somente pode
ser negociado com outra instituição autorizada a operar no mercado de câmbio,
com instituição do exterior sujeita à regulação e à supervisão financeira em seu
país de origem ou com o Banco Central do Brasil, observadas as mesmas condições
estabelecidas para a negociação de moeda estrangeira.

§ 3º As operações de que trata este Capítulo devem ser registradas como moeda
própria no Sistema Câmbio, tomando por unidade o grama.

TÍTULO VII
CONTAS DE NÃO RESIDENTES EM REAIS
CAPÍTULO ÚNICO

Art. 67. As instituições autorizadas a operar no mercado de câmbio podem abrir,
manter e encerrar contas de depósito e contas de pagamento em reais tituladas

[Página 60]

por não residentes nas mesmas condições nas quais podem abrir e manter tais
contas tituladas por residentes, ressalvadas as disposições deste Título.

Parágrafo único. Cada movimentação em conta de pagamento pré-paga em reais
de que trata este Título é limitada a R$100.000,00 (cem mil reais), excetuada
movimentação em contrapartida a operação de compra ou de venda de moeda
estrangeira.

Art. 68. A movimentação de recurso de interesse de terceiro em conta de que trata
este Título somente é permitida se a conta for titulada por instituição domiciliada
ou com sede no exterior sujeita à regulação e à supervisão financeira em seu país
de origem e mantida em banco autorizado a operar no mercado de câmbio,
observado que, neste caso, a instituição mantenedora da conta:

I - pode requisitar ou dispensar, conforme sua avaliação, informações e
documentos comprobatórios, considerando a avaliação do cliente e as
características da operação (Redação dada pela Resolução BCB 337, de
22/08/2023); e

II - deve manter à disposição do Banco Central do Brasil e conservar pelo período
mínimo de dez anos, contados do término do exercício em que ocorra a
movimentação, as informações e documentos comprobatórios que tenham sido
coletados (Redação dada pela Resolução BCB 337, de 22/08/2023).

III - (Revogado pela Resolução BCB 337, de 22/08/2023).

§ 1º A movimentação de que trata o caput de valor superior a R$10.000,00 (dez mil
reais) deve ter como contrapartida crédito ou débito à conta de depósito ou de
pagamento mantida em instituições financeiras e demais instituições autorizadas
a funcionar pelo Banco Central do Brasil ou em instituições de pagamento que, em
virtude de sua adesão ao Pix, integrem o SPB, observado que referida
movimentação:

I - também pode ser realizada por meio de cheque de emissão do pagador, na forma
de sua regulamentação;

II - não é permitida em contrapartida a crédito à conta de pagamento pós-paga.

§ 2º A movimentação de que trata o caput de até R$10.000,00 (dez mil reais) pode
ser realizada com qualquer meio de pagamento em uso no mercado financeiro,
inclusive espécie, observado o inciso II do § 1º.

Art. 68-A. No caso de movimentação de recurso de interesse de terceiro em conta
de que trata este Título, a instituição mantenedora da conta deve obter do cliente

[Página 61]

a informação sobre a finalidade da movimentação, quando exigida no Anexo II,
devendo, para esse fim, apresentar ou tornar disponível, em livre formato que
permita seu claro entendimento pelo cliente, os códigos constantes dos Anexos III,
IV ou V, conforme o caso (Incluído pela Resolução BCB 337, de 22/08/2023).

§ 1º Devem também ser prestadas as informações constantes do Anexo VI, com a
indicação efetuada pelo cliente, sobre o pagador ou recebedor no exterior e sua
relação de vínculo com o cliente (Incluído pela Resolução BCB 337, de
22/08/2023).

§ 2º A pedido do cliente (Parágrafo e incisos incluídos pela Resolução BCB 337, de
22/08/2023):

I - é facultada a utilização da lista de códigos constante do Anexo IV para
movimentação de até R$250.000,00 (duzentos e cinquenta mil reais), mediante
concordância da instituição mantenedora;

II - a instituição mantenedora deve ajustar informação já prestada pelo cliente
relativa à movimentação.

§ 3º As instituições mantenedoras prestarão orientação e suporte técnico, inclusive
por meio virtual, para os clientes que necessitarem de apoio para a correta
classificação da finalidade da movimentação (Incluído pela Resolução BCB 337, de
22/08/2023).

TÍTULO VIII
CONTAS EM MOEDA ESTRANGEIRA NO PAÍS
CAPÍTULO ÚNICO

Art. 69. As contas de depósito em moeda estrangeira no País podem ser abertas,
mantidas e encerradas por instituições bancárias autorizadas a operar no mercado
de câmbio.

§ 1º Os recursos mantidos nas contas de depósito em moeda estrangeira podem
ser livremente aplicados no mercado internacional, salvo eventual restrição
estabelecida em legislação especial ou por órgão regulador.

§ 2º Ficam mantidas as autorizações concedidas até a data de entrada em vigor
desta Resolução para a abertura e manutenção das contas em moeda estrangeira.

Art. 70. Podem ser mantidas as contas de depósito em moeda estrangeira tituladas
por:

[Página 62]

I - agência de turismo ou prestador de serviços turísticos, tendo a conta
movimentação restrita a recebimentos e pagamentos decorrentes de sua atuação
no turismo emissivo ou receptivo;

II - embaixadas, legações estrangeiras e organismos internacionais reconhecidos
pelo Governo brasileiro, tendo a conta livre movimentação;

III - empresa que atue na prestação de serviços postais, conforme o art. 2º da Lei
nº 6.538, de 1978, tendo a conta movimentação restrita ao curso das sistemáticas
de vale postal internacional, vedada movimentação de valores em espécie;

IV - emissores de cartões de crédito de uso internacional, tendo a conta
movimentação restrita à efetivação de pagamentos ao exterior pela utilização em
lojas francas e no exterior de cartões emitidos no Brasil, vedada movimentação de
valores em espécie;

V - estrangeiro transitoriamente no País e brasileiro não residente, observado que
seus créditos são restritos a recursos oriundos do exterior e que os débitos se
sujeitam a operação de câmbio no caso de transferência no Brasil para residente;

VI - entidades da administração direta e indireta da União, dos Estados, dos
Municípios e do Distrito Federal, sendo que a conta deve ser vinculada a operação
de crédito externo (contas designadas) concedido por organismos internacionais e
agências governamentais estrangeiras e que, no caso de contas da União, devem
ser observadas as condições estabelecidas pela Secretaria do Tesouro Nacional;

VII - empresas encarregadas da implementação e desenvolvimento de projetos do
setor energético;

VIII - sociedades seguradoras, resseguradoras e corretoras de resseguro;

IX - transportadores não residentes;

X - instituições autorizadas a operar no mercado de câmbio; e

XI - empresas detentoras de direitos de exploração e produção de petróleo e gás
natural.

Art. 71. As empresas encarregadas da implementação e desenvolvimento, no País,
de projetos relacionados com a prospecção, produção, exploração, processamento
e transporte de petróleo e de gás natural e com a geração e transmissão de energia
elétrica podem ser titulares das contas de que trata este Título, observado que:

[Página 63]

I - para a abertura das contas, o titular deve possuir ato público de liberação
(concessão, autorização ou permissão) da Agência Nacional de Energia Elétrica
(Aneel) ou da Agência Nacional do Petróleo, Gás Natural e Biocombustíveis (ANP)
ou, ainda, de órgão estadual responsável pela delegação, quando for o caso;

II - somente podem ter em depósito recursos em moedas estrangeiras equivalentes
aos reais recebidos em decorrência das atividades previstas no caput e destinados
à liquidação de compromissos e obrigações no exterior previstos na
regulamentação do Banco Central do Brasil;

III - os saques sobre as contas somente podem ser efetuados para remessa ao
exterior em pagamento de obrigações que integrem os projetos previstos no caput
e, no caso de consórcio, para conta em moeda estrangeira titulada por empresa do
mesmo consórcio, devendo ser observada a legislação cambial vigente;

IV - no caso de consórcio, todas as empresas participantes podem ser titulares de
contas em moeda estrangeira, desde que venham a auferir receitas decorrentes
das atividades previstas no caput;

V - para a abertura da conta, o interessado deve apresentar manifestação do Banco
Central do Brasil de que a empresa está contemplada pelas disposições desta
Resolução.

§ 1º A extinção dos efeitos do ato público de liberação de que trata o inciso I
implica a perda da faculdade de manutenção da conta em moeda estrangeira.

§ 2º Na hipótese do § 1º, deve ser providenciado o encerramento da conta em
moeda estrangeira e a conversão para reais do saldo porventura existente no prazo
de trinta dias, mediante realização de operação de câmbio, na forma da
regulamentação em vigor.

Art. 72. As sociedades seguradoras, resseguradores locais, resseguradores
admitidos e corretoras de resseguros podem ser titulares de contas em moeda
estrangeira, observado que:

I - a movimentação de conta em moeda estrangeira titulada por sociedade
seguradora, ressegurador local ou ressegurador admitido é restrita a:

a) recebimentos e pagamentos de prêmios, indenizações, recuperações de crédito
e outros valores previstos em contratos de seguro, resseguro, retrocessão e
cosseguro, celebrados em moeda estrangeira;

b) rendimentos da aplicação dos saldos existentes, observada a regulamentação
relativa à aplicação de recursos garantidores;

[Página 64]

c) acolhimentos em depósito de recursos para manutenção do saldo mínimo da
conta, definido pelo Conselho Nacional de Seguros Privados (CNSP), no caso de
ressegurador admitido, observado que o saque dos recursos destinados à
manutenção de saldo mínimo somente pode ser promovido após a liberação do
vínculo pela Superintendência de Seguros Privados (Susep).

II - o uso da conta em moeda estrangeira titulada por corretora de resseguros é
restrita ao trânsito dos valores referentes a prêmios, indenizações e outros valores
previstos em contratos de resseguro celebrados em moeda estrangeira, observado
que os valores em moeda estrangeira referentes à remuneração da corretora de
resseguros devem ser imediatamente convertidos para reais, mediante
contratação e liquidação do câmbio;

III - os valores nelas mantidos podem ser livremente convertidos para reais,
mediante contratação e liquidação de operação de câmbio, na forma da
regulamentação em vigor, com exceção dos valores relativos às aplicações dos
recursos garantidores das provisões técnicas que tenham vedada a sua conversão
para reais;

IV - é dispensada operação de câmbio para transferência de recursos entre tais
contas;

V - a perda da autorização pela Susep implica a perda da faculdade de manutenção
da conta em moeda estrangeira, devendo ser providenciado seu encerramento e
promovida a conversão para reais do saldo porventura existente no prazo de trinta
dias, mediante realização de operação de câmbio, na forma da regulamentação em
vigor.

Art. 73. Os transportadores não residentes podem ser titulares de conta de
depósito em moeda estrangeira, que pode ser alimentada com recursos resultantes
da conversão de moeda nacional auferida no País em decorrência de suas
atividades.

Art. 74. Nas operações de câmbio para fins de transferência ao exterior de receitas
auferidas no País pelos transportadores não residentes é facultada a manutenção
transitória de valores estimados para futura utilização no pagamento de despesas
incorridas no País.

§ 1º As operações de câmbio tratadas no caput são liquidadas pelo valor
integralmente contratado, podendo ocorrer o envio de ordem de pagamento ao
exterior por valor inferior ao da operação de câmbio correspondente e a diferença
servir para o pagamento das despesas incorridas no País pelo transportador não

[Página 65]

residente, devendo, quando do pagamento de tais despesas, serem celebradas as
respectivas operações de câmbio na forma da regulamentação em vigor.

§ 2º Para fins de apuração dos valores em moeda estrangeira referentes às
despesas incorridas no País tratadas no § 1º, a critério das partes, pode ser utilizada
qualquer taxa de câmbio que esteja entre as taxas mínima e máxima disponíveis no
Sisbacen, no período referente à permanência do veículo transportador em
território nacional.

§ 3º Caso o valor estimado para o custeio de que trata o caput tenha sido superior
ao efetivamente despendido no Brasil, deve ser enviada nova ordem de pagamento
ao exterior com o valor não utilizado no País.

Art. 75. As instituições autorizadas a operar no mercado de câmbio podem ser
titulares de contas em moeda estrangeira, observado que a débito dessas contas
podem os bancos depositários:

I - acatar instrumentos em cobrança de bancos do exterior ou de bancos no País
autorizados a operar no mercado de câmbio;

II - acolher solicitações de seus respectivos titulares para:

a) saque ou emissão de ordens de pagamento em moeda estrangeira sobre o
exterior;

b) efetuar pagamentos de obrigações no País em moeda nacional;

c) conversão a moeda nacional.

§ 1º As operações de que tratam as alíneas “b” e “c” do inciso II do caput devem
ser precedidas da correspondente compra da moeda estrangeira por banco
autorizado a operar no mercado de câmbio.

§ 2º A revogação, o cancelamento ou a cassação de autorização para operar no
mercado de câmbio implica o encerramento da conta em moeda estrangeira,
devendo o titular da conta vender a instituição autorizada a operar no mercado de
câmbio o saldo existente, no prazo estabelecido pelo Banco Central do Brasil.

Art. 76. As empresas detentoras de direitos de exploração e produção de petróleo
e gás natural podem ser titulares de conta de depósito em moeda estrangeira
destinada exclusivamente ao depósito de fundos de provisionamento em garantia
a despesas com o descomissionamento de instalações de produção em campos de
petróleo
e
gás
natural,
conforme
regulamentação
sobre
fundos
de
provisionamento editada pela ANP, devendo ser observado que:

[Página 66]

I - as movimentações são limitadas ao depósito dos fundos de provisionamento de
que trata o caput e aos créditos e débitos decorrentes da sua aplicação, conforme
previsto em regulamentação editada pela ANP, observado que outras
movimentações dependem de anuência prévia da ANP;

II - é permitida a conversão para reais dos valores nela mantidos, mediante
contratação de operação de câmbio, na forma da regulamentação em vigor;
III - é dispensada a contratação de operação de câmbio para a transferência de
recursos em moeda estrangeira;

IV - deve ser providenciado o seu encerramento e promovida a conversão para reais
ou a transferência do saldo porventura existente em até cinco dias úteis após o
banco mantenedor receber notificação da ANP.

TÍTULO VIII-A
PRESTAÇÃO DE SERVIÇOS DE ATIVOS VIRTUAIS NO MERCADO DE CÂMBIO
CAPÍTULO ÚNICO
(Incluído pela Resolução BCB 521, de 10/11/2025)

Art. 76-A. Está incluída no mercado de câmbio a prestação de serviços de ativos
virtuais que compreenda as seguintes atividades ou operações:

I - pagamento ou transferência internacional com ativos virtuais;

II - transferência de ativo virtual de ou para cliente de prestador de serviços de
ativos virtuais para cumprimento de obrigação decorrente do uso internacional de
cartão ou de outro meio de pagamento eletrônico;

III - transferência de ativo virtual de ou para carteira autocustodiada que não
envolva pagamento ou transferência internacional com ativos virtuais; e

IV - compra, venda ou troca de ativos virtuais referenciados em moeda fiduciária.

§ 1º Para efeitos desta Resolução:

I - as referências à compra ou à venda de ativo virtual significam que a prestadora
de serviços de ativos virtuais é a compradora ou a vendedora, respectivamente; e

II - carteira autocustodiada é aquela cujo proprietário detém o controle da
respectiva chave privada, sendo capaz de movimentá-la sem necessidade de
participação de prestadora de serviços de ativos virtuais;

[Página 67]

§ 2º É vedada a compra ou venda de ativos virtuais com pagamento ou recebimento
em moeda estrangeira, inclusive no caso de compra ou venda efetuada em livro de
negociação.

§ 3º É vedada a movimentação de recursos de interesse de terceiro mediante
prestação de serviços de ativos virtuais incluída no mercado de câmbio, exceto
quando a prestadora de serviços de ativos virtuais prestar serviço a instituição
autorizada a operar no mercado de câmbio que atue no interesse de seus clientes.
§ 4º A prestadora de serviços de ativos virtuais deve ser capaz de comprovar que,
para a realização do negócio, o cliente teve ciência das condições negociadas e das
responsabilidades das partes.

§ 5º A prestadora de serviços de ativos virtuais deve identificar o proprietário de
carteira autocustodiada, implementar e ter documentados os processos para
verificar a origem e o destino dos ativos virtuais nas operações de que trata o caput.

§ 6º As atividades ou operações mencionadas neste artigo, quando efetuadas com
o propósito de investimento, com fluxos e estoques relacionados a capital
estrangeiro no país e a capital brasileiro no exterior, deverão submeter-se às
respectivas regulamentações desses capitais.

Art. 76-B. Para fins desta Resolução, o pagamento ou transferência internacional
com ativos virtuais é:

I - o pagamento ou a transferência cuja liquidação ocorra mediante a alteração de
titularidade de ativos virtuais entre residente e não residente, ou entre não
residentes; ou

II - o recebimento ou o envio, do ou para o exterior, de ativo virtual de titularidade
de mesma pessoa natural ou jurídica.

§ 1º O disposto no caput não inclui a alteração da titularidade de ativo virtual
decorrente de troca de ativo virtual em livro de negociação com acesso oferecido
ao cliente pela própria prestadora de serviços de ativos virtuais.

§ 2º No caso de operação que envolva prestadora de serviços de ativos virtuais no
exterior, a prestadora de serviços de ativos virtuais deve verificar se a referida
entidade no exterior está sob efetiva supervisão prudencial e de conduta ou se é
integrante de grupo financeiro sujeito a efetiva supervisão consolidada, observado
que, se a jurisdição onde referida entidade está sediada no exterior não estabelece
tais requerimentos, a prestadora de serviços de ativos virtuais deve ter
documentada avaliação sobre os riscos de realização de negócios com referida
entidade.

[Página 68]

Art. 76-C. Para a realização das operações de que trata o art. 76-B, a prestadora
de serviços de ativos virtuais deve:

I - obter do cliente a informação sobre a finalidade do pagamento ou transferência,
apresentando ou tornando disponível, para esse fim, em livre formato que permita
o claro entendimento pelo cliente, os códigos constantes dos Anexos III ou IV,
considerando o equivalente a US$50.000,00 (cinquenta mil dólares dos Estados
Unidos) como limite por pagamento ou transferência para uso do Anexo III;
II - prestar orientação e suporte técnico para o cliente que necessite de apoio para
a correta classificação da finalidade do pagamento ou da transferência;

III - obter do cliente as informações constantes do Anexo VI sobre o pagador ou
recebedor no exterior e sua relação de vínculo com o cliente;

IV - ajustar, a pedido do cliente, informação por ele já prestada relativa ao
pagamento ou transferência.

(Artigos 76-A, B e C, e seus dispositivos incluídos pela Resolução BCB 521, de
10/11/2025).

TÍTULO IX
PRESTAÇÃO E DIVULGAÇÃO DE INFORMAÇÕES
CAPÍTULO ÚNICO

Art. 77. A instituição autorizada a operar no mercado de câmbio deve enviar para
o Banco Central do Brasil as informações sobre as operações no mercado de
câmbio no prazo, na forma e nas condições estabelecidas nesta Resolução.

Art. 78. O envio das informações relativas às operações do mercado de câmbio
deve ser realizado entre 7h e:

I - 19h para o registro dos eventos do mercado primário;

II - 17h para o registro de eventos do mercado interbancário, exceto os de
arbitragens;

III - 19h para o registro da contratação de arbitragens no mercado interbancário.

§ 1º As operações negociadas após os horários constantes dos incisos do caput
devem ser registradas com data do evento do movimento subsequente.

§ 2º O Banco Central do Brasil poderá ampliar os horários constantes do caput em
situação de excepcionalidade e mediante comunicação às instituições autorizadas
a operar no mercado de câmbio.

[Página 69]

§ 3º A prestação de informações ao Banco Central do Brasil sobre operação de
câmbio de até US$50.000,00 (cinquenta mil dólares dos Estados Unidos), ou seu
equivalente em outras moedas, que não necessite ser vinculada a operação de
capital estrangeiro informada em sistema do Banco Central do Brasil pode ser
realizada até o dia cinco do mês subsequente, observado que tal prestação de
informações pode ser realizada por meio de arquivo no caso de operação de câmbio
para liquidação pronta com apenas um pagador ou recebedor no exterior e não
sujeita à interveniência de corretora ou distribuidora autorizada a funcionar pelo
Banco Central do Brasil.

§ 4º A opção de liquidação automática pode ser utilizada para operação de compra
ou de venda de moeda estrangeira com cliente, contratada para liquidação pronta,
para qualquer finalidade que não necessite ser vinculada a operação de capital
estrangeiro informada em sistema do Banco Central do Brasil, e com apenas um
pagador ou recebedor no exterior.

§ 5º A anulação de registro no Sistema Câmbio de eventos da operação de câmbio
é permitida apenas em situações excepcionais para a correção de erros ou
eliminação de duplicidade, devendo observar requerimentos adicionais do Banco
Central do Brasil.

§ 6º O registro de operação de câmbio fora do prazo regulamentar só é admitido
para a situação de que trata o § 5º, ressalvadas as soluções de contingência do
Sistema Câmbio ou as situações decorrentes de fatores alheios à vontade das
instituições autorizadas a operar no mercado de câmbio.

Art. 79. As informações constantes do Anexo I a esta Resolução e eventuais
alterações relativas às operações de câmbio devem ser prestadas ao Banco Central
do Brasil pela instituição autorizada a operar no mercado de câmbio, por meio do
Sistema Câmbio, no prazo, na forma e nas condições estabelecidas nesta
Resolução.

§ 1º O Banco Central do Brasil pode adicionalmente requisitar informações
complementares a serem enviadas pelas instituições autorizadas a operar no
mercado de câmbio.

§ 2º As informações referentes às operações constantes do Sistema Câmbio devem
ser compatíveis com os saldos das contas que compõem a posição de câmbio da
instituição autorizada a operar no mercado de câmbio.

§ 3º A instituição autorizada a operar no mercado de câmbio que contrate
correspondente no País deve registrar informações relativas a seu contratado no
Sistema de Informações sobre Entidades de Interesse do Banco Central (Unicad)

[Página 70]

previamente à realização dos negócios e divulgá-las em formato de dados abertos,
na forma e nas condições estabelecidas pelo Banco Central do Brasil.

Art. 80. Instituições mantenedoras de contas de não residentes devem prestar
informações em relação às movimentações discriminadas no Anexo II até o dia
cinco do mês subsequente ao mês da movimentação, por meio de mensagem ou
de arquivo.

§ 1º (Revogado pela Resolução BCB 337, de 22/08/2023).

§ 2º (Revogado pela Resolução BCB 337, de 22/08/2023).

Parágrafo único. O prazo de que trata o caput não se aplica à movimentação que
necessite ser informada em sistema de prestação de informações de capital
estrangeiro do Banco Central do Brasil, situação em que as informações devem ser
enviadas por meio de mensagem até o segundo dia útil após o cliente informar a
finalidade da movimentação (Incluído pela Resolução BCB 337, de 22/08/2023).

Art. 81. As instituições abaixo indicadas devem prestar adicionalmente as
seguintes informações ao Banco Central do Brasil por meio do Sistema Câmbio, na
forma por ele estabelecida:

I - instituições autorizadas a operar no mercado de câmbio: informações referentes
às transferências unilaterais tratadas no art. 26, até o dia dez do mês subsequente;

II - instituições financeiras e demais instituições autorizadas a funcionar pelo Banco
Central do Brasil: informações relativas aos pagamentos e transferências
referentes ao eFX, tratado no Título V, observado que:

a) informações relativas a aquisições de bens e serviços efetuadas com cartão de
uso internacional devem ser prestadas até o dia dez do mês subsequente;

b) informações relativas a demais pagamentos e transferências devem ser
prestadas no prazo de dois dias úteis a partir da solicitação do Banco Central do
Brasil.

Parágrafo único. O Banco Central do Brasil estabelecerá a forma para o envio de
informações relativas ao serviço de transferência postal internacional.

Art. 82. O prestador de eFX cujo cartão de uso internacional de sua emissão
permita a realização de saque no exterior ou a aquisição de bens e serviços do
exterior deve, até as 10h, horário de Brasília:

[Página 71]

I - tornar disponível em todos os seus canais de atendimento ao cliente a taxa de
conversão do dólar dos Estados Unidos para reais utilizada no dia anterior na
conversão dos valores das operações em moeda estrangeira de seus clientes; e

II - publicar, na forma e condições estabelecidas pelo Banco Central do Brasil,
inclusive no formato de dados abertos, informações sobre o histórico das taxas de
conversão de que trata o inciso I.

Art. 82-A. As instituições autorizadas a operar no mercado de câmbio devem enviar
as informações constantes do Anexo II-A a respeito de suas operações de prestação
de serviços de ativos virtuais previstas nesta Resolução realizadas a partir de 3 de
novembro de 2026, até o dia cinco do mês subsequente à operação, na forma
definida pelo Banco Central do Brasil (Nova redação conferida pela Resolução BCB
574, de 18/06/2026).

Parágrafo único. O disposto no caput também se aplica às sociedades prestadoras
de serviços de ativos virtuais de que trata o art. 29, § 5º (Artigo e parágrafo
incluídos pela Resolução BCB 521, de 10/11/2025).

TÍTULO X
DISPOSIÇÕES FINAIS

Art. 83. As agências de turismo ainda detentoras de autorização para comprar e
vender moeda estrangeira em espécie, cheques e cheques de viagem referentes a
viagens internacionais cujos controladores finais apresentaram pedido ao Banco
Central do Brasil para constituição e funcionamento de instituição do Sistema
Financeiro Nacional passível de operar no mercado de câmbio, devem observar
que, se o pedido for:

I - deferido, a autorização concedida à agência de turismo perde a validade na data
de início das atividades da nova instituição autorizada, respeitado o prazo previsto
no plano de negócios; e

II - indeferido ou arquivado, a autorização concedida à agência de turismo perde a
validade trinta dias após a decisão do Banco Central do Brasil.

Parágrafo único. As agências de turismo de que trata o caput:

I - podem comprar moeda estrangeira de instituição integrante do Sistema
Financeiro Nacional autorizada a operar no mercado de câmbio para suprimento
de recursos;

II - não podem conduzir operações de câmbio por meio de posto de atendimento e
a contratação de correspondentes para o curso de operações de câmbio;

[Página 72]

III - não têm posição de câmbio, mas devem observar o limite operacional diário de
US$200.000,00 (duzentos mil dólares dos Estados Unidos), que representa o total
em moeda estrangeira mantido pela agência de turismo em caixa e na conta em
moeda estrangeira de que trata o inciso I do art. 70, sendo que eventual excesso
sobre o referido limite deve ser obrigatoriamente vendido a instituição integrante
do Sistema Financeiro Nacional autorizada a operar no mercado de câmbio,
observado que, configurada contumácia, a ocorrência de excesso sobre o limite
operacional pode implicar revogação da autorização;

IV - devem enviar as informações referentes às suas operações para o Banco
Central do Brasil na forma e no prazo por ele definidos.

Art. 84. As instituições autorizadas a operar no mercado de câmbio devem
observar as condições de legítimos credores ou devedores para curso das
operações cambiais.

Art. 85. Para a realização das operações de que trata esta resolução, as instituições
autorizadas a operar no mercado de câmbio devem observar o disposto na Circular
nº 3.978, de 2020.

ANEXO I
(Com redação dada pela Resolução BCB 337, de 22/08/2023)

INFORMAÇÕES MÍNIMAS QUE FAZEM PARTE DA OPERAÇÃO DE CÂMBIO

I - identificação da instituição autorizada a operar no mercado de câmbio e, se
houver, da instituição intermediadora, devendo ser informados para o cliente os
nomes e os números de inscrição no Cadastro Nacional da Pessoa Jurídica (CNPJ)
das instituições;

II - identificação do cliente, observada a Circular nº 3.978, de 23 de janeiro de 2020;
III - número da operação de câmbio no Sistema Câmbio;

IV - data do evento e se o evento se refere a contratação, a alteração ou a
cancelamento;

V - informação sobre se a operação de câmbio é de compra ou de venda de moeda
estrangeira;

VI - moeda estrangeira;

[Página 73]

VII - valor em moeda estrangeira;

VIII - taxa de câmbio;

IX - valor em reais;

X - Valor Efetivo Total (VET), quando exigido;

XI - forma de entrega da moeda estrangeira;

XII - data prevista para liquidação;

XIII - finalidade da operação;

XIV - pagador ou recebedor no exterior, quando exigido;

XV - nome e país do pagador ou do recebedor no exterior, se houver;

XVI - relação de vínculo entre o cliente e o pagador ou o recebedor no exterior,
quando exigido;

XVII - percentual de adiantamento sobre a operação de câmbio, se houver;

XVIII - número do código de capitais estrangeiros, se houver;

XIX - instruções de recebimento ou de pagamento, se houver;

XX - outras informações que o Banco Central do Brasil requisitar.

ANEXO II
(Com redação dada pela Resolução BCB 337, de 22/08/2023)

INFORMAÇÕES A SEREM ENVIADAS AO BANCO CENTRAL DO BRASIL EM
RELAÇÃO A MOVIMENTAÇÕES EM CONTAS EM REAIS TITULADAS POR NÃO
RESIDENTES

(1) Movimentação relativa a ordem de pagamento recebida do exterior ou enviada
para o exterior de interesse de terceiro:

I - valor e data da movimentação;
II - identificação do titular da conta;
III - dados sobre o remetente e o destinatário final.

[Página 74]

(2) Movimentação relativa a ordem de pagamento recebida do exterior ou enviada
para o exterior de interesse de terceiro quando o destinatário final ou o remetente
for residente, além das informações estabelecidas em (1):

I - finalidade da movimentação, conforme os Anexos IV ou V, se a movimentação
tiver valor igual ou superior a R$1.000.000,00 (um milhão de reais); ou

II - número do código de capitais estrangeiros e finalidade da movimentação,
conforme os Anexos III, IV ou V, se a movimentação, independentemente de seu
valor, necessitar ser informada em sistema de prestação de informações de capital
estrangeiro do Banco Central do Brasil.

(3) Valor total mensal dos créditos e valor total mensal dos débitos de
movimentações próprias iguais ou superiores a R$10.000,00 (dez mil reais) de
conta titulada por embaixada, repartição consular ou organismo internacional
reconhecido pelo Governo brasileiro.

ANEXO II-A
(Incluído pela Resolução BCB 521, de 10/11/2025)

INFORMAÇÕES A SEREM ENVIADAS AO BANCO CENTRAL DO BRASIL EM
RELAÇÃO ÀS OPERAÇÕES DE PRESTAÇÃO DE SERVIÇOS DE ATIVOS VIRTUAIS
PREVISTAS NESTA RESOLUÇÃO.

(1) Pagamento ou transferência internacional com ativos virtuais:

I - data da operação;
II - finalidade da operação;
III - informação sobre se a operação de ingresso ou remessa de ativo virtual;
IV - identificação do cliente, observada a Circular nº 3.978, de 23 de janeiro de
2020;
V - denominação do ativo virtual;
VI - quantidade do ativo virtual transferido;
VII - valor de referência em reais da unidade do ativo virtual na data da operação;
VIII - pagador ou recebedor no exterior;
IX - nome e país do pagador ou do recebedor no exterior;
X - relação de vínculo entre o cliente e o pagador ou o recebedor no exterior.

(2) Transferência de ativo virtual entre o cliente de prestador de serviços de ativos
virtuais e o emissor de cartão ou de outro meio de pagamento eletrônico de uso
internacional:

I - data da operação;

[Página 75]

II - informação sobre se o emissor é o remetente ou o destinatário do ativo virtual;
III - identificação do cliente, observada a Circular nº 3.978, de 23 de janeiro de
2020;
IV - denominação do ativo virtual;
V - quantidade do ativo virtual transferido;
VI - valor de referência em reais da unidade do ativo virtual na data da operação;
VII - pagador ou recebedor no exterior;
VIII - nome e país do pagador ou do recebedor no exterior.

(3) Transferência de ativo virtual de ou para carteira autocustodiada que não
envolva pagamento ou transferência internacional com ativos virtuais:

I - data da operação;
II - identificação do cliente, observada a Circular nº 3.978, de 23 de janeiro de 2020;
III - denominação do ativo virtual;
IV - quantidade do ativo virtual transferido;
V - valor de referência em reais da unidade do ativo virtual na data da operação;
VI - identificação do proprietário da carteira autocustodiada;
VII -informação sobre se a carteira autocustodiada é origem ou destino.

(4) Total mensal de compras, vendas e trocas de ativos virtuais referenciados em
moeda fiduciária:
I - mês de referência;
II - identificação do cliente, observada a Circular nº 3.978, de 23 de janeiro de 2020;
III - ativo virtual referenciado em moeda fiduciária:
a. denominação;
b. quantidade mensal obtida pelo cliente (resultante de vendas da PSAV e de
trocas);
c. quantidade mensal entregue pelo cliente (resultante de compras da PSAV e de
trocas).

Observação importante: Os demais anexos, que tratam dos códigos de
classificação da operação, não constam deste Material de Apoio e não serão
objeto de questões nas provas de Certificação.$mat$, 'junho/2026'),
(1, 3, $mat$Resoluções BCB 278, 279 e 280/2022: capitais estrangeiros, capitais brasileiros no exterior, residência (cap. 6, parte 2)$mat$, $mat$Resolução BCB nº 278, de 31 de dezembro de 2022
Regulamenta a Lei nº 14.286, de 29 de dezembro de 2021, em relação ao capital
estrangeiro no País, nas operações de crédito externo e de investimento
estrangeiro direto, bem como a prestação de informações ao Banco Central do
Brasil.
CAPÍTULO I

[Página 76]

DISPOSIÇÕES GERAIS
Art. 1º  Esta Resolução regulamenta a Lei nº 14.286, de 29 de dezembro de 2021,
em relação aos fluxos, estoques e prestação de informações de capitais
estrangeiros no País em operações de:
I - crédito externo; e
II - investimento estrangeiro direto.

Parágrafo único.  As operações de crédito externo e investimento estrangeiro
direto em ativos virtuais devem seguir o disposto nesta Resolução (Incluído pela
Resolução BCB 521, de 10/11/2025).

Art. 2º  Para fins do disposto nesta Resolução entende-se por:
I - crédito externo: compromisso financeiro, mesmo no caso em que os recursos
não ingressem no País, assumido por residente que tenha como credor um não
residente em razão de:
a) empréstimo direto;
b) emissão de título no mercado internacional;
c) emissão de títulos de colocação privada no mercado interno;
d) financiamento;
e) importação financiada de bens ou serviços;
f) recebimento antecipado de exportação, entendido como a captação de recursos
externos em adiantamento a futuras exportações de bens ou serviços que serão
realizadas em pagamento à dívida contraída (Redação dada pela Resolução BCB
492, de 14/08/2025);
g) arrendamento mercantil financeiro externo, entendido como a operação em que
não residente proprietário legal de ativo (arrendador) transmite substancialmente
todos os riscos e as vantagens da propriedade do ativo para residente
(arrendatário) mediante pagamento de prestações (Redação dada pela Resolução
BCB 492, de 14/08/2025); ou
h) emissão de título sustentável no mercado internacional (Alínea incluída pela
Resolução BCB 492, de 14/08/2025).
II - operação de repasse do exterior: contrato vinculado a captação de recursos no
exterior, por meio do qual instituição financeira nacional concede crédito a
residente mediante a transferência de idênticas condições de custo da dívida
contratada (principal, juros e encargos acessórios), incluindo a tributação
aplicável;

[Página 77]

III - operação de repasse interfinanceiro do exterior: operação de repasse do
exterior cujo devedor no País é outra instituição financeira ou sociedade de
arrendamento mercantil;
IV - cessão de crédito: transferência de direito creditório, externo ou interno, entre
credores residentes e não residentes, ou entre credores não residentes  (Redação
dada pela Resolução BCB 348, de 17/10/2023);
V - investimento estrangeiro direto: participação direta de não residente no capital
social de sociedade no País, ou outro direito econômico de não residente no País
derivado de ato ou contrato sempre que o retorno desse investimento dependa dos
resultados do negócio (Redação dada pela Resolução BCB 348, de 17/10/2023);
VI - Sistema de Prestação de Informações de Capital Estrangeiro de Crédito Externo
(SCE-Crédito): sistema informatizado disponibilizado pelo Banco Central do Brasil
para prestação de informações de operação de crédito externo (Redação dada pela
Resolução BCB 348, de 17/10/2023);
VII - Sistema de Prestação de Informações de Capital Estrangeiro de Investimento
Estrangeiro Direto (SCE-IED): sistema informatizado disponibilizado pelo Banco
Central do Brasil para prestação de informações de operação de investimento
estrangeiro direto (Redação dada pela Resolução BCB 348, de 17/10/2023);
VIII - código SCE-Crédito: identificador da operação de crédito externo gerado
automaticamente pelo SCE-Crédito após informação da caracterização da
operação (Redação dada pela Resolução BCB 348, de 17/10/2023);
IX - código SCE-IED: identificador único do par receptor-investidor não residente
gerado automaticamente pelo SCE-IED após identificação do receptor e do
investidor não residente (Redação dada pela Resolução BCB 348, de 17/10/2023);
X - Cadastro Declaratório de Não Residente (CDNR): sistema disponibilizado pelo
Banco Central do Brasil em que são declaradas informações cadastrais do não
residente, sendo gerado número CDNR, que é pré-requisito para prestação de
informações de operações de crédito externo;
XI - receptor: qualquer entidade constituída ou organizada no País conforme a
legislação brasileira aplicável, com ou sem fins lucrativos, com ou sem
personalidade jurídica, incluindo qualquer corporação, sociedade, parceria,
empresário individual, consórcio e sociedade em conta de participação;
XII - conferência internacional de quotas ou ações: integralização de capital de
sociedade brasileira efetuada por não residente mediante dação ou permuta de
participação societária detida em sociedade estrangeira, sediada no exterior, ou
integralização de capital de sociedade estrangeira, sediada no exterior, realizada

[Página 78]

mediante dação ou permuta, por residente, de participação societária detida em
sociedade brasileira;
XIII - (Revogado pela Resolução BCB 410, de 11/09/2024).
XIV - (Revogado pela Resolução BCB 410, de 11/09/2024).
XV - reorganização societária: fusão, incorporação ou cisão de sociedades no País,
na qual pelo menos uma delas seja receptora de investimento estrangeiro direto
(Redação dada pela Resolução BCB 348, de 17/10/2023);
XVI - reinvestimento: capitalização de lucros, de dividendos, de juros sobre o
capital próprio ou de reservas de lucros no receptor em que foram produzidos
(Redação dada pela Resolução BCB 348, de 17/10/2023);
XVII - conversão: operação pela qual direitos e créditos passíveis de gerar
transferências financeiras para o exterior, assim como bens pertencentes a não
residentes, convertem-se em investimento estrangeiro direto ou crédito externo
nos termos desta Resolução (Redação dada pela Resolução BCB 410, de
11/09/2024);
XVIII - (Revogado pela Resolução BCB 410, de 11/09/2024).
XIX - alienação a residente: transferência de participação societária em sociedade
brasileira de investidor não residente para investidor residente;
XX - aquisição de residente: transferência de participação societária em sociedade
brasileira de investidor residente para investidor não residente;
XXI - inativação do código SCE-IED: fim do vínculo do par receptor-investidor por
extinção do investimento;
XXII - encerramento de receptora: liquidação, cisão total, fusão ou incorporação
da sociedade brasileira receptora do investimento (Incisos XIX a XXII inseridos pela
Resolução BCB 410, de 11/09/2024).
Parágrafo único.  Os títulos sustentáveis emitidos no mercado internacional podem
ser:
I - Títulos Verdes: títulos de dívida em que o uso dos recursos captados é restrito
ao financiamento ou refinanciamento de atividades ou projetos que gerem
benefícios ao meio ambiente;

[Página 79]

II - Títulos Sociais: títulos de dívida em que o uso dos recursos captados é restrito
ao financiamento ou refinanciamento de atividades ou projetos que gerem
benefícios sociais;
III - Títulos de Sustentabilidade: títulos de dívida em que o uso dos recursos
captados é restrito ao financiamento ou refinanciamento de atividades ou projetos
que gerem benefícios sociais e ao meio ambiente; ou
IV - Títulos Vinculados a Metas de Sustentabilidade: títulos de dívida em que os
recursos captados têm destinação livre, mas o emissor se compromete a atingir
objetivos pré-definidos de sustentabilidade – que melhorem as condições do meio
ambiente, da sociedade ou de ambos (Parágrafo e incisos incluídos pela Resolução
BCB 492, de 14/08/2025).

CAPÍTULO II
FLUXOS E ESTOQUES DO CAPITAL ESTRANGEIRO
Seção I
Disposições Gerais
Art. 3º  Os fluxos e estoques de capital estrangeiro devem seguir a forma e as
condições estabelecidas neste Capítulo além do disposto na regulamentação do
mercado de câmbio.

§ 1º  Para fins desta Resolução, as operações de crédito externo incluem as
operações de crédito realizadas em ativos virtuais referenciados em moeda
fiduciária.
§ 2º  As operações de investimento estrangeiro direto incluem as integralizações
em ativos virtuais (Parágrafos incluídos pela Resolução BCB 521, de 10/11/2025).

Art. 4º  Nas operações de crédito externo e de investimento estrangeiro direto de
que trata esta Resolução devem ser observadas sua legalidade, sua
fundamentação econômica e a compatibilidade com as condições usualmente
observadas nos mercados internacionais.

Parágrafo único.  A documentação comprobatória das operações deve ser mantida
pelo prazo de 10 (dez) anos, contados a partir da conclusão da operação, no caso
de crédito externo, ou do término da participação no capital social do receptor, no
caso de investimento estrangeiro direto, podendo o Banco Central do Brasil,
durante esse período, solicitá-la ao devedor da operação de crédito externo ou ao
receptor, sempre que considerar necessário.

Seção II
Operações de Crédito Externo
Art. 5º  É livre a contratação e a renegociação de operações de crédito externo em
qualquer moeda.

[Página 80]

Art. 6º  Os custos e as demais condições das operações de crédito externo devem
manter compatibilidade com aqueles usualmente observados nos mercados
internacionais e estar claramente definidos nos contratos das operações.

Art. 7º  As transferências financeiras e as movimentações para o exterior
decorrentes das operações de crédito externo são limitadas ao montante
necessário para liquidar o principal da dívida, juros e encargos.

Art. 8º  É facultada a liquidação antecipada de obrigações, inclusive de encargos
acessórios, bem como o pagamento de juros antecipados relativos às operações de
crédito externo.
Art. 9º  O pagamento por corresponsável ou terceiro de valores devidos em
operação de crédito externo deve observar a legalidade dessa prerrogativa.
Art. 10.  A captação de recursos no exterior, tanto para livre aplicação no mercado
doméstico quanto para realização de operações de repasse interfinanceiro do
exterior, pode ser realizada por instituições financeiras e sociedades de
arrendamento mercantil, observadas as regulamentações pertinentes a tais
entidades.

Art. 11.  A captação de recursos no exterior para realização de operações de
repasse do exterior apenas pode ser realizada por instituições financeiras.

§ 1º  Na operação de repasse do exterior, a instituição financeira deve repassar ao
tomador final dos recursos os efeitos decorrentes da variação cambial da dívida
originalmente contraída no exterior.
§ 2º  Na operação de repasse do exterior, é vedada a cobrança de qualquer ônus,
exceto comissão pelo serviço de intermediação financeira.
§ 3º  O ingresso de recursos no País para as operações de repasse do exterior
também pode ocorrer a partir de conta no exterior especialmente designada para
a operação de captação de recursos realizada com bancos multilaterais de
desenvolvimento e agências internacionais de desenvolvimento, titulada pela
instituição financeira nacional.

Art. 12.  A operação de recebimento antecipado de exportação pode referir-se a
exportação do devedor da operação, de sua controladora, de suas controladas ou
de sociedade que seja controlada por sua controladora.

§ 1º  A antecipação de recursos a exportadores brasileiros pode ser efetuada:
I - pelo importador;
II - por pessoa jurídica não financeira no exterior; ou

[Página 81]

III - por instituição financeira no exterior.
§ 2º  A amortização das operações de recebimento antecipado de exportação deve
ser efetuada mediante o embarque das mercadorias ou a prestação de serviços,
podendo os juros serem pagos por meio de transferências financeiras ou de
exportações.

Art. 13.  Na hipótese de não ocorrer o embarque das mercadorias ou a prestação
de serviços na situação de que trata o art. 12, faculta-se o retorno, ao exterior, dos
recursos que ingressaram no País na forma desta Seção, inclusive pelo garantidor
da operação, ou a conversão em investimento estrangeiro direto ou empréstimo
direto.

Art. 14.  A operação de arrendamento mercantil financeiro externo deve ter:

I - prazo total limitado à vida útil do bem;
II - contraprestações compatíveis com as condições praticadas no mercado
internacional para o prazo e tipo de bem arrendado;
III - prestações contratuais, parcelas fixas, distribuídas no tempo de tal forma que,
em qualquer momento da vigência do contrato, a proporção entre o valor total já
transferido ao exterior e o valor do arrendamento não seja superior à proporção
existente entre o prazo já decorrido e o prazo total da operação; e
IV - contrato com cláusula de opção de compra ou de renovação do prazo de
vigência do contrato.
Parágrafo único.  Quando se tratar de contrato de arrendamento mercantil
financeiro externo entre arrendadora-compradora domiciliada no exterior e
arrendatária-vendedora domiciliada no País (sale-leaseback), o valor do contrato
deve ser inferior a 90% (noventa por cento) do custo do bem objeto do
arrendamento mercantil, cuja aquisição deve ocorrer mediante pagamento à vista.

Seção III
Operações de Investimento Estrangeiro Direto

Art. 15.  É livre a realização de operações de investimento estrangeiro direto no
País, bem como suas transferências financeiras e as movimentações associadas,
observadas as disposições de legislação específica e a fundamentação econômica
da operação.
CAPÍTULO III
DA PRESTAÇÃO DE INFORMAÇÕES DO CAPITAL ESTRANGEIRO
Seção I
Disposições Gerais

[Página 82]

Art. 16.  Devem ser prestadas ao Banco Central do Brasil informações relativas a
operações de crédito externo e de investimento estrangeiro direto nos termos
desta Resolução.

§ 1º  Nas operações de crédito externo em ativos virtuais referenciados em moeda
fiduciária, deve ser informado o valor na moeda fiduciária de referência para fins
de prestação de informações no SCE-Crédito.
§ 2º  Nas operações de investimento estrangeiro direto com ativos virtuais, deve
ser informado o valor em moeda fiduciária para fins de prestação de informações
no SCE-IED (Parágrafos incluídos pela Resolução BCB 521, de 10/11/2025).

Art. 17.  É responsável pela prestação de informações:

I - o devedor, no caso das operações de crédito externo; ou
II - o receptor, no caso de operações de investimento estrangeiro direto (Redação
dada pela Resolução BCB 348, de 17/10/2023).

Art. 18.  O responsável pela prestação de informações deve:

I - manter à disposição do Banco Central do Brasil a documentação comprobatória
das informações prestadas atualizada e em ordem, até o termo final do prazo de
10 (dez) anos, contado a partir:
a) do encerramento das obrigações da operação, no caso de crédito externo; ou
b) da liquidação do investimento estrangeiro direto de cada investidor no receptor,
no caso de investimento estrangeiro direto.
II - providenciar a correção de informações declaradas que estejam incorretas,
desatualizadas ou incompletas;
III - providenciar a correção de informações quando solicitada pelo Banco Central
do Brasil.
§ 1º  O responsável pela prestação de informações tem responsabilidade pela
fundamentação econômica e pela legalidade da operação, assim como pela
veracidade das declarações prestadas.
§ 2º  O responsável pela prestação de informações ou o responsável legal deve
registrar a inativação do código SCE-IED e o encerramento da receptora nas
situações cabíveis (Parágrafo adicionado pela Resolução BCB 410, de 11/09/2024).
Art. 19.  O responsável pela prestação de informações está sujeito às penalidades
estabelecidas na legislação e na regulamentação específica.

Art. 20.  O devedor e o receptor podem constituir mandatário para incluir,
consultar e atualizar as informações prestadas ao Banco Central do Brasil.

[Página 83]

§ 1º  As instituições financeiras e demais instituições autorizadas a funcionar pelo
Banco Central do Brasil podem incluir e alterar mandatários desde que autorizadas
pelo devedor ou pelo receptor.
§ 2º  A documentação comprobatória das autorizações de que trata este artigo
deve ser mantida à disposição do Banco Central do Brasil pelo mesmo prazo de
guarda da documentação da operação de capital estrangeiro à qual a autorização
se refere, conforme estabelecido no art. 18.
§ 3º  A autorização referida neste artigo poderá ser obtida por qualquer meio
acordado entre as partes, com a devida segurança jurídica e clara manifestação de
consentimento do prestador de informações na constituição do mandatário.

Art. 21.  Nas transferências financeiras das operações de crédito externo ou de
investimento estrangeiro direto sujeitas à prestação de informações, conforme
critério de exigibilidade desta norma, deve constar nas informações da operação
de câmbio ou da movimentação de recursos de interesse de terceiro em conta de
não residente em reais:

I - o código SCE-Crédito em todas as transferências financeiras; ou
II - o código SCE-IED nas transferências financeiras de valor igual ou superior a
US$100.000,00 (cem mil dólares dos Estados Unidos da América) ou seu
equivalente em outras moedas (Redações do artigo e incisos dadas pela Resolução
BCB 348, de 17/10/2023).
Art. 22.  A inobservância das disposições relativas à prestação de informações de
operação de capitais estrangeiros no País pode implicar a vedação à realização de
transferências financeiras relacionadas à operação, enquanto não forem sanadas
as irregularidades, sem prejuízo da aplicação de penalidades nos termos da
legislação.

Seção II
Das Operações de Crédito Externo
Art. 23.  A prestação de informações deve ser realizada pelo responsável tanto nos
casos de ingresso de recursos no País quanto nos casos em que estes sejam
mantidos no exterior, nas seguintes situações:
I - empréstimo direto e financiamento, inclusive de organismos internacionais,
emissão de títulos no mercado internacional, com identificação dos títulos
sustentáveis, e emissão de títulos de colocação privada no mercado interno,
sempre que o valor da operação de crédito externo for igual ou superior a
US$1.000.000,00 (um milhão de dólares dos Estados Unidos da América) ou seu
equivalente em outras moedas (Redação dada pela Resolução BCB 492, de
14/08/2025);

[Página 84]

II - importação financiada de bens ou serviços com prazo de pagamento superior a
180 (cento e oitenta) dias, sempre que o valor da operação de crédito externo for
igual ou superior a US$500.000,00 (quinhentos mil dólares dos Estados Unidos da
América) ou seu equivalente em outras moedas; e
III - recebimento antecipado de exportação e arrendamento mercantil financeiro
externo, com prazo de pagamento superior a 360 (trezentos e sessenta) dias,
sempre que o valor da operação de crédito externo for igual ou superior a
US$1.000.000,00 (um milhão de dólares dos Estados Unidos da América) ou seu
equivalente em outras moedas.
§ 1º  A prestação de informações de operação de crédito externo contratada por
entes da Administração Pública Direta e Indireta federal, estadual, municipal e do
Distrito Federal deve ser realizada independentemente do valor da operação.
§ 2º  Para o cálculo da equivalência em outras moedas dos valores mencionados
neste artigo, deve ser considerada a data de assinatura do contrato ou a data de
emissão dos títulos no exterior, levando em conta a taxa de câmbio do dia útil
anterior divulgada pelo Banco Central do Brasil.

Art. 24.  As informações relativas aos não residentes envolvidos nas operações de
crédito externo devem ser declaradas no CDNR previamente à prestação de
informações.

Art. 25.  Para fins deste Capítulo, deve ser feita nova prestação de informações
sempre que, após a primeira transferência financeira ou movimentação, ocorrer:
I - alteração de data de vencimento;
II - repactuação de condição financeira; ou
III - alteração de devedor, exceto nos casos de reestruturação societária, sucessão
ou ordem judicial.
§ 1º  A nova prestação de informações deve ser efetuada pelo responsável em até
30 (trinta) dias após a ocorrência da alteração.
§ 2º  O disposto no caput não se aplica à alteração de taxa de juros cujo indexador
tenha tido sua divulgação encerrada.

Art. 25-A.  As conversões entre operações de investimento estrangeiro direto e de
crédito externo, e vice-versa, bem como entre operações de crédito externo,
inclusive de juros e encargos em principal, devem ser informadas no SCE-Crédito
em até trinta dias após sua ocorrência (Incluído pela Resolução BCB 348, de
17/10/2023 e alterado pela Resolução BCB 492, de 14/08/2025).

Art. 26.  O registro de operação de crédito externo realizado anteriormente à
vigência desta Resolução deve ser mantido atualizado, nos termos desta

[Página 85]

Resolução, até o término da operação, se enquadrada nas hipóteses previstas no
art. 23.
Parágrafo único.  Estão dispensados de serem atualizados, permanecendo
disponíveis para consulta pelo período de 1 (um) ano após a entrada em vigor desta
Resolução:
I - os registros dos contratos de royalties, de serviços técnicos e assemelhados, de
arrendamento mercantil operacional externo, de aluguel e de afretamento
efetuados anteriormente à vigência desta Resolução; e
II - os registros das operações de crédito externo efetuados anteriormente à
vigência desta Resolução e não enquadrados nas hipóteses previstas no art. 23.

Art. 27.  A prestação de informações de operação de crédito externo é composta
por:

I - caracterização da operação;
II - condições de pagamento (Redação dos incisos I e II, dada pela Resolução BCB
348, de 17/10/2023);
III - cronograma de pagamento; e
IV - detalhamento das transferências financeiras e das movimentações
relacionadas à operação, conforme disposto nos arts. 30 e 31.
Art. 28.  A caracterização da operação e as condições de pagamento devem ser
declaradas no SCE-Crédito:
I - até o ingresso dos recursos no País, quando a operação for contratada com
ingresso; ou
II - em até 30 (trinta) dias após desembolso, entrega da mercadoria ou prestação
de serviço, pelo credor, no exterior ou no País, quando a operação for contratada
sem ingresso de recursos no País (Redações do caput e do inciso II, dadas pela
Resolução BCB 348, de 17/10/2023).

Art. 29.  As informações relativas ao cronograma de pagamento, indispensáveis
para efetivação de remessas, devem ser declaradas pelo responsável em até 30
(trinta) dias, conforme o caso, após:

I - o ingresso de moeda;
II - o desembaraço aduaneiro;
III - a prestação dos serviços ao residente; ou
IV - o desembolso ou a entrega de mercadoria, pelo credor, no exterior ou no País,
em operações sem ingresso de recursos no País  (Redação dada pela Resolução BCB
348, de 17/10/2023).

[Página 86]

Art. 30.  As informações referentes às transferências financeiras, inclusive de
movimentação de recurso de interesse de terceiro em conta de não residente em
reais, das operações de crédito externo sujeitas à prestação de informações são
capturadas automaticamente pelo SCE-Crédito, tendo por base informações
disponíveis no Sistema Câmbio (Redação dada pela Resolução BCB 348, de
17/10/2023).

Parágrafo único.  Os valores ingressados são capturados automaticamente nas
moedas constantes das operações de câmbio e das movimentações de recursos de
interesse de terceiro em conta de não residente em reais, independentemente,
conforme o caso:
I - da moeda em que a operação de crédito foi contratada, que deve ser informada
como moeda de denominação; ou
II - do ativo virtual referenciado em moeda fiduciária em que a operação de crédito
foi contratada, observado o disposto no art. 16, § 1º (Redação dada pela Resolução
BCB 521, de 10/11/2025).

Art. 31.  Nas operações de crédito externo sujeitas à prestação de informações,
devem ser declaradas pelo responsável no SCE-Crédito, em até 30 (trinta) dias após
sua ocorrência, as seguintes movimentações:

I - embarque de mercadorias ao exterior;
II - prestação de serviços a não residente;
III - pagamentos e recebimentos realizados no exterior;
IV - pagamentos e recebimentos em conta de não residente em reais que não sejam
movimentações de interesse de terceiro;
V - baixa ou cancelamento da dívida;
VI - pagamentos realizados ou obrigação incorrida no País;
VII - ingresso de bens e perda de mercadoria parcial ou total;
VIII - cessão de crédito; e
IX - pagamentos e recebimentos cuja liquidação ocorra com ativos virtuais
(Incluído pela Resolução BCB 521, de 10/11/2025).
Parágrafo único.  Devem ser prestadas pelo devedor da operação de crédito
externo informações relativas às cessões de crédito onerosas ou não onerosas
realizadas pelo credor da operação de crédito (Redações do caput, incisos IV e VIII,
e parágrafo único dadas pela Resolução BCB 348, de 17/10/2023).

[Página 87]

Seção III
Das Operações de Investimento Estrangeiro Direto
 (Redação dada pela Resolução BCB 348, de 17/10/2023)
Art. 32.  A prestação de informações de operações de investimento estrangeiro
direto deve ser realizada pelo responsável quando:
I - ocorrer transferência financeira, inclusive movimentação de recurso de interesse
de terceiro em conta de não residente em reais, relacionada a investidor não
residente de valor igual ou superior a US$100.000,00 (cem mil dólares dos Estados
Unidos da América) ou seu equivalente em outras moedas (Redações do caput e do
inciso I dadas pela Resolução BCB 348, de 17/10/2023);
II - ocorrer movimentação, nos casos previstos no art. 36, de valor igual ou superior
a US$100.000,00 (cem mil dólares dos Estados Unidos da América) ou seu
equivalente em outras moedas; ou
III - ocorrer a data-base das declarações periódicas previstas nos arts. 38 a 40, para
os receptores sujeitos a tais declarações.
Parágrafo único.  As situações previstas nos incisos I e II do caput não se aplicam
às transferências financeiras e às movimentações envolvendo valores mobiliários
negociados em mercado organizado e às operações com tais valores mobiliários
realizadas fora de mercado organizado nos casos previstos na regulamentação do
Conselho Monetário Nacional (CMN) e da Comissão de Valores Mobiliários (CVM).

Art. 33.  A prestação de informações de operações de investimento estrangeiro
direto deve contemplar (Redação dada pela Resolução BCB 348, de 17/10/2023):

I - a identificação do receptor;
II - o detalhamento dos investimentos estrangeiros diretos no receptor, quando
exigido;
III - as declarações trimestrais, quando exigidas;
IV - as declarações anuais, quando exigidas; e
V - as declarações quinquenais, quando exigidas.

Art. 34.  O detalhamento do investimento estrangeiro direto no receptor deve
contemplar:

I - a identificação do investidor não residente;
II - as transferências financeiras e as movimentações decorrentes do investimento
estrangeiro direto, conforme disposto nos arts. 35 e 36; e
III - o código SCE-IED.

[Página 88]

§ 1º  O código SCE-IED é gerado automaticamente pelo SCE-IED após identificação
do receptor e do investidor não residente, que devem ser informados
anteriormente à primeira transferência financeira do investimento, na forma
prevista no art. 32, inciso I, à primeira movimentação, na forma prevista no art. 32,
inciso II, ou à primeira declaração periódica trimestral ou anual.
§ 2º  O receptor de investimento estrangeiro direto sujeito unicamente à prestação
da declaração quinquenal fica dispensado do detalhamento do investimento
estrangeiro direto no SCE-IED (Redações do inciso III e dos parágrafos 1º e 2º, dadas
pela Resolução BCB 348, de 17/10/2023).

§ 3º  As participações de não residente no capital do receptor representadas por
valores mobiliários negociados em mercado organizado não devem ser incluídas
no detalhamento do investimento estrangeiro direto.

Art. 35.  As transferências financeiras, inclusive movimentação de recurso de
interesse de terceiro em conta de não residente em reais, decorrentes do
investimento estrangeiro direto são capturadas automaticamente pelo SCE-IED,
tendo por base as informações disponíveis no Sistema Câmbio, nos casos de
(Redação dada pela Resolução BCB 348, de 17/10/2023):

I - ingresso de moeda; e
II - remessa ao exterior de lucros e dividendos, de juros sobre o capital próprio e de
retorno de capital.

Art. 36.  A movimentação decorrente do investimento estrangeiro direto deve ser
informada em até 30 (trinta) dias de sua ocorrência, nos casos de:

I - capitalização por meio de ativos tangíveis, intangíveis ou por meio de ativos
virtuais (Redação dada pela Resolução BCB 410, de 11/09/2024);
II - conversão em investimento de direitos remissíveis para o exterior não
informado como crédito externo;
III - (Revogado pela Resolução BCB 410, de 11/09/2024).
IV - conferência internacional de quotas ou ações;
V - (Revogado pela Resolução BCB 410, de 11/09/2024).
VI - distribuição de lucros e de dividendos, pagamento de juros sobre capital
próprio, aquisição de residentes, alienação a residentes, restituição de capital e
acervo líquido resultante de liquidação, capitalização de lucros, de dividendos e de
juros sobre capital próprio e outras capitalizações, quando não realizados na forma
do art. 35 (Redação dada pela Resolução BCB 410, de 11/09/2024).
VII - (Revogado pela Resolução BCB 410, de 11/09/2024).

[Página 89]

VIII - (Revogado pela Resolução BCB 410, de 11/09/2024).

Art. 37.  Nas declarações periódicas trimestrais, anuais e quinquenais, devem ser
prestadas informações relativas:

I - à estrutura societária e à identificação de investidores não residentes;
II - ao valor contábil e econômico do receptor;
III - ao lucro operacional e não operacional do receptor; e
IV - a dados contábeis complementares do receptor.

Parágrafo único.  Nas declarações anuais e quinquenais podem ser requeridos
dados referentes a informações econômicas que permitam mapear as atividades
de empresas multinacionais no Brasil e suas regiões, a exemplo de setor de
atividade, emprego, faturamento, tecnologia e comércio internacional.

Art. 38.  A declaração trimestral deve ser prestada pelo receptor de investimento
estrangeiro direto que, na data-base da declaração trimestral de referência, tiver
ativos totais em valor igual ou superior a R$300.000.000,00 (trezentos milhões de
reais).

Parágrafo único.  As datas-bases trimestrais de referência são 31 de março, 30 de
junho e 30 de setembro de cada ano.

Art. 39.  A declaração anual deve ser prestada pelo receptor de investimento
estrangeiro direto que, na data-base de 31 de dezembro do ano anterior, tiver
ativos totais em valor igual ou superior a R$100.000.000,00 (cem milhões de reais).

Art. 40.  A declaração quinquenal, cuja data-base é 31 de dezembro de ano
calendário terminado em 0 (zero) ou 5 (cinco), deve ser prestada pelo receptor de
investimento estrangeiro direto que, na data-base de 31 de dezembro do ano
anterior, tiver ativos totais em valor igual ou superior a R$100.000,00 (cem mil
reais).

Parágrafo único.  Não haverá declaração anual nos anos em que houver declaração
quinquenal.

Art. 41.  Os prazos para prestação das declarações periódicas são:

I - declarações trimestrais:
a) data-base de 31 de março: de 1º de abril até 30 de junho;
b) data-base de 30 de junho: de 1º de julho até 30 de setembro; e
c) data-base de 30 de setembro: de 1º de outubro até 31 de dezembro;

[Página 90]

II - declarações anuais e quinquenais: de 1º de janeiro até 31 de março do ano
subsequente.
§ 1º O prazo para prestação da declaração trimestral com data-base de 30 de
setembro de 2023 é de 1º de novembro até 31 de dezembro de 2023.
§ 2º O prazo para prestação da declaração trimestral com data-base de 30 de
setembro de 2024 é de 11 de novembro até 31 de dezembro de 2024 (Exclusão do
parágrafo único e inclusão dos parágrafos 1º e 2º pela Resolução BCB 348, de
17/10/2023).
CAPÍTULO IV
DISPOSIÇÕES FINAIS

Art. 42.  A prestação de informações prevista no art. 36 desta Resolução será
devida a partir de 1º de outubro de 2024 (Redação dada pela Resolução BCB 348,
de 17/10/2023).

Art. 43.  Devem ser observadas de forma complementar a esta Resolução as
disposições da Resolução BCB nº 281, de 31 de dezembro de 2022 (Norma
transitória).

Art. 44.  O Banco Central do Brasil divulgará, em sua página na internet, Manuais
do Declarante contendo instruções para a prestação de informações de capital
estrangeiro no País.

Art. 45.  Revoga uma série de normativos anteriores.

Resolução BCB Nº 279, de 31 de dezembro de 2022
Regulamenta a Lei nº 14.286, de 29 de dezembro de 2021, para dispor sobre o
capital brasileiro no exterior.

CAPÍTULO I
DISPOSIÇÕES PRELIMINARES
Art. 1º  Esta Resolução dispõe sobre fluxos, estoques e prestação de informações
de capitais brasileiros no exterior, entendidos como os valores, os bens, os direitos
e os ativos de qualquer natureza detidos fora do território nacional por residentes.

§ 1º Para fins desta Resolução, são considerados também como capitais brasileiros
no exterior os financiamentos, empréstimos diretos e créditos comerciais
concedidos no País a não residentes.

[Página 91]

§ 2º As operações de capitais brasileiros no exterior em ativos virtuais devem
observar o disposto nesta Resolução (Parágrafo incluído pela Resolução BCB 521,
de 10/11/2025).
CAPÍTULO II
DOS FLUXOS E ESTOQUES DO CAPITAL BRASILEIRO NO EXTERIOR

Art. 2º  A aplicação do capital brasileiro no exterior pode ser efetuada em qualquer
modalidade regularmente praticada no mercado internacional.
Parágrafo único.  As operações de derivativos no exterior podem ser efetuadas em
qualquer modalidade regularmente praticada no mercado internacional em bolsas
ou em mercado de balcão.

Art. 3º  Os fluxos e estoques de capitais brasileiros no exterior devem cumprir as
exigências legais, e a sua fundamentação econômica deve ser observada.
Parágrafo único.  A documentação comprobatória dos fluxos e estoques de capital
brasileiro no exterior deve ser mantida pelo prazo de 10 (dez) anos contados a
partir da conclusão da operação de capital brasileiro no exterior, podendo o Banco
Central do Brasil, durante esse período, solicitá-la ao detentor do capital sempre
que considerar necessário.

Art. 4º  Entidades sujeitas a regulamentação específica devem observar,
adicionalmente, os requisitos regulatórios próprios às suas atividades na aplicação
de capital brasileiro no exterior.

Art. 5º  A aplicação em participação no capital de sociedade, quando feita por meio
de conferência internacional de ações ou outros ativos, não pode caracterizar
participações recíprocas entre as sociedades nacional e estrangeira.

§ 1º  Para fins do disposto no caput, entende-se por conferência internacional de
ações ou outros ativos:
I - a integralização de capital de sociedade brasileira efetuada por não residente
no Brasil, mediante dação ou permuta de participação societária detida em
sociedade estrangeira, sediada no exterior; ou
II - a integralização de capital de sociedade estrangeira, sediada no exterior,
realizada mediante dação ou permuta, por residente no Brasil, de participação
societária detida em sociedade brasileira.
§ 2º  Até 31 de outubro de 2023, para a realização de investimentos por meio de
conferência internacional de ações ou outros ativos será exigida a realização de
operações simultâneas de câmbio relativas ao ingresso de investimento externo no
País e à saída de investimento brasileiro para o exterior.

[Página 92]

Art. 6º  As transferências financeiras relacionadas a capital brasileiro no exterior
devem ser cursadas em instituição autorizada a operar no mercado de câmbio,
observados os limites e as condições específicas estabelecidas na legislação e na
regulamentação.

Parágrafo único.  No caso de negociação de instrumentos derivativos no exterior,
as transferências devem ser cursadas apenas em banco autorizado a operar no
mercado de câmbio.

CAPÍTULO III
DA PRESTAÇÃO DE INFORMAÇÕES

Art. 7º  Devem ser prestadas ao Banco Central do Brasil informações sobre o
capital brasileiro no exterior nos termos desta Resolução, relativas a:
I - participação em capital de sociedades não residentes;
II - certificados de depósito de valores mobiliários (BDRs) emitidos por sociedades
não residentes;
III - cotas de fundos de investimento no exterior;
IV - títulos de dívida emitidos por não residentes;
V - empréstimos e financiamentos concedidos a não residentes;
VI - depósitos em instituições não residentes;
VII - créditos comerciais concedidos a não residentes;
VIII - imóveis localizados no exterior;
IX - ativos virtuais;
X - derivativos negociados no exterior; e
XI - títulos de dívida sustentáveis emitidos por não residentes (Incluído pela
Resolução BCB 492, de 14/08/2025).

§ 1º  Também devem ser prestadas informações relativas a:
I - receitas de exportações mantidas no exterior e sua utilização; e
II - rendas de capitais brasileiros no exterior.

§ 2º  Considera-se ainda capital brasileiro no exterior para efeitos de prestação de
informações o patrimônio no exterior cuja titularidade foi transferida por qualquer
arranjo, revogável ou não, a agente fiduciário no exterior para administração em
favor de beneficiários residentes especificados.

§ 3º  Para fins desta Resolução os títulos sustentáveis podem ser:

[Página 93]

I - Títulos Verdes: títulos de dívida em que o uso dos recursos captados é restrito
ao financiamento ou refinanciamento de atividades ou projetos que gerem
benefícios ao meio ambiente;
II - Títulos Sociais: títulos de dívida em que o uso dos recursos captados é restrito
ao financiamento ou refinanciamento de atividades ou projetos que gerem
benefícios sociais;
III - Títulos de Sustentabilidade: títulos de dívida em que o uso dos recursos
captados é restrito ao financiamento ou refinanciamento de atividades ou projetos
que gerem benefícios sociais e ao meio ambiente; ou
IV - Títulos Vinculados a Metas de Sustentabilidade: títulos de dívida em que os
recursos captados têm destinação livre, mas o emissor se compromete a atingir
objetivos pré-definidos de sustentabilidade – que melhorem as condições do meio
ambiente, da sociedade ou de ambos (Parágrafo e incisos incluídos pela Resolução
BCB 492, de 14/08/2025).
Art. 8º  É responsável pela prestação de informações a pessoa física ou jurídica
residente detentora de capital brasileiro no exterior.

Parágrafo único.  São os responsáveis pela prestação de informações nos termos
desta Resolução, conforme o caso:

I - a instituição depositária de BDRs;

II - o fundo de investimento com aplicações no exterior, por meio de seus
administradores; e
III - o residente beneficiário dos arranjos referidos no § 2º do art. 7º.

Art. 9º  A prestação de informações deve ser feita em declarações anual e
trimestral enviadas por meio eletrônico ao Banco Central do Brasil.

Art. 10.  A declaração anual deve ser enviada quando os capitais brasileiros no
exterior, na data-base anual, totalizarem quantia igual ou superior a
US$1.000.000,00 (um milhão de dólares dos Estados Unidos da América) ou seu
equivalente em outras moedas.

Parágrafo único.  A data-base da declaração anual é 31 de dezembro.

Art. 11.  A declaração trimestral deve ser enviada quando os capitais brasileiros no
exterior, na data-base trimestral, totalizarem quantia igual ou superior a
US$100.000.000,00 (cem milhões de dólares dos Estados Unidos da América) ou
seu equivalente em outras moedas.
Parágrafo único.  As datas-bases das declarações trimestrais são 31 de março, 30
de junho e 30 de setembro.

[Página 94]

Art. 12.  Os limites estabelecidos nos arts. 10 e 11:
I - no caso de residentes, com exceção daqueles mencionados nos incisos I e II do
parágrafo único do art. 8º, não incluem:
a) BDRs;
b) cotas de fundos de investimentos no País que possuam ativos no exterior;
II - no caso de instituição depositária de BDR, são calculados individualmente por
programa autorizado pela Comissão de Valores Mobiliários; e
III - no caso de fundo de investimento, são calculados pelo total de ativos no
exterior.
Parágrafo único.  Caso os ativos no exterior de residentes sejam mantidos em conta
conjunta de depósitos ou, por qualquer outra forma, pertençam em condomínio a
duas ou mais pessoas físicas ou jurídicas, cada parte deverá considerar o valor
integral desse ativo para enquadramento quanto à obrigatoriedade de prestar a
declaração, devendo cada declarante realizar a declaração apenas da sua
respectiva parcela, mesmo que o valor total declarado individualmente seja
inferior ao piso de obrigatoriedade.

Art. 13.  O período para o envio da declaração anual é de 15 de fevereiro a 5 de
abril do ano subsequente à data-base.

Art. 14.  Os períodos para o envio das declarações trimestrais são:
I - de 30 de abril a 5 de junho subsequente, no caso da data-base de 31 de março;
II - de 31 de julho a 5 de setembro subsequente, no caso da data-base de 30 de
junho;
III - de 31 de outubro a 5 de dezembro subsequente, no caso da data-base de 30 de
setembro.

Art. 15.  O responsável pela prestação de informações nos termos deste Capítulo
deve manter, pelo prazo de 10 (dez) anos contados a partir da data-base da
declaração, a documentação comprobatória utilizada para respaldar as
informações prestadas, para apresentação ao Banco Central do Brasil, quando
solicitada.

Art. 16.  O responsável pela prestação de informações está sujeito às penalidades
estabelecidas na legislação e na regulamentação específica.

CAPÍTULO IV
DISPOSIÇÕES FINAIS
Art. 17.  O Banco Central do Brasil divulgará em sua página na internet o Manual
do Declarante contendo instruções para o preenchimento das declarações de
capitais brasileiros no exterior.

[Página 95]

Art. 18.  A divulgação de dados pelo Banco Central do Brasil relativos às
informações prestadas com base nesta Resolução dar-se-á de maneira a não
identificar situações individuais.

Resolução BCB nº 280, de 31 de dezembro de 2022
Regulamenta o art. 1º da Lei nº 14.286, de 29 de dezembro de 2021, em relação à
definição de residente e de não residente a ser aplicada para pessoas físicas e
jurídicas.

Art. 1º  Esta Resolução estabelece a definição de residente e de não residente para
fins da Lei nº 14.286, de 29 de dezembro de 2021, que dispõe sobre o mercado de
câmbio brasileiro, o capital brasileiro no exterior, o capital estrangeiro no País e a
prestação de informações ao Banco Central do Brasil.
 Art. 2º  Considera-se residente a pessoa física:
I - que resida no Brasil em caráter permanente;
II - que se ausente do País para prestar serviços a partir do exterior para a
Administração Pública Federal brasileira;
III - que se encontre no Brasil com autorização de residência deferida por prazo
indeterminado, a partir da data de ingresso no País;
IV - que se encontre no Brasil com visto temporário:
a) trabalhando com vínculo empregatício ou desenvolvendo atividade econômica
no País, a partir da data de ingresso no País; ou
b) com permanência há mais de 12 (doze) meses consecutivos no Brasil, desde que
não haja manifestação da pessoa física para a instituição autorizada a operar no
mercado de câmbio com justificativa para reduzir ou aumentar esse prazo;
V - brasileira que, na condição de não residente, entrar no País com ânimo
definitivo, a partir da data de ingresso no País;
VI - residente que se retire em caráter temporário do território nacional, durante
os primeiros 12 (doze) meses consecutivos de ausência, desde que não haja
manifestação da pessoa física para a instituição autorizada a operar no mercado
de câmbio com justificativa para reduzir ou aumentar esse prazo.

Art. 3º  Considera-se não residente a pessoa física:
I - que não se enquadre nas hipóteses previstas no art. 2º;

[Página 96]

II - que se retire em caráter permanente do território nacional, a partir da data da
saída do País;
III - que, na condição de não residente, preste serviço a partir do Brasil como
funcionária de governo estrangeiro, ressalvado o disposto no inciso V do art. 2º;
IV - residente que se ausente do Brasil em caráter temporário, a partir do dia
seguinte àquele em que complete 12 (doze) meses consecutivos de ausência,
desde que não haja manifestação da pessoa física para a instituição autorizada a
operar no mercado de câmbio com justificativa para reduzir ou aumentar esse
prazo.

Art. 4º  Quanto à pessoa jurídica, considera-se:

I - residente a entidade domiciliada ou com sede no Brasil;

II - não residente a entidade domiciliada ou com sede no exterior e que não se
enquadre na hipótese do inciso I deste artigo.

Art. 5º  É de responsabilidade exclusiva da pessoa física a justificativa contida na
manifestação prevista nesta Resolução e coletada pela instituição autorizada a
operar no mercado de câmbio.$mat$, 'junho/2026'),
(1, 4, $mat$Resolução BCB 542/2025: sociedades corretoras de câmbio$mat$, $mat$Resolução BCB n° 542, de 18 de dezembro de 2025

Estabelece condições para a constituição, a organização e o funcionamento das
sociedades corretoras de câmbio.
CAPÍTULO I
DO OBJETO E DO ÂMBITO DE APLICAÇÃO
Art. 1º  Esta Resolução estabelece as normas gerais a serem observadas em
matéria de organização, disciplina, fiscalização e atividades das sociedades
corretoras de câmbio.

CAPÍTULO II
DAS CARACTERÍSTICAS, DA CONSTITUIÇÃO, DO FUNCIONAMENTO E DAS
NORMAS OPERACIONAIS

[Página 111]

Seção I
Do objeto social e das operações e atividades admitidas
Art. 2º  A sociedade corretora de câmbio tem por objeto social a intermediação em
operações de câmbio e a prática de operações no mercado de câmbio, nos termos
e limites da legislação e da regulamentação em vigor.
Art. 3º  É facultado à sociedade corretora de câmbio, além das operações previstas
no art. 2º, atuar como:
I - emissora de moeda eletrônica; e
II - intermediária de ativos virtuais.
§ 1º  As faculdades de que trata o caput devem ser exercidas em consonância com
a legislação e a regulamentação que disciplinam as referidas prestações de
serviços.
§ 2º  Os serviços previstos no caput não devem ser o objeto principal da sociedade
corretora de câmbio.
Seção II
Da constituição, da autorização para funcionamento e da denominação e do
capital social

Art. 4º  As sociedades corretoras de câmbio devem ser constituídas sob a forma de
sociedades anônimas ou de sociedades limitadas.
Parágrafo único.  É vedada a constituição de sociedade corretora de câmbio como
sociedade empresária na qual figure pessoa natural como sócio único.
Art. 5º  O funcionamento de sociedades corretoras de câmbio depende de
autorização prévia do Banco Central do Brasil, na forma da regulamentação
específica.
Art. 6º  No nome empresarial das instituições de que trata o art. 2º deve constar a
expressão “Sociedade Corretora de Câmbio”.
§ 1º  É vedado o uso de termos característicos da nomenclatura das demais
instituições autorizadas a funcionar pelo Banco Central do Brasil em vernáculo ou
em idioma estrangeiro.
§ 2º  A expressão “Sociedade Corretora de Câmbio” é privativa de sociedade
corretora de câmbio.
Seção III
Das vedações
Art. 7º  É vedado à sociedade corretora de câmbio:
I - realizar operações que caracterizem, sob qualquer forma, a concessão de
financiamentos, empréstimos ou adiantamentos a seus clientes, inclusive por meio
de cessão de direitos;

[Página 112]

II - adquirir bens não destinados ao uso próprio, salvo os recebidos em liquidação
de dívidas de difícil ou duvidosa solução, conforme regulamentação em vigor; ou
III - obter empréstimos ou financiamentos de instituições financeiras, exceto se
vinculados à aquisição de bens para uso próprio.
Seção IV
Da assistência aos contratantes de operações
Art. 8º  As sociedades corretoras de câmbio prestarão assistência, orientação e
suporte técnico, inclusive por meio virtual, aos contratantes das operações em que
intervierem, até o final da liquidação dos contratos respectivos.

Capítulo III
DISPOSIÇÕES GERAIS E FINAIS
Art. 9º  O Banco Central do Brasil adotará, nos termos de suas competências legais,
as medidas necessárias à execução do disposto nesta Resolução.
Art. 10.  Fica revogada a Resolução CMN nº 5.009, de 24 de março de 2022,
publicada no Diário Oficial da União de 28 de março de 2022.
Art. 11.  Esta Resolução entra em vigor em 2 de fevereiro de 2026.

[Página 113]$mat$, 'junho/2026'),
(4, 1, $mat$Correspondentes cambiais: Resolução CMN 4.935/2021 (cap. 7)$mat$, $mat$7. Os Correspondentes Cambiais

A Resolução CMN n° 4.935 de 29 de julho de 2021, trata de todos os tipos de
correspondentes bancários, mas aqui serão abordados apenas os dispositivos
aplicáveis aos correspondentes cambiais.
Dispõe sobre a contratação de correspondentes no País pelas instituições
financeiras e pelas demais instituições autorizadas a funcionar pelo Banco Central
do Brasil.
CAPÍTULO I
DO OBJETO
Art. 1º  Esta Resolução dispõe sobre a contratação de correspondentes no País
pelas instituições financeiras e pelas demais instituições autorizadas a funcionar
pelo Banco Central do Brasil.
CAPÍTULO II
          DA CONTRATAÇÃO DE CORRESPONDENTE

Seção I
     Das Características Gerais

Art. 2º  As instituições financeiras e demais instituições autorizadas a funcionar
pelo Banco Central do Brasil devem observar as disposições desta Resolução como
condição para a contratação de correspondentes no País, visando à prestação de
serviços, pelo contratado, de atividades de atendimento a clientes e usuários da
instituição contratante.
§ 1º  A prestação de serviços de que trata esta Resolução, de forma pessoal ou por
meio de plataforma eletrônica, somente pode ser contratada com correspondente
no País.
§ 2º  Considera-se plataforma eletrônica sistema eletrônico operado pelo
correspondente no País, que permite a realização das atividades de atendimento
de que trata o art. 12 desta Resolução por meio de sítio eletrônico na internet,
aplicativo ou outras plataformas de comunicação em rede.
Art. 3º  O correspondente atua por conta e sob as diretrizes da instituição
contratante, que assume inteira responsabilidade pelo atendimento prestado aos
clientes e usuários por meio do contratado.

[Página 114]

Parágrafo único.  Cabe à instituição contratante garantir a integridade, a
confiabilidade, a segurança e o sigilo das transações realizadas por meio do
contratado, bem como o cumprimento da legislação e da regulamentação relativas
a essas transações.
Art. 4º  Podem ser contratados, na qualidade de correspondente:
I - as sociedades, os empresários e as associações definidos na Lei nº 10.406, de 10
de janeiro de 2002 (Código Civil);
II - os prestadores de serviços notariais e de registro de que trata a Lei nº 8.935, de
18 de novembro de 1994; e
III - as empresas públicas.

Art. 5º  É vedada a celebração de contrato de correspondente no País com:

I - entidade cuja atividade principal seja a prestação de serviços de correspondente
para o desempenho das atividades de atendimento definidas nos incisos II, IV e VI
do art. 12; e
II - entidade cujo controle seja exercido por administrador da instituição
contratante ou por administrador de entidade controladora da instituição
contratante.
Parágrafo único.  A vedação de que trata o inciso II não se aplica à hipótese em que
o administrador seja também controlador da instituição contratante.
Art. 6º  Não é admitida a celebração de contrato de correspondente que configure
contrato de franquia, nos termos da Lei nº 13.966, de 26 de dezembro de 2019, ou
cujos efeitos sejam semelhantes no tocante aos direitos e obrigações das partes ou
às formas empregadas para o atendimento ao público.
Art. 7º  A contratação, como correspondente, de instituições financeiras e demais
instituições autorizadas a funcionar pelo Banco Central do Brasil deve observar as
seguintes condições:
I - dispensa das exigências estabelecidas nos arts. 15 e 16, na hipótese de a
instituição contratada oferecer a seus próprios clientes operações da mesma
natureza; e
II - não incidência da vedação estabelecida no art. 14, inciso IX.
Art. 8º  Depende de prévia autorização do Banco Central do Brasil a celebração de
contrato de correspondente com entidade não integrante do Sistema Financeiro
Nacional (SFN) cuja denominação ou nome fantasia empregue termos

[Página 115]

característicos das denominações das instituições do SFN, ou de expressões
similares em vernáculo ou em idioma estrangeiro.
Art. 9º  A instituição contratante deve designar diretor responsável pela
contratação de correspondentes no País e pelo atendimento por eles prestado.
Art. 10.  Admite-se o substabelecimento do contrato de correspondente, em um
único nível, desde que o contrato inicial preveja essa possibilidade e as condições
para sua efetivação, entre as quais a anuência da instituição contratante.
§ 1º  A instituição contratante, para anuir ao substabelecimento, deve assegurar o
cumprimento das disposições desta Resolução pelas entidades substabelecidas.
§ 2º  É vedado o substabelecimento do contrato no tocante às atividades de
atendimento em operações de câmbio.
§ 3º  As entidades substabelecidas devem adotar as formas estabelecidas no art.
4º.
Art. 11.  É vedada à instituição contratante:
I - a cobrança de clientes atendidos pelo correspondente de tarifa, comissão,
valores referentes a ressarcimento de serviços prestados por terceiros ou qualquer
outra forma de remuneração, pelo fornecimento de produtos ou serviços de
responsabilidade da referida instituição, ressalvadas as tarifas constantes da tabela
adotada pela instituição contratante, de acordo com a regulamentação em vigor;
e
II - a prestação de serviços por correspondente no recinto de suas dependências.
Seção II
       Do Objeto do Contrato de Correspondente
Art. 12.  O contrato de correspondente pode ter por objeto as seguintes atividades
de atendimento, visando ao fornecimento de produtos e serviços de
responsabilidade da instituição contratante a seus clientes e usuários:
Os incisos I ao VI não se aplicam ao câmbio.
VII - realização de operações de câmbio de responsabilidade da instituição
contratante, observado o disposto no art. 13.
Parágrafo único.  Pode ser incluída no contrato a prestação de serviços
complementares de coleta de informações cadastrais e de documentação, bem
como controle e processamento de dados.

[Página 116]

Art. 13.  O atendimento prestado pelo correspondente em operações de câmbio
deve ser contratualmente restrito às seguintes operações:
I - Compra e venda de moeda estrangeira em espécie, cheque ou cheque de viagem,
bem como carga de moeda estrangeira em cartão pré-pago;
II - execução ativa ou passiva de ordem de pagamento relativa a transferência
unilateral do ou para o exterior; e
III - recepção e encaminhamento de propostas de operações de câmbio.
Parágrafo único.  O contrato que inclua o atendimento nas operações de câmbio
relacionadas nos incisos I e II do caput deve prever as seguintes condições:
I - limitação ao valor de US$3.000,00 (três mil dólares dos Estados Unidos), ou seu
equivalente em outras moedas, por operação, e no caso de operação de compra ou
de venda de moeda estrangeira em espécie com entrega do contravalor em moeda
nacional também em espécie, limitação ao valor de US$1.000,00 (mil dólares dos
Estados Unidos), ou seu equivalente em outras moedas;
II - obrigatoriedade de informação ao cliente do Valor Efetivo Total (VET) da
operação, expresso em reais por unidade de moeda estrangeira e calculado
considerando a taxa de câmbio, os tributos incidentes e as tarifas eventualmente
cobradas;
III - obrigatoriedade de entrega ao cliente de comprovante para cada operação de
câmbio realizada, contendo a identificação da instituição contratante, da empresa
contratada e do cliente, a indicação da moeda estrangeira, da taxa de câmbio, dos
valores em moeda estrangeira e em moeda nacional e do VET, bem como a
identificação do pagador ou recebedor no exterior nas operações de câmbio de que
trata o inciso II do caput;
IV - cláusula de exclusividade do correspondente com a instituição contratante
para a prestação de serviços relativa às operações de câmbio de que trata o inciso
I do caput; e
V - observância das disposições regulamentares que dispõem sobre o mercado de
câmbio.
Seção III
     Das Condições Gerais do Contrato de Correspondente
Art. 14.  O contrato de correspondente deve estabelecer:

[Página 117]

I - exigência de que o contratado mantenha relação formalizada mediante vínculo
empregatício ou vínculo contratual de outra espécie com as pessoas naturais
integrantes da sua equipe, envolvidas no atendimento a clientes e usuários;
II - vedação à utilização, pelo contratado, de logomarca ou de outros atributos que
sejam similares aos adotados pela instituição contratante em suas agências, postos
de atendimento, sítio eletrônico na internet, aplicativo ou outras plataformas de
comunicação em rede;
III - divulgação ao público, pelo contratado, de sua condição de prestador de
serviços à instituição contratante, identificada pelo nome com que é conhecida no
mercado, com descrição dos produtos e serviços oferecidos e canais de contato da
instituição contratante, inclusive de sua ouvidoria, em local visível, em destaque e
em formato legível, por meio de:
a) sítio eletrônico do correspondente na internet, acessível na página inicial;
b) aplicativo e outras plataformas de comunicação em rede do correspondente; ou
c) painel mantido nos locais onde seja prestado atendimento aos clientes e
usuários, no caso de o correspondente possuir dependências físicas.
IV - obrigatoriedade de apresentação aos clientes, durante o atendimento, dos
custos e das condições de contratação dos produtos e serviços oferecidos pelas
instituições contratantes de que tratam os incisos I, V e VII do art. 12, na hipótese
de atuar como correspondente de mais de uma instituição;
V - realização de acertos financeiros entre a instituição contratante e o
correspondente, no máximo, a cada dois dias úteis;
VI - utilização, pelo correspondente, exclusivamente de padrões, normas
operacionais e tabelas definidas pela instituição contratante, inclusive na
proposição ou aplicação de tarifas, taxas de juros, taxas de câmbio, cálculo de
Custo Efetivo Total (CET) ou do VET e quaisquer quantias auferidas ou devidas pelo
cliente, inerentes aos produtos e serviços de fornecimento da instituição
contratante;
VII - vedação ao contratado de emitir, a seu favor, instrumentos de pagamento ou
títulos relativos às operações realizadas, ou de cobrar em seu próprio benefício, a
qualquer título, valor relacionado com os produtos e serviços de fornecimento da
instituição contratante;
VIII - vedação à realização de adiantamento a cliente, pelo correspondente, por
conta de recursos a serem liberados pela instituição contratante;

[Página 118]

IX - vedação à prestação de garantia, inclusive coobrigação, pelo correspondente
nas operações a que se refere o contrato;
X - realização, pelo contratado, de atendimento aos clientes e usuários relativo a
demandas envolvendo esclarecimentos, obtenção de documentos, liberações,
reclamações e outros referentes aos produtos e serviços fornecidos, as quais serão
encaminhadas de imediato à instituição contratante, quando não forem resolvidas
pelo correspondente;
XI - permissão de acesso do Banco Central do Brasil aos contratos firmados ao
amparo desta Resolução, à documentação e informações referentes aos produtos
e serviços fornecidos, bem como às dependências do contratado e respectiva
documentação relativa aos atos constitutivos, registros, cadastros e licenças
requeridos pela legislação;
XII - possibilidade de adoção de medidas administrativas pela instituição
contratante, por sua iniciativa, nos termos do art. 18, ou por determinação do
Banco Central do Brasil;
XIII - observância da política de atuação e de contratação, estabelecida pela
instituição contratante nos termos do art. 18, e das medidas administrativas nela
previstas; e
XIV - declaração de que o contratado tem pleno conhecimento de que a realização,
por sua própria conta, das operações consideradas privativas das instituições
financeiras ou de outras operações vedadas pela legislação vigente sujeita o
infrator às penalidades previstas nas Leis ns. 7.492, de 16 de junho de 1986, e
13.506, de 13 de novembro de 2017.
Parágrafo único.  A vedação de que trata o inciso IX não se aplica às operações de
financiamento e de arrendamento mercantil de bens e serviços fornecidos pelo
próprio correspondente no exercício de atividade comercial integrante de seu
objeto social.
Seção IV
   Do Encaminhamento de Propostas de Operações de Crédito e de
Arrendamento Mercantil (suprimida pois não se refere a câmbio)
CAPÍTULO III
          DO CONTROLE DAS ATIVIDADES DO CORRESPONDENTE
Art. 17.  A instituição contratante deve colocar à disposição do correspondente e
de sua equipe de atendimento documentação técnica adequada, bem como
manter canal
de comunicação
permanente com
objetivo de
prestar
esclarecimentos tempestivos à referida equipe sobre seus produtos e serviços, e

[Página 119]

deve atender, conforme o art. 14, inciso X, às demandas apresentadas pelos
clientes e usuários ao contratado.
Art. 18.  As instituições mencionadas no art. 1º que mantiverem contratos de
correspondente no País devem estabelecer e manter atualizada política de atuação
e de contratação desses prestadores de serviços, prevendo, no mínimo:
I - critérios exigidos para contratação;
II - mecanismos de controle de qualidade da atuação do correspondente, levando
em conta indicadores de acompanhamento de qualidade de atendimento dos
clientes, considerando, inclusive, demandas e reclamações registradas; e
III - regras de remuneração pela prestação dos serviços.
§ 1º  Os mecanismos a que se refere o inciso II do caput devem conter medidas
administrativas, contratualmente previstas, a serem adotadas pela instituição
contratante em relação ao correspondente, aos substabelecidos e aos agentes
certificados, se verificadas irregularidades ou inobservância dos padrões
estabelecidos, incluindo a possibilidade de suspensão do atendimento prestado ao
público e o encerramento antecipado do contrato nos casos considerados graves
pela instituição contratante.
§ 2º  As medidas administrativas de que trata o § 1º devem prever orientações,
treinamentos e sanções, e sua aplicação deve ser ponderada levando-se em
consideração aspectos qualitativos e quantitativos relacionados à gravidade da
irregularidade detectada.
§ 3º  As regras de remuneração de que trata o inciso III do caput devem:
I - ser compatíveis com a política de gestão de riscos, de modo a não incentivar
comportamentos que elevem a exposição ao risco acima dos níveis considerados
prudentes nas estratégias de curto, médio e longo prazos adotadas pela
instituição;
II - ter viabilidade econômica no caso das operações de crédito e de arrendamento
mercantil cujas propostas sejam encaminhadas pelos correspondentes; e
III - considerar qualquer forma de remuneração, inclusive adiantamentos por meio
de operação de crédito, aquisição de recebíveis ou constituição de garantias, bem
como o pagamento de despesas, a distribuição de prêmios, bonificações,
promoções ou qualquer outra forma assemelhada.
§ 4º  A política de que trata o caput deve ser formalizada em documento específico
e aprovada pelo conselho de administração ou, na sua ausência, pela diretoria da
instituição.

[Página 120]

§ 5º  Admite-se que a política de que trata o caput seja unificada por:
I - conglomerado; ou
II - sistema cooperativo de crédito.
§ 6º  O documento de que trata o § 4º deve ser mantido à disposição do Banco
Central do Brasil.
Art. 19.  As instituições mencionadas no art. 1º devem adequar o sistema de
controles internos com o objetivo de monitorar as atividades de atendimento ao
público realizadas por intermédio de correspondentes, compatibilizando-os com o
volume e a complexidade das operações realizadas.
§ 1º  A auditoria interna da instituição contratante deve avaliar, anualmente, a
efetividade dos mecanismos de controle de qualidade.
§ 2º  Fica o Banco Central do Brasil autorizado a:
I - determinar a adoção das medidas administrativas de que trata o § 1º do art. 18,
inclusive a suspensão do atendimento prestado ao público ou o encerramento do
contrato; ou
II - condicionar a contratação de novos correspondentes à correção de deficiências
na política de que trata o art. 18.
§ 3º  Nas hipóteses do § 2º, a decisão do Banco Central do Brasil deverá ser
precedida de manifestação da instituição contratante.
CAPÍTULO IV
       DA DIVULGAÇÃO DE INFORMAÇÕES
Art. 21.  A instituição contratante deve manter atualizada a relação de seus
contratados:
I - na forma de dados abertos; e
II - no seu sítio eletrônico na internet, acessível na página inicial e em local visível
e formato legível.
§ 1º  A relação de que trata o caput deve conter as seguintes informações:
I - identificação;
II - localização; e

[Página 121]

III - atividades de atendimento, referidas no art. 12, incluídas no contrato e, no caso
de o contratado prestar serviços presencialmente, especificadas por ponto de
atendimento.
§ 2º  O Banco Central do Brasil divulgará o conteúdo e as especificações para
divulgação das informações de que trata o § 1º nos termos definidos no caput.
Art. 22.  A instituição contratante deve segregar as informações sobre demandas
e reclamações recebidas pela instituição, nos respectivos serviços de atendimento
e de ouvidoria, apresentadas por clientes e usuários atendidos por
correspondentes.
Art. 23.  A instituição contratante deve informar ao Banco Central do Brasil, na
forma definida pela referida autarquia:
I - o diretor responsável de que trata o art. 9º desta Resolução; e
II - a celebração de contrato de correspondente, bem como posteriores
atualizações e encerramento.
CAPÍTULO V
  DISPOSIÇÕES FINAIS
Art. 24.  Fica o Banco Central do Brasil autorizado a baixar as normas e a adotar as
medidas necessárias à execução do disposto nesta Resolução”.
Art. 25.  Revoga Resoluções do Conselho Monetário Nacional e do Banco Central
que tratavam do mesmo assunto e correlatos.

[Página 122]$mat$, 'junho/2026'),
(2, 2, $mat$Lei 9.613/98 (lavagem de dinheiro) e Lei 13.260/2016 (terrorismo)$mat$, $mat$8. Prevenção à lavagem de dinheiro, combate ao financiamento do
terrorismo e à proliferação de armas de destruição em massa
(PLD/FTP).

Legislação
Lei nº 9.613, de 3 de março de 1998 (atualizada pelas Leis nºs 12.683, de 9 de
julho de 2012, e 14.478, de 21 de dezembro de 2022)
Dispõe sobre os crimes de "lavagem" ou ocultação de bens, direitos e valores; a
prevenção da utilização do sistema financeiro para os ilícitos previstos nesta Lei;
cria o Conselho de Controle de Atividades Financeiras - COAF, e dá outras
providências.
CAPÍTULO I
Dos Crimes de "Lavagem" ou Ocultação de Bens, Direitos e Valores
Art. 1o  Ocultar ou dissimular a natureza, origem, localização, disposição,
movimentação ou propriedade de bens, direitos ou valores provenientes, direta ou
indiretamente, de infração penal.
Pena: reclusão, de 3 (três) a 10 (dez) anos, e multa.
§ 1o  Incorre na mesma pena quem, para ocultar ou dissimular a utilização de bens,
direitos ou valores provenientes de infração penal:
I - os converte em ativos lícitos;
II - os adquire, recebe, troca, negocia, dá ou recebe em garantia, guarda, tem em
depósito, movimenta ou transfere;
III - importa ou exporta bens com valores não correspondentes aos verdadeiros.
§ 2o  Incorre, ainda, na mesma pena quem:
I - utiliza, na atividade econômica ou financeira, bens, direitos ou valores
provenientes de infração penal;
II - participa de grupo, associação ou escritório tendo conhecimento de que sua
atividade principal ou secundária é dirigida à prática de crimes previstos nesta Lei.
§ 3º A tentativa é punida nos termos do parágrafo único do art. 14 do Código Penal.

[Página 123]

§ 4o  A pena será aumentada de um a dois terços, se os crimes definidos nesta Lei
forem cometidos de forma reiterada ou por intermédio de organização criminosa.
§ 5o  A pena poderá ser reduzida de um a dois terços e ser cumprida em regime
aberto ou semiaberto, facultando-se ao juiz deixar de aplicá-la ou substituí-la, a
qualquer tempo, por pena restritiva de direitos, se o autor, coautor ou partícipe
colaborar espontaneamente com as autoridades, prestando esclarecimentos que
conduzam à apuração das infrações penais, à identificação dos autores, coautores
e partícipes, ou à localização dos bens, direitos ou valores objeto do crime.
§ 6º Para a apuração do crime de que trata este artigo, admite-se a utilização da
ação controlada e da infiltração de agentes.
CAPÍTULO II
Disposições Processuais Especiais
Art. 2º  O processo e julgamento dos crimes previstos nesta Lei:
I – obedecem às disposições relativas ao procedimento comum dos crimes punidos
com reclusão, da competência do juiz singular;
II - independem do processo e julgamento das infrações penais antecedentes,
ainda que praticados em outro país, cabendo ao juiz competente para os crimes
previstos nesta Lei a decisão sobre a unidade de processo e julgamento;
III - são da competência da Justiça Federal:
a) quando praticados contra o sistema financeiro e a ordem econômico-financeira,
ou em detrimento de bens, serviços ou interesses da União, ou de suas entidades
autárquicas ou empresas públicas;
b) quando a infração penal antecedente for de competência da Justiça
Federal.
§ 1o  A denúncia será instruída com indícios suficientes da existência da infração
penal antecedente, sendo puníveis os fatos previstos nesta Lei, ainda que
desconhecido ou isento de pena o autor, ou extinta a punibilidade da infração penal
antecedente.
§ 2o  No processo por crime previsto nesta Lei, não se aplica o disposto no art. 366
do Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal),
devendo o acusado que não comparecer nem constituir advogado ser citado por
edital, prosseguindo o feito até o julgamento, com a nomeação de defensor
dativo.
Art. 3o  (Revogado)

[Página 124]

Art. 4o  O juiz, de ofício, a requerimento do Ministério Público ou mediante
representação do delegado de polícia, ouvido o Ministério Público em 24 (vinte e
quatro) horas, havendo indícios suficientes de infração penal, poderá decretar
medidas assecuratórias de bens, direitos ou valores do investigado ou acusado, ou
existentes em nome de interpostas pessoas, que sejam instrumento, produto ou
proveito dos crimes previstos nesta Lei ou das infrações penais antecedentes.
§ 1o  Proceder-se-á à alienação antecipada para preservação do valor dos bens
sempre que estiverem sujeitos a qualquer grau de deterioração ou depreciação, ou
quando houver dificuldade para sua manutenção.
§ 2o  O juiz determinará a liberação total ou parcial dos bens, direitos e valores
quando comprovada a licitude de sua origem, mantendo-se a constrição dos bens,
direitos e valores necessários e suficientes à reparação dos danos e ao pagamento
de prestações pecuniárias, multas e custas decorrentes da infração penal.
§ 3o  Nenhum pedido de liberação será conhecido sem o comparecimento pessoal
do acusado ou de interposta pessoa a que se refere o caput deste artigo, podendo
o juiz determinar a prática de atos necessários à conservação de bens, direitos ou
valores, sem prejuízo do disposto no § 1o.
§ 4o  Poderão ser decretadas medidas assecuratórias sobre bens, direitos ou valores
para reparação do dano decorrente da infração penal antecedente ou da prevista
nesta Lei ou para pagamento de prestação pecuniária, multa e custas.
Art. 4o-A.  A alienação antecipada para preservação de valor de bens sob constrição
será decretada pelo juiz, de ofício, a requerimento do Ministério Público ou por
solicitação da parte interessada, mediante petição autônoma, que será autuada
em apartado e cujos autos terão tramitação em separado em relação ao processo
principal.
§ 1o  O requerimento de alienação deverá conter a relação de todos os demais bens,
com a descrição e a especificação de cada um deles, e informações sobre quem os
detém e local onde se encontram.
§ 2o  O juiz determinará a avaliação dos bens, nos autos apartados, e intimará o
Ministério Público.
§ 3o  Feita a avaliação e dirimidas eventuais divergências sobre o respectivo laudo,
o juiz, por sentença, homologará o valor atribuído aos bens e determinará sejam
alienados em leilão ou pregão, preferencialmente eletrônico, por valor não inferior
a 75% (setenta e cinco por cento) da avaliação.
§ 4o  Realizado o leilão, a quantia apurada será depositada em conta judicial
remunerada, adotando-se a seguinte disciplina:

[Página 125]

I - nos processos de competência da Justiça Federal e da Justiça do Distrito
Federal:
a) os depósitos serão efetuados na Caixa Econômica Federal ou em
instituição financeira pública, mediante documento adequado para essa
finalidade;
b) os depósitos serão repassados pela Caixa Econômica Federal ou por
outra instituição financeira pública para a Conta Única do Tesouro
Nacional, independentemente de qualquer formalidade, no prazo de 24
(vinte e quatro) horas; e
c) os valores devolvidos pela Caixa Econômica Federal ou por instituição
financeira pública serão debitados à Conta Única do Tesouro Nacional,
em subconta de restituição.
II - nos processos de competência da Justiça dos Estados:
a) os depósitos serão efetuados em instituição financeira designada em lei,
preferencialmente pública, de cada Estado ou, na sua ausência, em
instituição financeira pública da União;
b) os depósitos serão repassados para a conta única de cada Estado, na
forma da respectiva legislação.
§ 5o  Mediante ordem da autoridade judicial, o valor do depósito, após o trânsito
em julgado da sentença proferida na ação penal, será:
I - em caso de sentença condenatória, nos processos de competência da Justiça
Federal e da Justiça do Distrito Federal, incorporado definitivamente ao
patrimônio da União, e, nos processos de competência da Justiça Estadual,
incorporado ao patrimônio do Estado respectivo;
II - em caso de sentença absolutória extintiva de punibilidade, colocado à
disposição do réu pela instituição financeira, acrescido da remuneração da conta
judicial.
§ 6o  A instituição financeira depositária manterá controle dos valores depositados
ou devolvidos.
§ 7o  Serão deduzidos da quantia apurada no leilão todos os tributos e multas
incidentes sobre o bem alienado, sem prejuízo de iniciativas que, no âmbito da
competência de cada ente da Federação, venham a desonerar bens sob constrição
judicial daqueles ônus.
§ 8o  Feito o depósito a que se refere o § 4o deste artigo, os autos da alienação
serão apensados aos do processo principal.

[Página 126]

§ 9o  Terão apenas efeito devolutivo os recursos interpostos contra as decisões
proferidas no curso do procedimento previsto neste artigo.
§ 10.  Sobrevindo o trânsito em julgado de sentença penal condenatória, o juiz
decretará, em favor, conforme o caso, da União ou do Estado:
I - a perda dos valores depositados na conta remunerada e da fiança;
II - a perda dos bens não alienados antecipadamente e daqueles aos quais não foi
dada destinação prévia; e
III - a perda dos bens não reclamados no prazo de 90 (noventa) dias após o trânsito
em julgado da sentença condenatória, ressalvado o direito de lesado ou terceiro
de boa-fé.
§ 11.  Os bens a que se referem os incisos II e III do § 10 deste artigo serão
adjudicados ou levados a leilão, depositando-se o saldo na conta única do
respectivo ente.
§ 12.  O juiz determinará ao registro público competente que emita documento de
habilitação à circulação e utilização dos bens colocados sob o uso e custódia das
entidades a que se refere o caput deste artigo.
§ 13.  Os recursos decorrentes da alienação antecipada de bens, direitos e valores
oriundos do crime de tráfico ilícito de drogas e que tenham sido objeto de
dissimulação e ocultação nos termos desta Lei permanecem submetidos à
disciplina definida em lei específica.
Art. 4o-B.  A ordem de prisão de pessoas ou as medidas assecuratórias de bens,
direitos ou valores poderão ser suspensas pelo juiz, ouvido o Ministério Público,
quando a sua execução imediata puder comprometer as investigações.
Art. 5o  Quando as circunstâncias o aconselharem, o juiz, ouvido o Ministério
Público, nomeará pessoa física ou jurídica qualificada para a administração dos
bens, direitos ou valores sujeitos a medidas assecuratórias, mediante termo de
compromisso.
Art. 6o  A pessoa responsável pela administração dos bens:
I - fará jus a uma remuneração, fixada pelo juiz, que será satisfeita com o produto
dos bens objeto da administração;
II - prestará, por determinação judicial, informações periódicas da situação dos
bens sob sua administração, bem como explicações e detalhamentos sobre
investimentos e reinvestimentos realizados.

[Página 127]

Parágrafo único.  Os atos relativos à administração dos bens sujeitos a medidas
assecuratórias serão levados ao conhecimento do Ministério Público, que
requererá o que entender cabível.
      CAPÍTULO III
Dos Efeitos da Condenação
Art. 7º São efeitos da condenação, além dos previstos no Código Penal:
I - a perda, em favor da União - e dos Estados, nos casos de competência da Justiça
Estadual - de todos os bens, direitos e valores relacionados, direta ou
indiretamente, à prática dos crimes previstos nesta Lei, inclusive aqueles utilizados
para prestar a fiança, ressalvado o direito do lesado ou de terceiro de boa-
fé;
II - a interdição do exercício de cargo ou função pública de qualquer natureza e de
diretor, de membro de conselho de administração ou de gerência das pessoas
jurídicas referidas no art. 9º, pelo dobro do tempo da pena privativa de liberdade
aplicada.
§ 1o  A União e os Estados, no âmbito de suas competências, regulamentarão a
forma de destinação dos bens, direitos e valores cuja perda houver sido declarada,
assegurada, quanto aos processos de competência da Justiça Federal, a sua
utilização pelos órgãos federais encarregados da prevenção, do combate, da ação
penal e do julgamento dos crimes previstos nesta Lei, e, quanto aos processos de
competência da Justiça Estadual, a preferência dos órgãos locais com idêntica
função.
§ 2o  Os instrumentos do crime sem valor econômico cuja perda em favor da União
ou do Estado for decretada serão inutilizados ou doados a museu criminal ou a
entidade pública, se houver interesse na sua conservação.
CAPÍTULO IV
Dos Bens, Direitos ou Valores Oriundos de Crimes Praticados no Estrangeiro
Art. 8o  O juiz determinará, na hipótese de existência de tratado ou convenção
internacional e por solicitação de autoridade estrangeira competente, medidas
assecuratórias sobre bens, direitos ou valores oriundos de crimes descritos no art.
1o praticados no estrangeiro.
§ 1º Aplica-se o disposto neste artigo, independentemente de tratado ou
convenção internacional, quando o governo do país da autoridade solicitante
prometer reciprocidade ao Brasil.
§ 2o  Na falta de tratado ou convenção, os bens, direitos ou valores privados
sujeitos a medidas assecuratórias por solicitação de autoridade estrangeira

[Página 128]

competente ou os recursos provenientes da sua alienação serão repartidos entre o
Estado requerente e o Brasil, na proporção de metade, ressalvado o direito do
lesado ou de terceiro de boa-fé.
CAPÍTULO V
Das Pessoas Sujeitas ao Mecanismo de Controle

Art. 9o  Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e
jurídicas que tenham, em caráter permanente ou eventual, como atividade
principal ou acessória, cumulativamente ou não:
I - a captação, intermediação e aplicação de recursos financeiros de terceiros, em
moeda nacional ou estrangeira;
II – a compra e venda de moeda estrangeira ou ouro como ativo financeiro ou
instrumento cambial;
III - a custódia, emissão, distribuição, liquidação, negociação, intermediação ou
administração de títulos ou valores mobiliários.
Parágrafo único. Sujeitam-se às mesmas obrigações:
I – as bolsas de valores, as bolsas de mercadorias ou futuros e os sistemas de
negociação do mercado de balcão organizado;
II - as seguradoras, as corretoras de seguros e as entidades de previdência
complementar ou de capitalização;
III - as administradoras de cartões de credenciamento ou cartões de crédito, bem
como as administradoras de consórcios para aquisição de bens ou serviços;
IV - as administradoras ou empresas que se utilizem de cartão ou qualquer outro
meio eletrônico, magnético ou equivalente, que permita a transferência de fundos;
V - as empresas de arrendamento mercantil (leasing), as empresas de fomento
comercial (factoring) e as Empresas Simples de Crédito (ESC);
VI - as sociedades que, mediante sorteio, método assemelhado, exploração de
loterias, inclusive de apostas de quota fixa, ou outras sistemáticas de captação de
apostas com pagamento de prêmios, realizem distribuição de dinheiro, de bens
móveis, de bens imóveis e de outras mercadorias ou serviços, bem como concedam
descontos na sua aquisição ou contratação;
VII - as filiais ou representações de entes estrangeiros que exerçam no Brasil
qualquer das atividades listadas neste artigo, ainda que de forma eventual;

[Página 129]

VIII - as demais entidades cujo funcionamento dependa de autorização de órgão
regulador dos mercados financeiro, de câmbio, de capitais e de seguros;
IX - as pessoas físicas ou jurídicas, nacionais ou estrangeiras, que operem no Brasil
como agentes, dirigentes, procuradoras, comissionárias ou por qualquer forma
representem interesses de ente estrangeiro que exerça qualquer das atividades
referidas neste artigo;
X - as pessoas físicas ou jurídicas que exerçam atividades de promoção imobiliária
ou compra e venda de imóveis;
XI - as pessoas físicas ou jurídicas que comercializem jóias, pedras e metais
preciosos, objetos de arte e antiguidades.
XII - as pessoas físicas ou jurídicas que comercializem bens de luxo ou de alto valor,
intermedeiem a sua comercialização ou exerçam atividades que envolvam grande
volume de recursos em espécie;
XIII - as juntas comerciais e os registros públicos;
XIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente,
serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou
assistência, de qualquer natureza, em operações:
a) de compra e venda de imóveis, estabelecimentos comerciais ou industriais ou
participações societárias de qualquer natureza;
b) de gestão de fundos, valores mobiliários ou outros ativos;
c) de abertura ou gestão de contas bancárias, de poupança, investimento ou de
valores mobiliários;
d) de criação, exploração ou gestão de sociedades de qualquer natureza,
fundações, fundos fiduciários ou estruturas análogas;
e) financeiras, societárias ou imobiliárias; e
f) de alienação ou aquisição de direitos sobre contratos relacionados a atividades
desportivas ou artísticas profissionais;
XV - pessoas físicas ou jurídicas que atuem na promoção, intermediação,
comercialização, agenciamento ou negociação de direitos de transferência de
atletas, artistas ou feiras, exposições ou eventos similares;
XVI - as empresas de transporte e guarda de valores;
XVII - as pessoas físicas ou jurídicas que comercializem bens de alto valor de origem
rural ou animal ou intermedeiem a sua comercialização;

[Página 130]

XVIII - as dependências no exterior das entidades mencionadas neste artigo, por
meio de sua matriz no Brasil, relativamente a residentes no País; e
XIX – as prestadoras de serviços de ativos virtuais. (Incluído pela Lei nº 14.478, de
2022)
CAPÍTULO VI
Da Identificação dos Clientes e Manutenção de Registros
Art. 10. As pessoas referidas no art. 9º:
I - identificarão seus clientes e manterão cadastro atualizado, nos termos de
instruções emanadas das autoridades competentes;
II - manterão registro de toda transação em moeda nacional ou estrangeira, títulos
e valores mobiliários, títulos de crédito, metais, ativos virtuais ou qualquer ativo
passível de ser convertido em dinheiro, que ultrapassar limite fixado pela
autoridade competente e nos termos de instruções por esta expedidas; (Redação
dada pela Lei nº 14.478, de 2022)
III - deverão adotar políticas, procedimentos e controles internos, compatíveis com
seu porte e volume de operações, que lhes permitam atender ao disposto neste
artigo e no art. 11, na forma disciplinada pelos órgãos competentes;
IV - deverão cadastrar-se e manter seu cadastro atualizado no órgão regulador ou
fiscalizador e, na falta deste, no Conselho de Controle de Atividades Financeiras
(Coaf), na forma e condições por eles estabelecidas;
V - deverão atender às requisições formuladas pelo Coaf na periodicidade, forma e
condições por ele estabelecidas, cabendo-lhe preservar, nos termos da lei, o sigilo
das informações prestadas.
§ 1º Na hipótese de o cliente constituir-se em pessoa jurídica, a identificação
referida no inciso I deste artigo deverá abranger as pessoas físicas autorizadas a
representá-la, bem como seus proprietários.
§ 2º Os cadastros e registros referidos nos incisos I e II deste artigo deverão ser
conservados durante o período mínimo de cinco anos a partir do encerramento da
conta ou da conclusão da transação, prazo este que poderá ser ampliado pela
autoridade competente.
§ 3º O registro referido no inciso II deste artigo será efetuado também quando a
pessoa física ou jurídica, seus entes ligados, houver realizado, em um mesmo mês-
calendário, operações com uma mesma pessoa, conglomerado ou grupo que, em
seu conjunto, ultrapassem o limite fixado pela autoridade competente.

[Página 131]

Art. 10A. O Banco Central manterá registro centralizado formando o cadastro
geral de correntistas e clientes de instituições financeiras, bem como de seus
procuradores.
CAPÍTULO VII
Da Comunicação de Operações Financeiras
Art. 11. As pessoas referidas no art. 9º:
I - dispensarão especial atenção às operações que, nos termos de instruções
emanadas das autoridades competentes, possam constituir-se em sérios indícios
dos crimes previstos nesta Lei, ou com eles relacionar-se;
II - deverão comunicar ao Coaf, abstendo-se de dar ciência de tal ato a qualquer
pessoa, inclusive àquela à qual se refira a informação, no prazo de 24 (vinte e
quatro) horas, a proposta ou realização:
a) de todas as transações referidas no inciso II do art. 10, acompanhadas da
identificação de que trata o inciso I do mencionado artigo; e
b) das operações referidas no inciso I;
III - deverão comunicar ao órgão regulador ou fiscalizador da sua atividade ou, na
sua falta, ao Coaf, na periodicidade, forma e condições por eles estabelecidas, a
não ocorrência de propostas, transações ou operações passíveis de serem
comunicadas nos termos do inciso II.
§ 1º As autoridades competentes, nas instruções referidas no inciso I deste artigo,
elaborarão relação de operações que, por suas características, no que se refere às
partes envolvidas, valores, forma de realização, instrumentos utilizados, ou pela
falta de fundamento econômico ou legal, possam configurar a hipótese nele
prevista.
§ 2º As comunicações de boa-fé, feitas na forma prevista neste artigo, não
acarretarão responsabilidade civil ou administrativa.
§ 3o  O Coaf disponibilizará as comunicações recebidas com base no inciso II
do caput aos respectivos órgãos responsáveis pela regulação ou fiscalização das
pessoas a que se refere o art. 9o.
Art. 11-A.    As transferências internacionais e os saques em espécie deverão ser
previamente comunicados à instituição financeira, nos termos, limites, prazos e
condições fixados pelo Banco Central do Brasil.
CAPÍTULO VIII
Da Responsabilidade Administrativa

[Página 132]

Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas
jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão
aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes
sanções:
I - advertência;
II - multa pecuniária variável não superior:
a) ao dobro do valor da operação;
b) ao dobro do lucro real obtido ou que presumivelmente seria obtido pela
realização da operação; ou
c) ao valor de R$ 20.000.000,00 (vinte milhões de reais);
III - inabilitação temporária, pelo prazo de até dez anos, para o exercício do cargo
de administrador das pessoas jurídicas referidas no art. 9º;
IV - cassação ou suspensão da autorização para o exercício de atividade, operação
ou funcionamento.
§ 1º A pena de advertência será aplicada por irregularidade no cumprimento das
instruções referidas nos incisos I e II do art. 10.
§ 2o  A multa será aplicada sempre que as pessoas referidas no art. 9o, por culpa ou
dolo:
I – deixarem de sanar as irregularidades objeto de advertência, no prazo assinalado
pela autoridade competente;
II - não cumprirem o disposto nos incisos I a IV do art. 10;
III - deixarem de atender, no prazo estabelecido, a requisição formulada nos termos
do inciso V do art. 10;
IV - descumprirem a vedação ou deixarem de fazer a comunicação a que se refere
o art. 11.
§ 3º A inabilitação temporária será aplicada quando forem verificadas infrações
graves quanto ao cumprimento das obrigações constantes desta Lei ou quando
ocorrer reincidência específica, devidamente caracterizada em transgressões
anteriormente punidas com multa.
§ 4º A cassação da autorização será aplicada nos casos de reincidência específica
de infrações anteriormente punidas com a pena prevista no inciso III
do caput deste artigo.

[Página 133]

Art. 13. (Revogado)
CAPÍTULO IX
Do Conselho de Controle de Atividades Financeiras

Art. 14.  É criado, no âmbito do Ministério da Fazenda, o Conselho de Controle de
Atividades Financeiras - COAF, com a finalidade de disciplinar, aplicar penas
administrativas, receber, examinar e identificar as ocorrências suspeitas de
atividades ilícitas previstas nesta Lei, sem prejuízo da competência de outros
órgãos e entidades.
§ 1º As instruções referidas no art. 10 destinadas às pessoas mencionadas no art.
9º, para as quais não exista órgão próprio fiscalizador ou regulador, serão
expedidas pelo COAF, competindo-lhe, para esses casos, a definição das pessoas
abrangidas e a aplicação das sanções enumeradas no art. 12.
§ 2º O COAF deverá, ainda, coordenar e propor mecanismos de cooperação e de
troca de informações que viabilizem ações rápidas e eficientes no combate à
ocultação ou dissimulação de bens, direitos e valores.
§ 3o O COAF poderá requerer aos órgãos da Administração Pública as informações
cadastrais bancárias e financeiras de pessoas envolvidas em atividades
suspeitas.
Art. 15. O COAF comunicará às autoridades competentes para a instauração dos
procedimentos cabíveis, quando concluir pela existência de crimes previstos nesta
Lei, de fundados indícios de sua prática, ou de qualquer outro ilícito.
Art. 16 (Revogado)
§ 2o  Caberá recurso das decisões do COAF relativas às aplicações de penas
administrativas ao Conselho de Recursos do Sistema Financeiro Nacional.

CAPÍTULO X
Disposições Gerais
Art. 17-A.  Aplicam-se, subsidiariamente, as disposições do Decreto-Lei nº 3.689,
de 3 de outubro de 1941 (Código de Processo Penal), no que não forem
incompatíveis com esta Lei.
Art. 17-B.  A autoridade policial e o Ministério Público terão acesso,
exclusivamente, aos dados cadastrais do investigado que informam qualificação
pessoal, filiação e endereço, independentemente de autorização judicial, mantidos
pela Justiça Eleitoral, pelas empresas telefônicas, pelas instituições financeiras,
pelos provedores de internet e pelas administradoras de cartão de crédito.

[Página 134]

Art. 17-C.  Os encaminhamentos das instituições financeiras e tributárias em
resposta às ordens judiciais de quebra ou transferência de sigilo deverão ser,
sempre que determinado, em meio informático, e apresentados em arquivos que
possibilitem a migração de informações para os autos do processo sem
redigitação.
Art. 17-D.  Em caso de indiciamento de servidor público, este será afastado, sem
prejuízo de remuneração e demais direitos previstos em lei, até que o juiz
competente autorize, em decisão fundamentada, o seu retorno.
Art. 17-E.  A Secretaria da Receita Federal do Brasil conservará os dados fiscais dos
contribuintes pelo prazo mínimo de 5 (cinco) anos, contado a partir do início do
exercício seguinte ao da declaração de renda respectiva ou ao do pagamento do
tributo.

Lei nº 13.260, de 16 de março de 2016.
Regulamenta o disposto no inciso XLIII do art. 5º da Constituição Federal,
disciplinando o terrorismo, tratando de disposições investigatórias e processuais
e reformulando o conceito de organização terrorista; e altera as Leis n º 7.960,
de 21 de dezembro de 1989, e 12.850, de 2 de agosto de 2013.
Art. 1º  Esta Lei regulamenta o disposto no inciso XLIII do art. 5º da Constituição
Federal , disciplinando o terrorismo, tratando de disposições investigatórias e
processuais e reformulando o conceito de organização terrorista.
Art. 2º O terrorismo consiste na prática por um ou mais indivíduos dos atos
previstos neste artigo, por razões de xenofobia, discriminação ou preconceito de
raça, cor, etnia e religião, quando cometidos com a finalidade de provocar terror
social ou generalizado, expondo a perigo pessoa, patrimônio, a paz pública ou a
incolumidade pública.
§ 1º São atos de terrorismo:
I - usar ou ameaçar usar, transportar, guardar, portar ou trazer consigo explosivos,
gases tóxicos, venenos, conteúdos biológicos, químicos, nucleares ou outros meios
capazes de causar danos ou promover destruição em massa;
II – (VETADO);
III - (VETADO);
IV - sabotar o funcionamento ou apoderar-se, com violência, grave ameaça a
pessoa ou servindo-se de mecanismos cibernéticos, do controle total ou parcial,

[Página 135]

ainda que de modo temporário, de meio de comunicação ou de transporte, de
portos, aeroportos, estações ferroviárias ou rodoviárias, hospitais, casas de saúde,
escolas, estádios esportivos, instalações públicas ou locais onde funcionem
serviços públicos essenciais, instalações de geração ou transmissão de energia,
instalações militares, instalações de exploração, refino e processamento de
petróleo e gás e instituições bancárias e sua rede de atendimento;
V - atentar contra a vida ou a integridade física de pessoa:
Pena - reclusão, de doze a trinta anos, além das sanções correspondentes à ameaça
ou à violência.
§ 2º O disposto neste artigo não se aplica à conduta individual ou coletiva de
pessoas em manifestações políticas, movimentos sociais, sindicais, religiosos, de
classe ou de categoria profissional, direcionados por propósitos sociais ou
reivindicatórios, visando a contestar, criticar, protestar ou apoiar, com o objetivo
de defender direitos, garantias e liberdades constitucionais, sem prejuízo da
tipificação penal contida em lei.
Art. 3º  Promover, constituir, integrar ou prestar auxílio, pessoalmente ou por
interposta pessoa, a organização terrorista:
Pena - reclusão, de cinco a oito anos, e multa.
Art. 4º (VETADO).
Art. 5º Realizar atos preparatórios de terrorismo com o propósito inequívoco de
consumar tal delito:
Pena - a correspondente ao delito consumado, diminuída de um quarto até a
metade.
§ 1º Incorre nas mesmas penas o agente que, com o propósito de praticar atos de
terrorismo:
I - recrutar, organizar, transportar ou municiar indivíduos que viajem para país
distinto daquele de sua residência ou nacionalidade; ou
II - fornecer ou receber treinamento em país distinto daquele de sua residência ou
nacionalidade.
§ 2º Nas hipóteses do § 1º, quando a conduta não envolver treinamento ou viagem
para país distinto daquele de sua residência ou nacionalidade, a pena será a
correspondente ao delito consumado, diminuída de metade a dois terços.

[Página 136]

Art. 6º Receber, prover, oferecer, obter, guardar, manter em depósito, solicitar,
investir, de qualquer modo, direta ou indiretamente, recursos, ativos, bens,
direitos, valores ou serviços de qualquer natureza, para o planejamento, a
preparação ou a execução dos crimes previstos nesta Lei:
Pena - reclusão, de quinze a trinta anos.
Parágrafo único. Incorre na mesma pena quem oferecer ou receber, obtiver,
guardar, mantiver em depósito, solicitar, investir ou de qualquer modo contribuir
para a obtenção de ativo, bem ou recurso financeiro, com a finalidade de financiar,
total ou parcialmente, pessoa, grupo de pessoas, associação, entidade,
organização criminosa que tenha como atividade principal ou secundária, mesmo
em caráter eventual, a prática dos crimes previstos nesta Lei.
Art. 7º Salvo quando for elementar da prática de qualquer crime previsto nesta Lei,
se de algum deles resultar lesão corporal grave, aumenta-se a pena de um terço,
se resultar morte, aumenta-se a pena da metade.
Art. 8º (VETADO).
Art. 9º (VETADO).
Art. 10. Mesmo antes de iniciada a execução do crime de terrorismo, na hipótese
do art. 5º desta Lei, aplicam-se as disposições do art. 15 do Decreto-Lei nº 2.848,
de 7 de dezembro de 1940 - Código Penal .
Art. 11. Para todos os efeitos legais, considera-se que os crimes previstos nesta Lei
são praticados contra o interesse da União, cabendo à Polícia Federal a
investigação criminal, em sede de inquérito policial, e à Justiça Federal o seu
processamento e julgamento, nos termos do inciso IV do art. 109 da Constituição
Federal .
Parágrafo único. (VETADO).
Art. 12. O juiz, de ofício, a requerimento do Ministério Público ou mediante
representação do delegado de polícia, ouvido o Ministério Público em vinte e
quatro horas, havendo indícios suficientes de crime previsto nesta Lei, poderá
decretar, no curso da investigação ou da ação penal, medidas assecuratórias de
bens, direitos ou valores do investigado ou acusado, ou existentes em nome de
interpostas pessoas, que sejam instrumento, produto ou proveito dos crimes
previstos nesta Lei.
§ 1º Proceder-se-á à alienação antecipada para preservação do valor dos bens
sempre que estiverem sujeitos a qualquer grau de deterioração ou depreciação, ou
quando houver dificuldade para sua manutenção.

[Página 137]

§ 2º O juiz determinará a liberação, total ou parcial, dos bens, direitos e valores
quando comprovada a licitude de sua origem e destinação, mantendo-se a
constrição dos bens, direitos e valores necessários e suficientes à reparação dos
danos e ao pagamento de prestações pecuniárias, multas e custas decorrentes da
infração penal.
§ 3º Nenhum pedido de liberação será conhecido sem o comparecimento pessoal
do acusado ou de interposta pessoa a que se refere o caput deste artigo, podendo
o juiz determinar a prática de atos necessários à conservação de bens, direitos ou
valores, sem prejuízo do disposto no § 1º.
§ 4º Poderão ser decretadas medidas assecuratórias sobre bens, direitos ou valores
para reparação do dano decorrente da infração penal antecedente ou da prevista
nesta Lei ou para pagamento de prestação pecuniária, multa e custas.
Art. 13. Quando as circunstâncias o aconselharem, o juiz, ouvido o Ministério
Público, nomeará pessoa física ou jurídica qualificada para a administração dos
bens, direitos ou valores sujeitos a medidas assecuratórias, mediante termo de
compromisso.
Art. 14. A pessoa responsável pela administração dos bens:
I - fará jus a uma remuneração, fixada pelo juiz, que será satisfeita
preferencialmente com o produto dos bens objeto da administração;
II - prestará, por determinação judicial, informações periódicas da situação dos
bens sob sua administração, bem como explicações e detalhamentos sobre
investimentos e reinvestimentos realizados.
Parágrafo único. Os atos relativos à administração dos bens serão levados ao
conhecimento do Ministério Público, que requererá o que entender cabível.
Art. 15. O juiz determinará, na hipótese de existência de tratado ou convenção
internacional e por solicitação de autoridade estrangeira competente, medidas
assecuratórias sobre bens, direitos ou valores oriundos de crimes descritos nesta
Lei praticados no estrangeiro.
§ 1º Aplica-se o disposto neste artigo, independentemente de tratado ou
convenção internacional, quando houver reciprocidade do governo do país da
autoridade solicitante.
§ 2º Na falta de tratado ou convenção, os bens, direitos ou valores sujeitos a
medidas assecuratórias por solicitação de autoridade estrangeira competente ou
os recursos provenientes da sua alienação serão repartidos entre o Estado

[Página 138]

requerente e o Brasil, na proporção de metade, ressalvado o direito do lesado ou
de terceiro de boa-fé.
Art. 16. Aplicam-se as disposições da Lei nº 12.850, de 2 agosto de 2013, para a
investigação, processo e julgamento dos crimes previstos nesta Lei.
Art. 17. Aplicam-se as disposições da Lei nº 8.072, de 25 de julho de 1990, aos
crimes previstos nesta Lei.
Art. 18. O inciso III do art. 1º da Lei nº 7.960, de 21 de dezembro de 1989, passa a
vigorar acrescido da seguinte alínea ‘p’:
“Art. lº ......................................................................
III - .............................................................................
p) crimes previstos na Lei de Terrorismo.”
Art. 19. O art. 1º da Lei nº 12.850, de 2 de agosto de 2013, passa a vigorar com a
seguinte alteração:
“Art. 1º .......................................................................
§ 2º .............................................................................
II - às organizações terroristas, entendidas como aquelas voltadas para a
prática dos atos de terrorismo legalmente definidos.”$mat$, 'junho/2026'),
(2, 3, $mat$Conceitos de PLD/FTP: fases da lavagem, GAFI, Egmont, COAF, ENCCLA, pilares$mat$, $mat$Os conceitos e definições relacionados à PLD/FTP

A prevenção à lavagem de dinheiro

As instituições financeiras, inclusive as autorizadas a operar em câmbio,
devem estar permanentemente atentas para evitar que o SFN dê sustentação
ao curso de operações ilícitas, envolvendo recursos de origem duvidosa.

É sabido que os sistemas financeiros de maneira geral, pela sua
capacidade de viabilizar de forma ágil a liquidação financeira de transações de
quaisquer naturezas, são alvo natural das organizações criminosas na tentativa
de movimentar e registrar recursos provenientes de crime, dando suporte
financeiro às suas atividades.

[Página 139]

Um dos grandes desafios atuais da comunidade financeira internacional é,
sem dúvida, continuar no caminho da modernidade e do incremento do processo
de globalização e integração econômica sem, contudo, permitir o uso
proliferado dos sistemas financeiros para dar suporte a essas operações ilícitas.

O Brasil tem se engajado fortemente nesse esforço, tendo como
resultados práticos a tipificação do crime de lavagem de dinheiro na legislação
brasileira, por meio da Lei nº 9.613, de 3 março de 1998, com as alterações
promovidas pelas Leis nºs 10.701, de 9 de julho de 2003, e 12.683, de 9 de julho
de 2012. Com a edição da Lei nº 9.613, foi criado também o Conselho de
Controle de Atividades Financeiras (COAF) no âmbito do Ministério da Fazenda.
O COAF é o órgão de inteligência financeira, que atua eminentemente na
prevenção à lavagem de dinheiro e ao financiamento do terrorismo e da
proliferação de armas de destruição em massa (PLD/FTP).

Prevê a referida Lei, ainda, sanções administrativas e penais, caso não
atendidas as responsabilidades definidas. O Sistema Financeiro Nacional, e os
procedimentos ligados ao mercado de câmbio em particular, estão inseridos
nesse contexto, no âmbito da regulamentação e supervisão do Banco Central do
Brasil.

Definição de Lavagem de Dinheiro

Não há na doutrina um conceito padrão sobre lavagem de dinheiro, mas
todas as definições convergem no sentido de ser uma prática que busca dar
aparência lícita a recursos obtidos de forma ilícita. Várias definições se aplicam
ao crime de lavagem de dinheiro, tanto do ponto de vista doutrinário e legal
quanto do ponto de vista conceitual.
De acordo com definição contida na página do COAF na internet, “o crime
de lavagem de dinheiro caracteriza-se por um conjunto de operações
comerciais ou financeiras que buscam a incorporação na economia de cada
país, de modo transitório ou permanente, de recursos, bens e valores de
origem ilícita e que se desenvolvem por meio de um processo dinâmico que
envolve, teoricamente, três fases independentes que, com frequência,
ocorrem simultaneamente” ou, em síntese, “dissimular a origem do dinheiro,
por meio de ações diversas, buscando atribuir aparência lícita a valores ou
bens obtidos de forma ilícita”.
As fases da lavagem de dinheiro são: i) colocação, que objetiva
introduzir o dinheiro na economia, buscando ocultar a origem de recursos
ilícitos. Normalmente, o criminoso busca movimentá-los em países com regras
mais permissivas e naqueles que possuem sistema financeiro liberal; ii)
ocultação/dissimulação/estratificação,
cujo
processo
consiste
na

[Página 140]

estruturação de operações complexas que buscam dificultar o rastreamento
contábil dos recursos ilícitos, dificultando investigações; e iii) integração, onde
os ativos são incorporados formalmente ao sistema econômico, retornando os
recursos já com aparência lícita.
Essas fases são distintas e independentes, e não necessariamente devem
ocorrer simultânea ou sucessivamente, contudo estudos indicam que a fase mais
vulnerável, geralmente é a de colocação, pois nela os criminosos pretendem
fazer desaparecer as grandes somas que suas atividades ilegais geraram,
separando os ativos da ilegalidade. Durante a colocação os delinquentes estão
mais vulneráveis, e as autoridades estão focadas nesse movimento financeiro
inicial, quando muito dinheiro é convertido, facilitando a descoberta. Nesta
primeira instância os principais canais de colocação são as instituições
financeiras, buscando a inserção nos movimentos financeiros diários e outras
atividades que transferirão o dinheiro além das fronteiras nacionais.

As instituições financeiras tradicionais bancos, corretoras, empresas de
crédito, etc, representam o caminho natural e mais conhecido para
transferência de dinheiro e, por esse motivo, são as mais fiscalizadas pelo Banco
Central. Uma vez que as próprias instituições temem ser um instrumento de
lavadores, elas passaram a adotar medidas de controle interno e de compliance
a fim de prevenir essas ocorrências, até pelo risco de uma vez deflagrada alguma
investigação dos órgãos de controle, perderem credibilidade no mercado e
sofrerem pesadas sanções.

Do ponto de vista legal, cada país tem autonomia para definir a tipificação
legal desses crimes.

Um país cuja legislação tipifica como crime antecedente ao de lavagem
de dinheiro apenas o tráfico de drogas e entorpecentes é considerado com
legislação de primeira geração.

Já o país cuja legislação tipifica como crime antecedente ao de lavagem
de dinheiro, além do tráfico de drogas e entorpecentes, um rol limitado e
taxativo de infrações penais de relevância significativa, é considerado com
legislação de segunda geração.

Por sua vez, um país cuja legislação tipifica como crime antecedente ao
de lavagem de dinheiro um amplo rol de crimes graves é considerado com
legislação de terceira geração.

No Brasil, o crime de lavagem de dinheiro foi definido pela Lei 9.613, de
1998, como a ocultação ou dissimulação da natureza, da origem, da localização,
da disposição, da movimentação ou da propriedade de bens, direitos ou valores

[Página 141]

provenientes, direta ou indiretamente, de infração penal. Esta redação foi dada
pela Lei nº 12.683, de 2012, que ampliou o alcance da tipificação de crime de
lavagem de dinheiro, antes ligada a um crime antecedente especificamente
definido na Lei n 9.613, sendo agora derivado de uma infração penal considerada
de forma genérica.

Essa ampliação do alcance permitiu o enquadramento da nossa
legislação como de terceira geração. Segundo essa legislação, incorre, ainda, na
pena aplicável a lavagem de dinheiro quem utiliza, na atividade econômica ou
financeira, bens, direitos ou valores provenientes de infração penal ou participa
de grupo, associação ou escritório tendo conhecimento de que sua atividade
principal ou secundária é dirigida à prática de crimes previstos na legislação.

O crime de lavagem é um crime derivado, portanto, sempre há um crime
antecedente previsto na legislação própria. No Brasil, a competência para
legislar sobre os crimes de lavagem de dinheiro é da União.

Assim temos a Lei 9.613/98, como de segunda geração: Pois somente
caracteriza a lavagem de dinheiro se a ocultação ou dissimulação seja de bens, direitos
ou valores provenientes de um crime antecedente.

Já a Lei 12.683/12, é considerada de terceira geração: Pois ampliou o alcance
anterior, uma vez que poderá haver lavagem de dinheiro se a ocultação ou dissimulação
for de bens, direitos ou valores provenientes de um crime, ou de uma contravenção
penal. Ou seja, a lavagem de dinheiro continua a sendo um crime derivado, mas a
infração penal antecedente pode ser relativa a crime ou contravenção penal,
considerada de forma genérica.

Governança no âmbito Internacional

O GAFI/FATF – Grupo de Ação Financeira contra a Lavagem de Dinheiro
e o Financiamento do Terrorismo - Financial Action Task Force é o fórum mais
importante em nível internacional na prevenção e combate à lavagem de
dinheiro e ao financiamento do terrorismo.

Conforme definição do COAF, o GAFI/FATF é uma organização
intergovernamental cujo propósito é desenvolver e promover políticas e
estratégias, nacionais e internacionais, de combate à lavagem de dinheiro e ao
financiamento do terrorismo. Criado em 1989, por decisão dos países-membros
do G7, o GAFI/FATF é um organismo elaborador de políticas que atua visando a
gerar a vontade política necessária para realizar reformas legislativas e
regulatórias nessas áreas.

[Página 142]

O GAFI/FATF é reconhecido pelos diversos órgãos e organismos
internacionais (FMI, Banco Mundial, BIS etc.) como capaz de estabelecer
medidas padronizadas e efetivas para a prevenção e combate à lavagem de
dinheiro e ao financiamento do terrorismo no mundo. Periodicamente, o GAFI
realiza avaliação dos países membros acerca da implementação de medidas de
prevenção e combate à lavagem de dinheiro, ao financiamento do terrorismo e
a proliferação de armas de destruição em massa.

 Outro organismo internacional pertencente ao sistema de combate à
lavagem de dinheiro e ao financiamento do terrorismo é o Grupo de Egmont,
conjunto de 164 unidades de inteligência financeira unidas em uma plataforma
segura para troca de informações com o objetivo de combater esses crimes. A
unidade de inteligência financeira (UIF) brasileira é o COAF, órgão central
nacional responsável por receber, analisar e disseminar às autoridades
competentes informações sobre operações financeiras não usuais que podem
representar indícios de ilícitos. O Grupo de Egmont reconhece diversos modelos
de atuação para as UIF, como os modelos administrativo, judicial, de persecução
penal ou misto.

 As Recomendações do GAFI

O GAFI divulgou, em 1990, o documento denominado “40
Recomendações”, que relacionava as melhoras práticas a serem adotadas pelos
países com o propósito de combater a lavagem de dinheiro e promover a
necessária cooperação internacional. A partir de 2001, foram acrescidas nove
recomendações, incluindo à prevenção ao financiamento ao terrorismo. As
recomendações do GAFI são reconhecidas e adotadas por mais de 180 países.

As 40 Recomendações do GAFI constituem-se como um guia para que os
países adotem padrões e promovam a efetiva adoção de medidas legais,
regulatórias e operacionais para combater a lavagem de dinheiro, ao
financiamento do terrorismo e o financiamento da proliferação de armas
nucleares, além de outras ameaças à integridade do sistema financeiro
relacionadas a esses crimes e de outros setores organizados da economia.

Essas Recomendações são a base para que todos os países atinjam o
objetivo comum de atacar a lavagem de dinheiro, o financiamento do terrorismo
e o financiamento da proliferação de armas de destruição em massa, e
constituem-se como um guia para que os países adotem em seus sistemas
regulatórios e de justiça criminal, as medidas para garantir maior transparência
e informações com relação à titularidade de pessoas jurídicas e outras
estruturas, o estabelecimento de autoridades competentes com funções
apropriadas, poderes e mecanismos de cooperação e acordos de cooperação
com outros países.

[Página 143]

As recomendações do GAFI sustentam a formulação, pelo Banco Central,
de políticas ligadas à prevenção a lavagem de dinheiro no âmbito do SFN.
Segundo elas, os países devem adotar medidas essenciais para que haja
aumento dos poderes e das responsabilidades das autoridades responsáveis pela
prevenção à lavagem de dinheiro. Organizações mundiais como o BIS, o FMI e o
Banco Mundial, reconhecem as recomendações do GAFI como padrões
internacionais de combate à lavagem de dinheiro e do financiamento do
terrorismo.

O GAFI monitora os países em relação às suas políticas e atuação na
prevenção à lavagem de dinheiro e do financiamento ao terrorismo através de
avaliações mútuas feitas por representantes dos países-membros.

As instituições financeiras, assim como outros setores organizados da
economia, têm a obrigação de identificar seus clientes e manter cadastro
atualizado, e registro de toda a transação em moeda nacional ou estrangeira,
além de outras operações. Deverão, também, adotar políticas, procedimentos e
controles internos, compatíveis com seu porte e volume de operações,
dispensando especial atenção às operações que, nos termos das instruções
emanadas autoridades competentes, possam constituir-se em sérios indícios dos
crimes previstos na Lei nº 9.613, ou com eles relacionar-se.

Devem, também, comunicar ao COAF, abstendo-se de dar ciência de tal
ato a qualquer pessoa, inclusive àquela à qual se refira a informação, até o dia
útil seguinte após a decisão de comunicação, a proposta ou realização de todas
as transações atípicas ou suspeitas.

O princípio “conheça seu cliente” constitui em importante mitigador de
risco. Esse princípio, se devidamente aplicado, tem a capacidade de oferecer à
instituição elementos bastantes que permitem a identificação das situações que
apresentem atipicidade e suspeição, dando suporte às comunicações ao COAF.

Governança no âmbito nacional

COAF – Conselho de Controle de Atividades Financeiras

O COAF, criado pela Lei nº 9.613 de 03 de março de 1998, passou a
constituir, desde então, a unidade de inteligência financeira do Brasil, com as
seguintes competências:

i) Receber, examinar e identificar as ocorrências suspeitas de atividades

[Página 144]

ilícitas previstas na referida lei;

ii) Comunicar às autoridades competentes para a instauração dos
procedimentos cabíveis nas situações em que o Conselho concluir pela
existência, ou fundados indícios, de crimes de lavagem, ocultação de bens,
direitos e valores, ou de qualquer outro ilícito;

iii) Coordenar e propor mecanismos de cooperação e de troca de
informações que viabilizem ações rápidas e eficientes no combate à ocultação
ou dissimulação de bens, direitos e valores;

iv) Disciplinar e aplicar penas administrativas aos setores não regulados
por Órgão próprio, por não tratamento adequado às ocorrências suspeitas de
atividades ilícitas previstas na Lei.

Ao lado da tipificação do crime, a Lei nº 9.613 estabeleceu um regime
administrativo que consiste em uma série de deveres de vigilância e
comunicação ao COAF de operações suspeitas e atípicas para os diversos setores
da economia, e de obrigações para suas respectivas autoridades supervisoras.

O COAF tem competência atribuída por Lei para requerer aos Órgãos da
administração Pública as informações cadastrais bancárias e financeiras de
pessoas envolvidas em atividades suspeitas.

A Lei nº 9.613 também atribuiu ao COAF a competência residual de
regular os setores econômicos para os quais não haja órgão regulador ou
fiscalizador próprio. Nesses casos, cabe ao Conselho definir as pessoas
abrangidas e os meios e critérios para envio de comunicações, bem como a
expedição das instruções para a identificação de clientes e manutenção de
registros de transações, além da aplicação de sanções previstas na referida Lei.

  O COAF é composto por uma parte executiva, integrada pela Presidência,
Secretaria-Executiva, duas Diretorias e quadro técnico, e por um Plenário,
composto por conselheiros que representam vários órgãos governamentais.

[Página 145]

