[Página 150]

  Os Pilares de sustentação da PLD/FTP

Os pilares de sustentação da prevenção à lavagem de dinheiro, ao
financiamento do terrorismo e à proliferação de armas de destruição em massa
podem ser assim considerados:

▪ Avaliação de Riscos e Abordagem com Base no Risco (ABR):

As instituições devem identificar, avaliar e compreender os riscos de
lavagem de dinheiro e financiamento do terrorismo, tomar medidas e
aplicar recursos com o objetivo de garantir que os riscos sejam

[Página 151]

efetivamente mitigados. Com base nessa avaliação, devem aplicar uma
abordagem baseada no risco (ABR) para garantir que as medidas de
prevenção ou mitigação da lavagem de dinheiro e do financiamento do
terrorismo sejam proporcionais aos riscos identificados. Essa abordagem
deve ser um fator essencial para a alocação eficiente de recursos e para
a implementação das medidas baseadas em risco.

A ABR requer o exame de dados e informações de diversas naturezas.

Nesse sentido, pode constituir fatores de risco de lavagem de dinheiro:

i.
a característica do cliente e seu perfil de negócio;

ii.
a ausência de beneficiário final;

iii.
países contrapartes, área geográfica e produtos negociados;

iv.
operações em sequência, quase que diária, sem justificativa
clara;

v.
forma de acesso do cliente à instituição financeira;

vi.
oferecimento de informações incompletas pelo cliente, que não
demonstra capacidade ou interesse em atender integralmente
ao requerido pela instituição financeira.

▪ Devida Diligência sobre o Cliente (DDC):

As medidas de DDC recomendadas pelo GAFI são as seguintes:

(a) identificar o cliente e verificar sua identidade por meio de
documentos, informações ou dados confiáveis e de fontes independentes.

(b) identificar o beneficiário e adotar medidas razoáveis para verificar a
identidade de tal beneficiário, de forma que a instituição financeira
obtenha conhecimento satisfatório sobre quem é o beneficiário. Para
pessoas jurídicas e outras estruturas jurídicas, as instituições financeiras
devem também compreender a propriedade e a estrutura de controle do
cliente.

(c) Compreender e, quando apropriado, obter informações a respeito do
propósito e da natureza pretendidos da relação de negócios.

[Página 152]

(d) Conduzir uma devida diligência contínua na relação de negócios e uma
análise minuciosa das transações conduzidas durante a relação para
garantir que tais transações sejam consistentes com o conhecimento da
instituição sobre o cliente, seus negócios e perfil de risco, incluindo,
quando necessário, a origem dos recursos. As instituições devem aplicar
cada uma das medidas de DDC listadas, determinando até que ponto tais
medidas usam uma abordagem baseada no risco (ABR).

Devem também verificar a identidade do cliente e do beneficiário antes
ou durante o estabelecimento de uma relação de negócios ou na
realização de transações para clientes ocasionais. Portanto, o processo
de Devida Diligência sobre o Cliente busca:

i) conhecer adequadamente o cliente e o seu perfil do seu negócio;

ii) manter cadastro atualizado e registro das informações;

iii) identificar o beneficiário final das operações; e

iv) conferir especial atenção sobre pessoas agindo em nome de clientes,
sobre as entidades sem personalidade jurídica, e sobre as entidades sem
fins lucrativos.

▪ Fundamentação Econômica das Operações:

A fundamentação econômica que justifica a realização da operação de
câmbio e que deverá ser indicada na descrição da natureza do fato.

▪ Comunicações ao COAF, com qualidade:

Se a instituição financeira tiver motivos razoáveis para suspeitar que os
fundos sejam produtos de atividade criminosa ou estejam relacionados
ao financiamento do terrorismo, ela está obrigada a comunicar
prontamente suas suspeitas ao COAF, essa comunicação precisa conter
os elementos necessários ao processo de investigação.
Ainda em relação às comunicações de operações atípicas ou suspeitas
ao COAF, é importante destacar que:

▪ Tais comunicações não caracterizadas como denúncias.

▪ As
comunicações
de
boa-fé
não
acarretam

[Página 153]

responsabilidades civil e administrativa.

▪ As comunicações geram informações que podem fazer parte
de RIF’s - Relatórios de Informações Financeiras, elaborados pelo
Coaf.

▪ A instituição financeira deve abster-se de dar ciência de tal
ato a qualquer pessoa, inclusive àquela à qual se refira a informação.

• As propostas de negócios não realizados também devem ser
comunicadas, caso apresentem indícios de atipicidade ou
suspeição.

▪ Auditoria e Controles Internos Adequados:

A auditoria e os controles internos da instituição precisam prever em seu
escopo de trabalho a verificação da efetividade dos manuais, práticas e
controles relativos à PLD/FTP e avaliar se os apontamentos
eventualmente realizados estão sendo regularizados.

 Terrorismo

Não há em nível internacional um conceito padrão definindo do que é
terrorismo, ficando na dependência da legislação de cada país, o que de certo
modo dificulta a celebração de acordo e convênios entre as nações.

Pode se classificar o terrorismo como modo de impor vontades pelo uso
sistemático do terror ou emprego sistemático da violência para fins políticos
e/ou religiosos.

Já o financiamento ao terrorismo é qualquer forma de ação de assistência
econômica ou apoio financeiro às atividades de pessoas ou grupos terroristas.

A luta contra o financiamento do terrorismo está intimamente ligada com
o combate à lavagem de dinheiro.

Logo após os atentados de setembro de 2001 nos EUA, as nações se
mobilizaram para intensificar a luta contra o terrorismo, com a inclusão do tema
entre aqueles tratados pelo GAFI.

[Página 154]

Assim, em 28 de setembro daquele mesmo ano o Conselho de Segurança
das Nações Unidas (CSNU) adotou resolução para impedir o financiamento do
terrorismo, criminalizar a coleta de fundos para este fim e congelar
imediatamente os bens financeiros dos terroristas.

As instituições financeiras, se não tiverem políticas adequadas de
controles internos, podem se envolver em transações relacionadas a esses
crimes, assumindo praticamente os mesmos riscos inerentes à prática de
lavagem de dinheiro.

Assim, os mesmos sinais de alerta utilizados pelas instituições financeiras
na prevenção à lavagem de dinheiro devem ser aplicados na prevenção ao
financiamento do terrorismo, embora haja entre diferenças entre as duas
situações, conforme a seguir demonstrado:

Diferenças entre lavagem de dinheiro e financiamento ao terrorismo

▪
Ambos são crimes transnacionais.

▪
Ambos fazem uso de métodos similares para sua realização.

 A ENCCLA (Estratégia Nacional de Combate à Corrupção e à Lavagem
de Dinheiro)

Instituída em 2003, sob a coordenação do Ministério da Justiça e
Segurança Pública, a Estratégia Nacional de Combate à Corrupção e à Lavagem
de Dinheiro (ENCCLA) é formada por mais de 60 órgãos, dos três poderes da
República, Ministérios Públicos e da sociedade civil que atuam, direta ou
indiretamente, na prevenção e combate à corrupção e à lavagem de dinheiro. A

[Página 155]

Estratégia intensifica a prevenção a esses crimes porque soma a expertise de
diversos parceiros em prol do Estado brasileiro.

A partir de 2023, a ABRACAM foi convidada a contribuir com o
desenvolvimento de uma das ações da Enccla, participando também da reunião
plenária que estabeleceu o planejamento de suas ações para 2024.

Anualmente, os órgãos participantes reúnem-se em plenária para, a partir
de consenso, traçar as ações que serão executadas no ano seguinte. Os órgãos
são divididos em grupos de trabalho que coordenam, ao longo do ano, a execução
de cada uma das ações elegidas.

O Departamento de Recuperação de Ativos e Cooperação Jurídica
Internacional (DRCI/SNJ) tem por competência articular a implementação da
ENCCLA e a Secretaria Nacional de Justiça e Cidadania coordena a Estratégia,
em parceria com os demais órgãos que a compõem.

Ao longo desses anos, os trabalhos desenvolvidos pela Estratégia
trouxeram diversos resultados positivos no combate ao crime de lavagem de
dinheiro e às práticas de corrupção.

Destacam-se, dentre os resultados alcançados pela ENCCLA, o Programa
Nacional de Capacitação e Treinamento no Combate à Corrupção e à Lavagem
de Dinheiro (PNLD); a Rede Nacional de Laboratórios contra Lavagem de
Dinheiro (Rede-LAB); o Sistema de Movimentação Bancária (SIMBA); a iniciativa
de padronização do layout para quebra de sigilo bancário e a posterior criação
do Cadastro Único de Correntistas do Sistema Financeiro Nacional (CCS); a
proposição legislativa que resultou na promulgação de leis importantes para o
país, tais como a Lei 12.683/12, que modernizou a nossa Lei de Lavagem de
Dinheiro.

