(2, 4, $mat$Circular BCB 3.978/2020: política, procedimentos e controles de PLD/FT$mat$, $mat$As normas de PLD/FTP do Banco Central do Brasil

Circular nº 3.978, de 23 de janeiro de 2020

CAPÍTULO I
DO OBJETO E DO ÂMBITO DE APLICAÇÃO

Art. 1º Esta Circular dispõe sobre a política, os procedimentos e os controles
internos a serem adotados pelas instituições autorizadas a funcionar pelo Banco
Central do Brasil visando à prevenção da utilização do sistema financeiro para a
prática dos crimes de “lavagem” ou ocultação de bens, direitos e valores, de que
trata a Lei nº 9.613, de 3 de março de 1998, e de financiamento do terrorismo,
previsto na Lei nº 13.260, de 16 de março de 2016.

Parágrafo único. Para os fins desta Circular, os crimes referidos no caput serão
denominados genericamente “lavagem de dinheiro” e “financiamento do
terrorismo”.

CAPÍTULO II
DA POLÍTICA DE PREVENÇÃO À LAVAGEM DE DINHEIRO E AO
FINANCIAMENTO DO TERRORISMO

Art. 2º As instituições mencionadas no art. 1º devem implementar e manter
política formulada com base em princípios e diretrizes que busquem prevenir a sua
utilização para as práticas de lavagem de dinheiro e de financiamento do
terrorismo.

Parágrafo único. A política de que trata o caput deve ser compatível com os perfis
de risco:

I - dos clientes;

II - da instituição;

III - das operações, transações, produtos e serviços; e

IV - dos funcionários, parceiros e prestadores de serviços terceirizados.

Art. 3º A política referida no art. 2º deve contemplar, no mínimo:

I - as diretrizes para:
a) a definição de papéis e responsabilidades para o cumprimento das obrigações de
que trata esta Circular;

[Página 157]

b) a definição de procedimentos voltados à avaliação e à análise prévia de novos
produtos e serviços, bem como da utilização de novas tecnologias, tendo em vista
o risco de lavagem de dinheiro e de financiamento do terrorismo;
c) a avaliação interna de risco e a avaliação de efetividade de que tratam os arts.
10 e 62;
d) a verificação do cumprimento da política, dos procedimentos e dos controles
internos de que trata esta Circular, bem como a identificação e a correção das
deficiências verificadas;
e) a promoção de cultura organizacional de prevenção à lavagem de dinheiro e ao
financiamento do terrorismo, contemplando, inclusive, os funcionários, os
parceiros e os prestadores de serviços terceirizados;
f) a seleção e a contratação de funcionários e de prestadores de serviços
terceirizados, tendo em vista o risco de lavagem de dinheiro e de financiamento do
terrorismo; e
g) a capacitação dos funcionários sobre o tema da prevenção à lavagem de dinheiro
e ao financiamento do terrorismo, incluindo os funcionários dos correspondentes
no País que prestem atendimento em nome das instituições mencionadas no art.
1º;

II - as diretrizes para implementação de procedimentos:
a) de coleta, verificação, validação e atualização de informações cadastrais,
visando a conhecer os clientes, os funcionários, os parceiros e os prestadores de
serviços terceirizados;
b) de registro de operações e de serviços financeiros;
c) de monitoramento, seleção e análise de operações e situações suspeitas; e
d) de comunicação de operações ao Conselho de Controle de Atividades
Financeiras (Coaf); e

III - o comprometimento da alta administração com a efetividade e a melhoria
contínua da política, dos procedimentos e dos controles internos relacionados com
a prevenção à lavagem de dinheiro e ao financiamento do terrorismo.

Art. 4º Admite-se a adoção de política de prevenção à lavagem de dinheiro e ao
financiamento do terrorismo única por conglomerado prudencial e por sistema
cooperativo de crédito.

Parágrafo único. As instituições que não constituírem política própria, em
decorrência do disposto no caput, devem formalizar a opção por essa faculdade
em reunião do conselho de administração ou, se inexistente, da diretoria da
instituição.

Art. 5º As instituições mencionadas no art. 1º devem assegurar a aplicação da
política referida no art. 2º em suas unidades situadas no exterior.

[Página 158]

Parágrafo único. Na hipótese de impedimento ou limitação legal à aplicação da
política referida no caput à unidade da instituição situada no exterior, deverá ser
elaborado relatório justificando o impedimento ou a limitação.

Art. 6º A política referida no art. 2º deve ser divulgada aos funcionários da
instituição, parceiros e prestadores de serviços terceirizados, mediante linguagem
clara e acessível, em nível de detalhamento compatível com as funções
desempenhadas e com a sensibilidade das informações.

Art. 7º A política referida no art. 2º deve ser:

I - documentada;

II - aprovada pelo conselho de administração ou, se inexistente, pela diretoria da
instituição; e

III - mantida atualizada.

CAPÍTULO III
DA GOVERNANÇA DA POLÍTICA DE PREVENÇÃO À LAVAGEM DE DINHEIRO E
AO FINANCIAMENTO DO TERRORISMO

Art. 8º As instituições mencionadas no art. 1º devem dispor de estrutura de
governança visando a assegurar o cumprimento da política referida no art. 2º e dos
procedimentos e controles internos de prevenção à lavagem de dinheiro e ao
financiamento do terrorismo previstos nesta Circular.

Art. 9º As instituições referidas no art. 1º devem indicar formalmente ao Banco
Central do Brasil diretor responsável pelo cumprimento das obrigações previstas
nesta Circular.

§ 1º O diretor mencionado no caput pode desempenhar outras funções na
instituição, desde que não haja conflito de interesses.

§ 2º A responsabilidade mencionada no caput deve ser observada em cada
instituição, mesmo no caso de opção pela faculdade estabelecida nos arts. 4º, 11,
42, 46 e 52.

CAPÍTULO IV
DA AVALIAÇÃO INTERNA DE RISCO

Art. 10. As instituições referidas no art. 1º devem realizar avaliação interna com o
objetivo de identificar e mensurar o risco de utilização de seus produtos e serviços
na prática da lavagem de dinheiro e do financiamento do terrorismo.

[Página 159]

§ 1º Para identificação do risco de que trata o caput, a avaliação interna deve
considerar, no mínimo, os perfis de risco:

I - dos clientes;

II - da instituição, incluindo o modelo de negócio e a área geográfica de atuação;

III - das operações, transações, produtos e serviços, abrangendo todos os canais de
distribuição e a utilização de novas tecnologias; e
IV - das atividades exercidas pelos funcionários, parceiros e prestadores de serviços
terceirizados.

§ 2º O risco identificado deve ser avaliado quanto à sua probabilidade de ocorrência
e à magnitude dos impactos financeiro, jurídico, reputacional e socioambiental
para a instituição.

§ 3º Devem ser definidas categorias de risco que possibilitem a adoção de controles
de gerenciamento e de mitigação reforçados para as situações de maior risco e a
adoção de controles simplificados nas situações de menor risco.

§ 4º Devem ser utilizadas como subsídio à avaliação interna de risco, quando
disponíveis, avaliações realizadas por entidades públicas do País relativas ao risco
de lavagem de dinheiro e de financiamento do terrorismo.

Art. 11. A avaliação interna de risco pode ser realizada de forma centralizada em
instituição do conglomerado prudencial e do sistema cooperativo de crédito.

Parágrafo único. As instituições que optarem por realizar a avaliação interna de
risco na forma do caput devem formalizar essa opção em reunião do conselho de
administração ou, se inexistente, da diretoria da instituição.

Art. 12. A avaliação interna de risco deve ser:

I - documentada e aprovada pelo diretor referido no art. 9º;

II - encaminhada para ciência:
a) ao comitê de risco, quando houver;
b) ao comitê de auditoria, quando houver; e
c) ao conselho de administração ou, se inexistente, à diretoria da instituição; e

III - revisada a cada dois anos, bem como quando ocorrerem alterações
significativas nos perfis de risco mencionados no art. 10, § 1º.

[Página 160]

CAPÍTULO V
DOS PROCEDIMENTOS DESTINADOS A CONHECER OS CLIENTES

Seção I
Dos Procedimentos

Art. 13. As instituições mencionadas no art. 1º devem implementar procedimentos
destinados a conhecer seus clientes, incluindo procedimentos que assegurem a
devida diligência na sua identificação, qualificação e classificação.

§ 1º Os procedimentos referidos no caput devem ser compatíveis com:

I - o perfil de risco do cliente, contemplando medidas reforçadas para clientes
classificados em categorias de maior risco, de acordo com a avaliação interna de
risco referida no art. 10;

II - a política de prevenção à lavagem de dinheiro e ao financiamento do terrorismo
de que trata o art. 2º; e

III - a avaliação interna de risco de que trata o art. 10.

§ 2º Os procedimentos mencionados no caput devem ser formalizados em manual
específico.

§ 3º O manual referido no § 2º deve ser aprovado pela diretoria da instituição e
mantido atualizado.

Art. 14. As informações obtidas e utilizadas nos procedimentos referidos no art. 13
devem ser armazenadas em sistemas informatizados e utilizadas nos
procedimentos de que trata o Capítulo VII.

Art. 15. Os procedimentos previstos neste Capítulo devem ser observados sem
prejuízo do disposto na regulamentação que disciplina produtos e serviços
específicos.

Seção II
Da Identificação dos Clientes

Art. 16. As instituições referidas no art. 1º devem adotar procedimentos de
identificação que permitam verificar e validar a identidade do cliente.

§ 1º Os procedimentos referidos no caput devem incluir a obtenção, a verificação
e a validação da autenticidade de informações de identificação do cliente,

[Página 161]

inclusive, se necessário, mediante confrontação dessas informações com as
disponíveis em bancos de dados de caráter público e privado.

§ 2º No processo de identificação do cliente devem ser coletados, no mínimo:

I - o nome completo e o número de registro no Cadastro de Pessoas Físicas (CPF),
no caso de pessoa natural (Redação dada pela Resolução BCB 119, de 27/07/2021);
e

II - a firma ou denominação social e o número de registro no Cadastro Nacional da
Pessoa Jurídica (CNPJ), no caso de pessoa jurídica (Redação dada pela Resolução
BCB 119, de 27/07/2021).

§ 3º No caso de cliente pessoa natural residente no exterior desobrigada de
inscrição no CPF, na forma definida pela Secretaria da Receita Federal do Brasil,
admite-se a utilização de documento de viagem na forma da Lei, devendo ser
coletados, no mínimo, o país emissor, o número e o tipo do documento.

§ 4º No caso de cliente pessoa jurídica com domicílio ou sede no exterior
desobrigada de inscrição no CNPJ, na forma definida pela Secretaria da Receita
Federal do Brasil, as instituições devem coletar, no mínimo, o nome da empresa, o
endereço da sede e o número de identificação ou de registro da empresa no
respectivo país de origem.

Art. 17. As informações referidas no art. 16 devem ser mantidas atualizadas. Seção
III Da Qualificação dos Clientes

Art. 18. As instituições mencionadas no art. 1º devem adotar procedimentos que
permitam qualificar seus clientes por meio da coleta, verificação e validação de
informações, compatíveis com o perfil de risco do cliente e com a natureza da
relação de negócio.

§ 1º Os procedimentos de qualificação referidos no caput devem incluir a coleta de
informações que permitam (Redação dada pela Resolução BCB 119, de
27/07/2021):

I - identificar o local de residência, no caso de pessoa natural (Incluído pela
Resolução BCB 119, de 27/07/2021);

II - identificar o local da sede ou filial, no caso de pessoa jurídica (Incluído pela
Resolução BCB 119, de 27/07/2021); e

[Página 162]

III - avaliar a capacidade financeira do cliente, incluindo a renda, no caso de pessoa
natural, ou o faturamento, no caso de pessoa jurídica (Incluído pela Resolução BCB
119, de 27/07/2021).

§ 2º A necessidade de verificação e de validação das informações referidas no § 1º
deve ser avaliada pelas instituições de acordo com o perfil de risco do cliente e com
a natureza da relação de negócio.

§ 3º Nos procedimentos de que trata o caput, devem ser coletadas informações
adicionais do cliente compatíveis com o risco de utilização de produtos e serviços
na prática da lavagem de dinheiro e do financiamento do terrorismo.

§ 4º A qualificação do cliente deve ser reavaliada de forma permanente, de acordo
com a evolução da relação de negócio e do perfil de risco.

§ 5º As informações coletadas na qualificação do cliente devem ser mantidas
atualizadas.

§ 6º O Banco Central do Brasil poderá divulgar rol de informações a serem
coletadas, verificadas e validadas em procedimentos específicos de qualificação de
clientes.

Art. 19. Os procedimentos de qualificação referidos no art. 18 devem incluir a
verificação da condição do cliente como pessoa exposta politicamente, nos termos
do art. 27, bem como a verificação da condição de representante, familiar ou
estreito colaborador dessas pessoas.

§ 1º Para os fins desta Circular, considera-se:

I - familiar, os parentes, na linha reta ou colateral, até o segundo grau, o cônjuge,
o companheiro, a companheira, o enteado e a enteada; e

II - estreito colaborador:

a) pessoa natural conhecida por ter qualquer tipo de estreita relação com pessoa
exposta politicamente, inclusive por:

1. ter participação conjunta em pessoa jurídica de direito privado;
2. figurar como mandatária, ainda que por instrumento particular da pessoa
mencionada no item 1; ou
3. ter participação conjunta em arranjos sem personalidade jurídica; e

[Página 163]

b) pessoa natural que tem o controle de pessoas jurídicas ou de arranjos sem
personalidade jurídica, conhecidos por terem sido criados para o benefício de
pessoa exposta politicamente.

§ 2º Para os clientes qualificados como pessoa exposta politicamente ou como
representante, familiar ou estreito colaborador dessas pessoas, as instituições
mencionadas no art. 1º devem:

I - adotar procedimentos e controles internos compatíveis com essa qualificação;

II - considerar essa qualificação na classificação do cliente nas categorias de risco
referidas no art. 20; e

III - avaliar o interesse no início ou na manutenção do relacionamento com o
cliente.

§ 3º A avaliação mencionada no § 2º, inciso III, deve ser realizada por detentor de
cargo ou função de nível hierárquico superior ao do responsável pela autorização
do relacionamento com o cliente.

Seção IV
Da Classificação dos Clientes

Art. 20. As instituições mencionadas no art. 1º devem classificar seus clientes nas
categorias de risco definidas na avaliação interna de risco mencionada no art. 10,
com base nas informações obtidas nos procedimentos de qualificação do cliente
referidos no art. 18.

Parágrafo único. A classificação mencionada no caput deve ser:

I - realizada com base no perfil de risco do cliente e na natureza da relação de
negócio; e

II - revista sempre que houver alterações no perfil de risco do cliente e na natureza
da relação de negócio.

Seção V
Disposições Comuns à Identificação, à Qualificação e à Classificação dos
Clientes

Art. 21. As instituições referidas no art. 1º devem adotar os procedimentos de
identificação, de qualificação e de classificação previstos neste Capítulo para os
administradores de clientes pessoas jurídicas e para os representantes de clientes.

[Página 164]

Parágrafo único. Os procedimentos referidos no caput devem ser compatíveis com
a função exercida pelo administrador e com a abrangência da representação.

Art. 22. Os critérios utilizados para a definição das informações necessárias e dos
procedimentos de verificação, validação e atualização das informações para cada
categoria de risco devem ser previstos no manual de que trata o art. 13, § 2º.

Art. 23. É vedado às instituições referidas no art. 1º iniciar relação de negócios sem
que os procedimentos de identificação e de qualificação do cliente estejam
concluídos.

Parágrafo único. Admite-se, por um período máximo de trinta dias, o início da
relação de negócios em caso de insuficiência de informações relativas à
qualificação do cliente, desde que não haja prejuízo aos procedimentos de
monitoramento e seleção de que trata o art. 39.

Art. 23-A. As instituições referidas no art. 1º ficam dispensadas de realizar os
procedimentos de qualificação e de classificação de clientes na contratação de
operação de crédito amparada por programa instituído pelo poder público federal
destinado à renegociação de dívidas de pessoas físicas inscritas em cadastros de
inadimplentes, desde que, cumulativamente (Artigo, incisos e parágrafo incluídos
pela Resolução BCB 344, de 04/10/2023):

I - as operações renegociadas estejam inadimplidas na data do estabelecimento do
respectivo programa;

II - os recursos liberados na operação de que trata o caput sejam transferidos
diretamente ao credor da dívida renegociada, sem qualquer interferência do
devedor; e

III - refiram-se a dívidas inadimplidas com pessoas jurídicas não financeiras ou
instituições autorizadas a funcionar pelo Banco Central do Brasil que sejam os
responsáveis pela inscrição do devedor em cadastros de inadimplentes.

Parágrafo único. O disposto no caput não se aplica à contratação de outros
produtos e serviços pelo cliente beneficiário da renegociação.

Seção VI
Da Identificação e da Qualificação do Beneficiário Final

Art. 24. Os procedimentos de qualificação do cliente pessoa jurídica devem incluir
a análise da cadeia de participação societária até a identificação da pessoa natural
caracterizada como seu beneficiário final, observado o disposto no art. 25.

[Página 165]

§ 1º Devem ser aplicados à pessoa natural referida no caput, no mínimo, os
procedimentos de qualificação definidos para a categoria de risco do cliente pessoa
jurídica na qual o beneficiário final detenha participação societária.

§ 2º É também considerado beneficiário final o representante, inclusive o
procurador e o preposto, que exerça o comando de fato sobre as atividades da
pessoa jurídica.

§ 3º Excetuam-se do disposto no caput (Parágrafo e incisos incluídos pela
Resolução BCB 119, de 27/07/2021):

I - as pessoas jurídicas caracterizadas como companhia aberta;

II - as entidade sem fins lucrativos;

III - as cooperativas;

IV - os fundos e clubes de investimento registrados na Comissão de Valores
Mobiliários, desde que, cumulativamente:

a) não sejam fundos exclusivos;
b) obtenham recursos de investidores com o propósito de atribuir o
desenvolvimento e a gestão de uma carteira de investimento a um gestor
qualificado que deve ter plena discricionariedade na representação e na tomada
de decisão perante as entidades investidas, não sendo obrigado a consultar os
cotistas para essas decisões e tampouco indicar os cotistas ou partes a eles ligadas
para atuar nas entidades investidas; e

c) seja informado o número de registro no CPF, no caso de pessoa natural, ou do
número de registro no CNPJ, no caso de pessoa jurídica, de todos os cotistas para
a Secretaria Especial da Receita Federal do Brasil (RFB), na forma por esta definida
em regulamentação específica;

V - os fundos de investimento registrados na Comissão de Valores Mobiliários,
constituídos na forma de condomínio fechado, cujas cotas sejam negociadas em
mercado organizado (Incluído pela Resolução BCB 119, de 27/07/2021);

VI - os investidores não residentes classificados como (Inciso e alíneas incluídos, a
pela Resolução BCB 119, de 27/07/2021):

a) governos, entidades governamentais e bancos centrais, assim como fundos
soberanos ou companhias de investimento controladas por fundos soberanos e
similares;

[Página 166]

b) organismos multilaterais;

c) companhias abertas ou equivalentes;
d) instituições financeiras ou similares, operando por conta própria;

e) administradores de carteiras, operando por conta própria;
f) sociedades seguradoras e entidades de previdência privada; e

g) fundos de investimento, desde que, cumulativamente:

1. o número de cotistas seja igual ou superior a cem e nenhum deles detenha
mais de 25% (vinte e cinco por cento) das cotas; e
2. a administração da carteira de ativos seja feita de forma discricionária por
administrador profissional sujeito à fiscalização de autoridade supervisora com a
qual o Banco Central do Brasil mantenha convênio para a troca de informações
relativas à prevenção da utilização do sistema financeiro para a prática dos crimes
de lavagem de dinheiro e de financiamento do terrorismo.

§ 4º No caso das entidades relacionadas no § 3º, as informações coletadas devem
abranger as das pessoas naturais autorizadas a representá-las, bem como as de
seus controladores, administradores ou gestores, e diretores, se houver (Incluído
pela Resolução BCB 119, de 27/07/2021).

Art. 25. As instituições mencionadas no art. 1º devem estabelecer valor mínimo de
referência de participação societária para a identificação de beneficiário final.

§ 1º O valor mínimo de referência de participação societária de que trata o caput
deve ser estabelecido com base no risco e não pode ser superior a 25% (vinte e
cinco por cento), considerada, em qualquer caso, a participação direta e a indireta.

§ 2º O valor de referência de que trata o caput deve ser justificado e documentado
no manual de procedimentos referido no art. 13, § 2º.

Art. 26. No caso de relação de negócio com cliente residente no exterior, que
também seja cliente de instituição do mesmo grupo no exterior, fiscalizada por
autoridade supervisora com a qual o Banco Central do Brasil mantenha convênio
para a troca de informações, admite-se que as informações relativas ao
beneficiário final sejam obtidas da instituição no exterior, desde que assegurado ao
Banco Central do Brasil o acesso às informações e aos procedimentos adotados.

Seção VII
Da Qualificação como Pessoa Exposta Politicamente

[Página 167]

Art. 27. As instituições mencionadas no art. 1º devem implementar procedimentos
que permitam qualificar seus clientes como pessoa exposta politicamente.

§ 1º Consideram-se pessoas expostas politicamente:

I - os detentores de mandatos eletivos dos Poderes Executivo e Legislativo da
União;

II - os ocupantes de cargo, no Poder Executivo da União, de:
a) Ministro de Estado ou equiparado;
b) Natureza Especial ou equivalente;
c) Presidente, vice-presidente e diretor, ou equivalentes, de entidades da
administração pública indireta; e
d) Grupo Direção e Assessoramento Superiores (DAS), nível 6, ou equivalente;

III - os membros do Conselho Nacional de Justiça, do Supremo Tribunal Federal,
dos Tribunais Superiores, dos Tribunais Regionais Federais, dos Tribunais Regionais
do Trabalho, dos Tribunais Regionais Eleitorais, do Conselho Superior da Justiça do
Trabalho e do Conselho da Justiça Federal;

IV - os membros do Conselho Nacional do Ministério Público, o Procurador-Geral
da República, o Vice-Procurador-Geral da República, o Procurador-Geral do
Trabalho, o Procurador-Geral da Justiça Militar, os Subprocuradores-Gerais da
República e os Procuradores Gerais de Justiça dos Estados e do Distrito Federal;

V - os membros do Tribunal de Contas da União, o Procurador-Geral e os
Subprocuradores-Gerais do Ministério Público junto ao Tribunal de Contas da
União;

VI - os presidentes e os tesoureiros nacionais, ou equivalentes, de partidos
políticos;

VII - os Governadores e os Secretários de Estado e do Distrito Federal, os Deputados
Estaduais e Distritais, os presidentes, ou equivalentes, de entidades da
administração pública indireta estadual e distrital e os presidentes de Tribunais de
Justiça, Tribunais Militares, Tribunais de Contas ou equivalentes dos Estados e do
Distrito Federal; e

VIII - os Prefeitos, os Vereadores, os Secretários Municipais, os presidentes, ou
equivalentes, de entidades da administração pública indireta municipal e os
Presidentes de Tribunais de Contas ou equivalentes dos Municípios.

§ 2º São também consideradas expostas politicamente as pessoas que, no exterior,
sejam:

[Página 168]

I - chefes de estado ou de governo;

II - políticos de escalões superiores;

III - ocupantes de cargos governamentais de escalões superiores;

IV - oficiais-generais e membros de escalões superiores do Poder Judiciário;

V - executivos de escalões superiores de empresas públicas; ou

VI - dirigentes de partidos políticos.

§ 3º São também consideradas pessoas expostas politicamente os dirigentes de
escalões superiores de entidades de direito internacional público ou privado.

§ 4º No caso de clientes residentes no exterior, para fins do disposto no caput, as
instituições mencionadas no art. 1º devem adotar pelo menos duas das seguintes
providências:

I - solicitar declaração expressa do cliente a respeito da sua qualificação;

II - recorrer a informações públicas disponíveis; e

III - consultar bases de dados públicas ou privadas sobre pessoas expostas
politicamente.

§ 5º A condição de pessoa exposta politicamente deve ser aplicada pelos cinco
anos seguintes à data em que a pessoa deixou de se enquadrar nas categorias
previstas nos §§ 1º, 2º, e 3º.

§ 6º No caso de relação de negócio com cliente residente no exterior que também
seja cliente de instituição do mesmo grupo no exterior, fiscalizada por autoridade
supervisora com a qual o Banco Central do Brasil mantenha convênio para troca
de informações, admite-se que as informações de qualificação de pessoa exposta
politicamente sejam obtidas da instituição no exterior, desde que assegurado ao
Banco Central do Brasil o acesso aos respectivos dados e procedimentos adotados.

CAPÍTULO VI
DO REGISTRO DE OPERAÇÕES
Seção I
Disposições Gerais

Art. 28. As instituições referidas no art. 1º devem manter registros de todas as
operações realizadas, produtos e serviços contratados, inclusive saques, depósitos,

[Página 169]

aportes, pagamentos, recebimentos, transferências de recursos e operações no
mercado de câmbio (Redação dada pela Resolução BCB 282, de 31/12/2022).

§ 1º Os registros referidos no caput devem conter, no mínimo, as seguintes
informações sobre cada operação:

I - tipo;

II - valor, quando aplicável;

III - data de realização;

IV - nome e número de inscrição no CPF ou no CNPJ do titular e do beneficiário da
operação, no caso de pessoa residente ou sediada no País; e

V - canal utilizado.

§ 2º No caso de operações envolvendo pessoa natural residente no exterior
desobrigada de inscrição no CPF, na forma definida pela Secretaria da Receita
Federal do Brasil, as instituições devem incluir no registro as seguintes
informações:

I - nome;

II - tipo e número do documento de viagem e respectivo país emissor; e

III - organismo internacional de que seja representante para o exercício de funções
específicas no País, quando for o caso.

§ 3º No caso de operações envolvendo pessoa jurídica com domicílio ou sede no
exterior desobrigada de inscrição no CNPJ, na forma definida pela Secretaria da
Receita Federal do Brasil, as instituições devem incluir no registro as seguintes
informações:

I - nome da empresa; e

II - número de identificação ou de registro da empresa no respectivo país de
origem.

§ 4º No caso de operações no mercado de câmbio, as instituições referidas no art.
1º devem, adicionalmente, manter registro e guarda dos documentos
comprobatórios exigidos para a realização de operações nesse mercado, conforme
critérios alinhados à avaliação interna de risco de que trata o Capítulo IV (Incluído
pela Resolução BCB 282, de 31/12/2022).

[Página 170]

Art. 29. Os registros de que trata este Capítulo devem ser realizados inclusive nas
situações em que a operação ocorrer no âmbito da mesma instituição.

Seção II
Do Registro de Operações de Pagamento, de Recebimento e de Transferência
de Recursos

Art. 30. No caso de operações relativas a pagamentos, recebimentos e
transferências de recursos, por meio de qualquer instrumento, as instituições
referidas no art. 1º devem incluir nos registros mencionados no art. 28 as
informações necessárias à identificação da origem e do destino dos recursos.

§ 1º A origem mencionada no caput refere-se à instituição pagadora, sacada ou
remetente e à pessoa sacada ou remetente dos recursos, bem como ao
instrumento de transferência ou de pagamento utilizado na transação.

§ 2º O destino mencionado no caput refere-se à instituição recebedora ou
destinatária e à pessoa recebedora ou destinatária dos recursos, bem como ao
instrumento de transferência ou de pagamento utilizado na transação.

§ 3º Para fins do cumprimento do disposto no caput, devem ser incluídas no
registro das operações, no mínimo, as seguintes informações, quando couber:

I - nome e número de inscrição no CPF ou no CNPJ do remetente ou sacado;

II - nome e número de inscrição no CPF ou no CNPJ do recebedor ou beneficiário;

III - códigos de identificação, no sistema de liquidação de pagamentos ou de
transferência de fundos, das instituições envolvidas na operação; e

IV - números das dependências e das contas envolvidas na operação.

§ 4º No caso de transferência de recursos por meio de cheque, as instituições
mencionadas no art. 1º devem incluir no registro da operação, além das
informações referidas no § 3º, o número do cheque.

Art. 31. Caso as instituições referidas no art. 1º estabeleçam relação de negócio
com terceiros não sujeitos a autorização para funcionar do Banco Central do Brasil,
participantes de arranjo de pagamento do qual a instituição também participe,
deve ser estipulado em contrato o acesso da instituição à identificação dos
destinatários finais dos recursos, para fins de prevenção à lavagem de dinheiro e
do financiamento do terrorismo.

[Página 171]

Parágrafo único. O disposto no caput se aplica inclusive no caso de relação de
negócio que envolva a interoperabilidade com arranjo de pagamento não sujeito a
autorização pelo Banco Central do Brasil, do qual as instituições referidas no art.
1º não participem.

Art. 32. No caso de transferência de recursos por meio da compensação
interbancária de cheque, a instituição sacada deve informar à instituição
depositária, e a instituição depositária deve informar à instituição sacada, os
números de inscrição no CPF ou no CNPJ dos titulares da conta sacada e da conta
depositária, respectivamente.

Seção III
Do Registro das Operações em Espécie

Art. 33. No caso de operações com utilização de recursos em espécie de valor
individual superior a R$2.000,00 (dois mil reais), as instituições referidas no art. 1º
devem incluir no registro, além das informações previstas nos arts. 28 e 30, o nome
e o respectivo número de inscrição no CPF do portador dos recursos.

Parágrafo único. Nas operações de que trata o caput, realizadas por empresa de
transporte de valores devidamente autorizada e registrada na autoridade
competente, nos termos da legislação em vigor, considera-se essa empresa como
a portadora dos recursos, a qual será identificada por meio do registro do número
de inscrição no CNPJ e da firma ou denominação social. (Incluído pela Resolução
BCB 119, de 27/07/2021.)

Art. 34. No caso de operações de depósito ou aporte em espécie de valor individual
igual ou superior a R$50.000,00 (cinquenta mil reais), as instituições referidas no
art. 1º devem incluir no registro, além das informações previstas nos arts. 28 e 30:

I - o nome e o respectivo número de inscrição no CPF ou no CNPJ, conforme o caso,
do proprietário dos recursos;

II - o nome e o respectivo número de inscrição no CPF do portador dos recursos; e

III - a origem dos recursos depositados ou aportados. Parágrafo único. Na hipótese
de recusa do cliente ou do portador dos recursos em prestar a informação referida
no inciso III do caput, a instituição deve registrar o fato e utilizar essa informação
nos procedimentos de monitoramento, seleção e análise de que tratam os art. 38
a 47.

Art. 35. No caso de operações de saque, inclusive as realizadas por meio de cheque
ou ordem de pagamento, de valor individual igual ou superior a R$50.000,00

[Página 172]

(cinquenta mil reais), as instituições referidas no art. 1º devem incluir no registro,
além das informações previstas nos arts. 28 e 30:

I - o nome e o respectivo número de inscrição no CPF ou no CNPJ, conforme o caso,
do destinatário dos recursos;

II - o nome e o respectivo número de inscrição no CPF do portador dos recursos;

III - a finalidade do saque; e IV - o número do protocolo referido no art. 36, § 2º,
inciso II.

Parágrafo único. Na hipótese de recusa do cliente ou do portador dos recursos em
prestar a informação referida no inciso III do caput, a instituição deve registrar o
fato e utilizar essa informação nos procedimentos de monitoramento, seleção e
análise de que tratam os art. 38 a 47.

Art. 36. As instituições mencionadas no art. 1º devem requerer dos sacadores
clientes e não clientes solicitação de provisionamento com, no mínimo, três dias
úteis de antecedência, das operações de saque, inclusive as realizadas por meio de
cheque ou ordem de pagamento, de valor igual ou superior a R$50.000,00
(cinquenta mil reais).

§ 1º As operações de saque de que trata o caput devem ser consideradas
individualmente, para efeitos de observação do limite previsto no caput.

§ 2º As instituições referidas no caput devem:

I - possibilitar a solicitação de provisionamento por meio do sítio eletrônico da
instituição na internet e das agências ou Postos de Atendimento;

II - emitir protocolo de atendimento ao cliente ou ao sacador não cliente, no qual
devem ser informados o valor da operação, a dependência na qual deverá ser
efetuado o saque e a data programada para o saque; e

III - registrar, no ato da solicitação de provisionamento, as informações indicadas
no art. 35, conforme o caso.

§ 3º No caso de saque em espécie a ser realizado por meio de cheque por sacador
não cliente, a solicitação de provisionamento de que trata o caput deve ser
realizada exclusivamente em agências ou em Postos de Atendimento.

§ 4º O disposto neste artigo deve ser observado sem prejuízo do art. 2º da
Resolução nº 3.695, de 26 de março de 2009.

[Página 173]

Art. 37. As instituições referidas no art. 1º devem manter registro específico de
recebimentos de boleto de pagamento pagos com recursos em espécie. Parágrafo
único. A instituição que receber boleto de pagamento que não seja de sua emissão
deve remeter à instituição emissora a informação de que o boleto foi pago em
espécie.

CAPÍTULO VII
DO MONITORAMENTO, DA SELEÇÃO E DA ANÁLISE DE OPERAÇÕES E
SITUAÇÕES SUSPEITAS

Seção I
Dos Procedimentos de Monitoramento, Seleção e Análise de Operações e
Situações Suspeitas

Art. 38. As instituições referidas no art. 1º devem implementar procedimentos de
monitoramento, seleção e análise de operações e situações com o objetivo de
identificar e dispensar especial atenção às suspeitas de lavagem de dinheiro e de
financiamento do terrorismo.

§ 1º Para os fins desta Circular, operações e situações suspeitas referem-se a
qualquer operação ou situação que apresente indícios de utilização da instituição
para a prática dos crimes de lavagem de dinheiro e de financiamento do terrorismo.

§ 2º Os procedimentos de que trata o caput devem ser aplicados, inclusive, às
propostas de operações. § 3º Os procedimentos mencionados no caput devem:

I - ser compatíveis com a política de prevenção à lavagem de dinheiro e ao
financiamento do terrorismo de que trata o art. 2º;

II - ser definidos com base na avaliação interna de risco de que trata o art. 10;

III - considerar a condição de pessoa exposta politicamente, nos termos do art. 27,
bem como a condição de representante, familiar ou estreito colaborador da pessoa
exposta politicamente, nos termos do art. 19; e

IV - estar descritos em manual específico, aprovado pela diretoria da instituição.

Seção II
Do Monitoramento e da Seleção de Operações e Situações Suspeitas

Art. 39. As instituições referidas no art. 1º devem implementar procedimentos de
monitoramento e seleção que permitam identificar operações e situações que
possam indicar suspeitas de lavagem de dinheiro e de financiamento do terrorismo,
especialmente:

[Página 174]

I - as operações realizadas e os produtos e serviços contratados que, considerando
as partes envolvidas, os valores, as formas de realização, os instrumentos utilizados
ou a falta de fundamento econômico ou legal, possam configurar a existência de
indícios de lavagem de dinheiro ou de financiamento do terrorismo, inclusive:
a) as operações realizadas ou os serviços prestados que, por sua habitualidade,
valor ou forma, configurem artifício que objetive burlar os procedimentos de
identificação, qualificação, registro, monitoramento e seleção previstos nesta
Circular;
b) as operações de depósito ou aporte em espécie, saque em espécie, ou pedido de
provisionamento para saque que apresentem indícios de ocultação ou
dissimulação da natureza, da origem, da localização, da disposição, da
movimentação ou da propriedade de bens, direitos e valores;
c) as operações realizadas e os produtos e serviços contratados que, considerando
as partes e os valores envolvidos, apresentem incompatibilidade com a capacidade
financeira do cliente, incluindo a renda, no caso de pessoa natural, ou o
faturamento, no caso de pessoa jurídica, e o patrimônio;
d) as operações com pessoas expostas politicamente de nacionalidade brasileira e
com representantes, familiares ou estreitos colaboradores de pessoas expostas
politicamente;
e) as operações com pessoas expostas politicamente estrangeiras;
f) os clientes e as operações em relação aos quais não seja possível identificar o
beneficiário final;
g) as operações oriundas ou destinadas a países ou territórios com deficiências
estratégicas na implementação das recomendações do Grupo de Ação Financeira
(Gafi); e
h) as situações em que não seja possível manter atualizadas as informações
cadastrais de seus clientes; e

II - as operações e situações que possam indicar suspeitas de financiamento do
terrorismo.

Parágrafo único. O período para a execução dos procedimentos de monitoramento
e de seleção das operações e situações suspeitas não pode exceder o prazo de
quarenta e cinco dias, contados a partir da data de ocorrência da operação ou da
situação.

Art. 40. As instituições referidas no art. 1º devem assegurar que os sistemas
utilizados no monitoramento e na seleção de operações e situações suspeitas
contenham informações detalhadas das operações realizadas e das situações
ocorridas, inclusive informações sobre a identificação e a qualificação dos
envolvidos.

§ 1º As instituições devem manter documentação detalhada dos parâmetros,
variáveis, regras e cenários utilizados no monitoramento e seleção de operações e

[Página 175]

situações que possam indicar suspeitas de lavagem de dinheiro e de financiamento
do terrorismo.

§ 2º Os sistemas e os procedimentos utilizados no monitoramento e na seleção de
operações e situações suspeitas devem ser passíveis de verificação quanto à sua
adequação e efetividade.

Art. 41. Devem ser incluídos no manual referido no art. 38, § 3º, inciso IV:

I - os critérios de definição da periodicidade de execução dos procedimentos de
monitoramento e seleção para os diferentes tipos de operações e situações
monitoradas; e
II - os parâmetros, as variáveis, as regras e os cenários utilizados no monitoramento
e seleção para os diferentes tipos de operações e situações.

Art. 42. Os procedimentos de monitoramento e seleção referidos no art. 39 podem
ser realizados de forma centralizada em instituição do conglomerado prudencial e
do sistema cooperativo de crédito.

Parágrafo único. As instituições que optarem por realizar os procedimentos de
monitoramento e seleção na forma do caput devem formalizar essa opção em
reunião do conselho de administração ou, se inexistente, da diretoria da instituição.

Seção III
Dos Procedimentos de Análise de Operações e Situações Suspeitas

Art. 43. As instituições referidas no art. 1º devem implementar procedimentos de
análise das operações e situações selecionadas por meio dos procedimentos de
monitoramento e seleção de que trata o art. 39, com o objetivo de caracterizá-las
ou não como suspeitas de lavagem de dinheiro e de financiamento do terrorismo.

§ 1º O período para a execução dos procedimentos de análise das operações e
situações selecionadas não pode exceder o prazo de quarenta e cinco dias,
contados a partir da data da seleção da operação ou situação.

§ 2º A análise mencionada no caput deve ser formalizada em dossiê,
independentemente da comunicação ao Coaf referida no art. 48.

Art. 44. É vedada:

I - a contratação de terceiros para a realização da análise referida no art. 43; e

[Página 176]

II - a realização da análise referida no art. 43 no exterior. Parágrafo único. A
vedação mencionada no caput não inclui a contratação de terceiros para a
prestação de serviços auxiliares à análise referida no art. 43.

Art. 45. As instituições referidas no art. 1º devem dispor, no País, de recursos e
competências necessários à análise de operações e situações suspeitas referida no
art. 43.

Art. 46. Os procedimentos de análise referidos no art. 43 podem ser realizados de
forma centralizada em instituição do conglomerado prudencial e do sistema
cooperativo de crédito.

Parágrafo único. As instituições que optarem por realizar os procedimentos de
análise na forma do caput devem formalizar a opção em reunião do conselho de
administração ou, se inexistente, da diretoria da instituição.

Seção IV
Disposições Gerais

Art. 47. No caso de contratação de serviços de processamento e armazenamento
de dados e de computação em nuvem utilizados para monitoramento e seleção de
operações e situações suspeitas, bem como de serviços auxiliares à análise dessas
operações e situações, as instituições referidas no art. 1º devem observar:

I - o disposto no Capítulo III da Circular nº 3.909, de 16 de agosto de 2018, e, no
que couber, nos Capítulos IV e V da referida Circular, no caso de instituições de
pagamento; e

II - o disposto no Capítulo III da Resolução nº 4.658, de 26 de abril de 2018, e, no
que couber, nos Capítulos IV e V da referida Resolução, no caso de instituições
financeiras e demais instituições autorizadas a funcionar pelo Banco Central do
Brasil.

CAPÍTULO VIII
DOS PROCEDIMENTOS DE COMUNICAÇÃO AO COAF

Seção I
Da Comunicação de Operações e Situações Suspeitas

Art. 48. As instituições referidas no art. 1º devem comunicar ao Coaf as operações
ou situações suspeitas de lavagem de dinheiro e de financiamento do terrorismo.

§ 1º A decisão de comunicação da operação ou situação ao Coaf deve:

[Página 177]

I - ser fundamentada com base nas informações contidas no dossiê mencionado no
art. 43, § 2º;

II - ser registrada de forma detalhada no dossiê mencionado no art. 43, § 2º; e
III - ocorrer até o final do prazo de análise referido no art. 43, § 1º.

§ 2º A comunicação da operação ou situação suspeita ao Coaf deve ser realizada
até o dia útil seguinte ao da decisão de comunicação.

Seção II
Da Comunicação de Operações em Espécie

Art. 49. As instituições mencionadas no art. 1º devem comunicar ao Coaf:

I - as operações de depósito ou aporte em espécie ou saque em espécie de valor
igual ou superior a R$50.000,00 (cinquenta mil reais);

II - as operações relativas a pagamentos, recebimentos e transferências de
recursos, por meio de qualquer instrumento, contra pagamento em espécie, de
valor igual ou superior a R$50.000,00 (cinquenta mil reais); e

III - a solicitação de provisionamento de saques em espécie de valor igual ou
superior a R$50.000,00 (cinquenta mil reais) de que trata o art. 36.

Parágrafo único. A comunicação mencionada no caput deve ser realizada até o dia
útil seguinte ao da ocorrência da operação ou do provisionamento.

Seção III
Disposições Gerais

Art. 50. As instituições referidas no art. 1º devem realizar as comunicações
mencionadas nos arts. 48 e 49 sem dar ciência aos envolvidos ou a terceiros.

Art. 51. As comunicações alteradas ou canceladas após o quinto dia útil seguinte
ao da sua realização devem ser acompanhadas de justificativa da ocorrência.

Art. 52. As comunicações podem ser realizadas de forma centralizada por meio de
instituição do conglomerado prudencial e de sistema cooperativo de crédito, em
nome da instituição na qual ocorreu a operação ou a situação.

Parágrafo único. As instituições que optarem por realizar as comunicações de
forma centralizada, nos termos do caput, devem formalizar a opção em reunião do
conselho de administração ou, se inexistente, da diretoria da instituição.

[Página 178]

Art. 53. As comunicações referidas nos arts. 48 e 49 devem especificar, quando for
o caso, se a pessoa objeto da comunicação:

I - é pessoa exposta politicamente ou representante, familiar ou estreito
colaborador dessa pessoa;

II - é pessoa que, reconhecidamente, praticou ou tenha intentado praticar atos
terroristas ou deles participado ou facilitado o seu cometimento; e

III - é pessoa que possui ou controla, direta ou indiretamente, recursos na
instituição, no caso do inciso II.

Art. 54. As instituições de que trata o art. 1º que não tiverem efetuado
comunicações ao Coaf em cada ano civil deverão prestar declaração, até dez dias
úteis após o encerramento do referido ano, atestando a não ocorrência de
operações ou situações passíveis de comunicação.

Art. 55. As instituições referidas no art. 1º devem se habilitar para realizar as
comunicações no Sistema de Controle de Atividades Financeiras (Siscoaf), do Coaf.

CAPÍTULO IX
DOS PROCEDIMENTOS DESTINADOS A CONHECER FUNCIONÁRIOS, PARCEIROS
E PRESTADORES DE SERVIÇOS TERCEIRIZADOS

Art. 56. As instituições mencionadas no art. 1º devem implementar procedimentos
destinados a conhecer seus funcionários, parceiros e prestadores de serviços
terceirizados, incluindo procedimentos de identificação e qualificação.

Parágrafo único. Os procedimentos referidos no caput devem ser compatíveis com
a política de prevenção à lavagem de dinheiro e ao financiamento do terrorismo de
que trata o art. 2º e com a avaliação interna de risco de que trata o art. 10.

Art. 57. Os procedimentos referidos no art. 56 devem ser formalizados em
documento específico aprovado pela diretoria da instituição.
Parágrafo único. O documento mencionado no caput deve ser mantido atualizado.

Art. 58. As instituições referidas no art. 1º devem classificar as atividades exercidas
por seus funcionários, parceiros e prestadores de serviços terceirizados nas
categorias de risco definidas na avaliação interna de risco, nos termos do art. 10.

§ 1º A classificação em categorias de risco mencionada no caput deve ser mantida
atualizada. §

[Página 179]

2º Os critérios para a classificação em categorias de risco referida no caput devem
estar previstos no documento mencionado no art. 57.

§ 3º As informações relativas aos funcionários, parceiros e prestadores de serviços
terceirizados devem ser mantidas atualizadas, considerando inclusive eventuais
alterações que impliquem mudança de classificação nas categorias de risco.

Art. 59. As instituições referidas no art. 1º, na celebração de contratos com
instituições financeiras sediadas no exterior, devem:

I - obter informações sobre o contratado que permitam compreender a natureza
de sua atividade e a sua reputação;

II - verificar se o contratado foi objeto de investigação ou de ação de autoridade
supervisora relacionada com lavagem de dinheiro ou com financiamento do
terrorismo;

III - certificar que o contratado tem presença física no país onde está constituído
ou licenciado;

IV - conhecer os controles adotados pelo contratado relativos à prevenção à
lavagem de dinheiro e ao financiamento do terrorismo;

V - obter a aprovação do detentor de cargo ou função de nível hierárquico superior
ao do responsável pela contratação; e

VI - dar ciência do contrato de parceria ao diretor mencionado no art. 9º.

Parágrafo único. O disposto no caput aplica-se inclusive às relações de parceria
estabelecidas com bancos correspondentes no exterior.

Art. 60. As instituições referidas no art. 1º, na celebração de contratos com
terceiros não sujeitos a autorização para funcionar do Banco Central do Brasil,
participantes de arranjo de pagamento do qual a instituição também participe,
devem:

I - obter informações sobre o terceiro que permitam compreender a natureza de
sua atividade e a sua reputação;

II - verificar se o terceiro foi objeto de investigação ou de ação de autoridade
supervisora relacionada com lavagem de dinheiro ou com financiamento do
terrorismo;

[Página 180]

III - certificar que o terceiro tem licença do instituidor do arranjo para operar,
quando for o caso;

IV - conhecer os controles adotados pelo terceiro relativos à prevenção à lavagem
de dinheiro e ao financiamento do terrorismo; e V - dar ciência do contrato ao
diretor mencionado no art. 9º.

CAPÍTULO X
DOS MECANISMOS DE ACOMPANHAMENTO E DE CONTROLE

Art. 61. As instituições mencionadas no art. 1º devem instituir mecanismos de
acompanhamento e de controle de modo a assegurar a implementação e a
adequação da política, dos procedimentos e dos controles internos de que trata
esta Circular, incluindo:

I - a definição de processos, testes e trilhas de auditoria;

II - a definição de métricas e indicadores adequados; e

III - a identificação e a correção de eventuais deficiências.
Parágrafo único. Os mecanismos de que trata o caput devem ser submetidos a
testes periódicos pela auditoria interna, quando aplicáveis, compatíveis com os
controles internos da instituição.

CAPÍTULO XI
DA AVALIAÇÃO DE EFETIVIDADE

Art. 62. As instituições referidas no art. 1º devem avaliar a efetividade da política,
dos procedimentos e dos controles internos de que trata esta Circular.

§ 1º A avaliação referida no caput deve ser documentada em relatório específico.

§ 2º O relatório de que trata o § 1º deve ser:

I - elaborado anualmente, com data-base de 31 de dezembro; e

II - encaminhado, para ciência, até 31 de março do ano seguinte ao da data-base:
a) ao comitê de auditoria, quando houver; e
b) ao conselho de administração ou, se inexistente, à diretoria da instituição.

Art. 63. O relatório referido no art. 62, § 1º, deve:

I - conter informações que descrevam:
a) a metodologia adotada na avaliação de efetividade;

[Página 181]

b) os testes aplicados;
c) a qualificação dos avaliadores; e
d) as deficiências identificadas; e

II - conter, no mínimo, a avaliação:
a) dos procedimentos destinados a conhecer clientes, incluindo a verificação e a
validação das informações dos clientes e a adequação dos dados cadastrais;
b) dos procedimentos de monitoramento, seleção, análise e comunicação ao Coaf,
incluindo a avaliação de efetividade dos parâmetros de seleção de operações e de
situações suspeitas;
c) da governança da política de prevenção à lavagem de dinheiro e ao
financiamento do terrorismo;
d) das medidas de desenvolvimento da cultura organizacional voltadas à
prevenção da lavagem de dinheiro e ao financiamento do terrorismo;
e) dos programas de capacitação periódica de pessoal;
f) dos procedimentos destinados a conhecer os funcionários, parceiros e
prestadores de serviços terceirizados; e
g) das ações de regularização dos apontamentos oriundos da auditoria interna e da
supervisão do Banco Central do Brasil.

Art. 64. Admite-se a elaboração de um único relatório de avaliação de efetividade
nos termos do art. 62, § 1º, relativo às instituições do conglomerado prudencial e
do sistema cooperativo de crédito.

Parágrafo único. As instituições que optarem por realizar o relatório de avaliação
de efetividade na forma do caput devem formalizar a opção em reunião do
conselho de administração ou, se inexistente, da diretoria da instituição.

Art. 65. As instituições referidas no art. 1º devem elaborar plano de ação destinado
a solucionar as deficiências identificadas por meio da avaliação de efetividade de
que trata o art. 62.

§ 1º O acompanhamento da implementação do plano de ação referido no caput
deve ser documentado por meio de relatório de acompanhamento.

§ 2º O plano de ação e o respectivo relatório de acompanhamento devem ser
encaminhados para ciência e avaliação, até 30 de junho do ano seguinte ao da
data-base do relatório de que trata o art. 62, § 1º:

I - do comitê de auditoria, quando houver;

II - da diretoria da instituição; e

III - do conselho de administração, quando existente.

[Página 182]

CAPÍTULO XII
DISPOSIÇÕES FINAIS

Art. 66. Devem permanecer à disposição do Banco Central do Brasil:

I - o documento de que trata o art. 7º, inciso I, relativo à política de prevenção à
lavagem de dinheiro e ao financiamento do terrorismo de que trata o art. 2º;

II - a ata de reunião do conselho de administração ou, na sua inexistência, da
diretoria da instituição, no caso de ser formalizada a opção de que trata o caput do
art. 4º;

III - o relatório de que trata o art. 5º, parágrafo único, se existente;

IV - o documento relativo à avaliação interna de risco de que trata o art. 12, inciso
I, juntamente com a documentação de suporte à sua elaboração;

V - o contrato referido no art. 31;

VI - a ata de reunião do conselho de administração ou, na sua inexistência, da
diretoria da instituição, no caso de serem formalizadas as opções mencionadas nos
arts. 11, 42, 46, 52 e 64;

VII - o relatório de avaliação de efetividade de que trata o art. 62, § 1º;

VIII - as versões anteriores da avaliação interna de risco de que trata o art. 10;

IX - o manual relativo aos procedimentos destinados a conhecer os clientes
referido no art. 13, § 2º;

X - o manual relativo aos procedimentos de monitoramento, seleção e análise de
operações e situações suspeitas mencionado no art. 38, § 3º, inciso IV;

XI - o documento relativo aos procedimentos destinados a conhecer os
funcionários, parceiros e prestadores de serviços terceirizados mencionado no art.
57;

XII - as versões anteriores do relatório de avaliação de efetividade de que trata o
art. 62, § 1º;

XIII - os dados, os registros e as informações relativas aos mecanismos de
acompanhamento e de controle de que trata o art. 61; e

[Página 183]

XIV - os documentos relativos ao plano de ação e ao respectivo relatório de
acompanhamento mencionados no art. 65.

§ 1º O contrato referido no inciso V do caput deve permanecer à disposição do
Banco Central do Brasil pelo prazo mínimo de cinco anos após o encerramento da
relação contratual.

§ 2º Os documentos e informações referidos nos incisos VIII a XIV do caput devem
permanecer à disposição do Banco Central do Brasil pelo prazo mínimo de cinco
anos.

Art. 67. As instituições referidas no art. 1º devem manter à disposição do Banco
Central do Brasil e conservar pelo período mínimo de dez anos:

I - as informações coletadas nos procedimentos destinados a conhecer os clientes
de que tratam os arts. 13, 16 e 18, contado o prazo referido no caput a partir do
primeiro dia do ano seguinte ao término do relacionamento com o cliente;

II - as informações coletadas nos procedimentos destinados a conhecer os
funcionários, parceiros e prestadores de serviços terceirizados de que trata o art.
56, contado o prazo referido no caput a partir da data de encerramento da relação
contratual;

III - as informações e registros de que tratam os arts. 28 a 37, contado o prazo
referido no caput a partir do primeiro dia do ano seguinte ao da realização da
operação; e

IV - o dossiê referido no art. 43, § 2º.

Art. 68. (Revogado pela Resolução BCB nº 282, de 31/12/2022).

Ficam revogados uma série de dispositivos anteriores.

[Página 184]$mat$, 'junho/2026'),
(2, 5, $mat$Carta Circular 4.001/2020 e IN BCB 461/2024: indícios de operações suspeitas$mat$, $mat$Carta Circular n° 4.001, de 29 de janeiro de 2020

Para fins de objetividade, serão listados apenas os incisos que tenham
relação direta com as operações de câmbio.

Divulga relação de operações e situações que podem configurar indícios
de ocorrência dos crimes de "lavagem" ou ocultação de bens, direitos e valores,
de que trata a Lei nº 9.613, de 3 de março de 1998, e de financiamento ao
terrorismo, previstos na Lei nº 13.260, de 16 de março de 2016, passíveis de
comunicação ao Conselho de Controle de Atividades Financeiras (COAF).

Art. 1º As operações ou as situações descritas a seguir exemplificam a
ocorrência de indícios de suspeita para fins dos procedimentos de
monitoramento e seleção previstos na Circular nº 3.978, de 23 de janeiro de
2020:

II - Situações relacionadas com operações em espécie e cartões pré-pagos em
moeda estrangeira e cheques de viagem:
a) movimentações de moeda estrangeira em espécie ou de cheques de
viagem denominados em moeda estrangeira, que apresentem atipicidade em
relação à atividade econômica do cliente ou incompatibilidade com a sua
capacidade financeira;
b) negociações de moeda estrangeira em espécie ou de cheques de
viagem
denominados
em
moeda
estrangeira,
que
não
apresentem
compatibilidade com a natureza declarada da operação;
c) negociações de moeda estrangeira em espécie ou de cheques de
viagem denominados em moeda estrangeira, realizadas por diferentes pessoas
naturais, não relacionadas entre si, que informem o mesmo endereço residencial,
telefone de contato ou possuam o mesmo representante legal;
d) negociações envolvendo taxas de câmbio com variação significativa
em relação às praticadas pelo mercado;
e) negociações de moeda estrangeira em espécie envolvendo cédulas
úmidas, malcheirosas, mofadas, ou com aspecto de terem sido armazenadas em
local impróprio, ou ainda que apresentem marcas, símbolos ou selos
desconhecidos, empacotadas em maços desorganizados e não uniformes;
f) negociações de moeda estrangeira em espécie ou troca de grandes
quantidades de cédulas de pequeno valor, realizadas por pessoa natural ou
jurídica, cuja atividade ou negócio não tenha como característica o recebimento
desse tipo de recurso;
g) utilização, carga ou recarga de cartão pré-pago em valor não
compatível com a capacidade financeira, atividade ou perfil do cliente;
h) utilização de diversas fontes de recursos para carga e recarga de
cartões pré-pagos;

[Página 185]

i) carga e recarga de cartões pré-pagos seguidas imediatamente por
saques em caixas eletrônicos.

III - Situações relacionadas com a identificação e qualificação de clientes:
a) resistência ao fornecimento de informações necessárias para o início
de relacionamento ou para a atualização cadastral;
b) oferecimento de informação falsa;
c) prestação de informação de difícil ou onerosa verificação;
d) abertura, movimentação de contas ou realização de operações por
detentor de procuração ou de qualquer outro tipo de mandato;
e) ocorrência de irregularidades relacionadas aos procedimentos de
identificação e registro das operações exigidos pela regulamentação vigente;
f) cadastramento de várias contas em uma mesma data, ou em curto
período, com depósitos de valores idênticos ou aproximados, ou com outros
elementos em comum, tais como origem dos recursos, titulares, procuradores,
sócios, endereço, número de telefone, etc;
g) operações em que não seja possível identificar o beneficiário final,
observados os procedimentos definidos na regulamentação vigente;
h) representação de diferentes pessoas jurídicas ou organizações pelos
mesmos procuradores ou representantes legais, sem justificativa razoável para
tal ocorrência;
i) informação de mesmo endereço residencial ou comercial por pessoas
naturais, sem demonstração da existência de relação familiar ou comercial;
j) incompatibilidade da atividade econômica ou faturamento informados
com o padrão apresentado por clientes com o mesmo perfil;
k) registro de mesmo endereço de e-mail ou de Internet Protocol (IP) por
diferentes pessoas jurídicas ou organizações, sem justificativa razoável para tal
ocorrência;
l) registro de mesmo endereço de e-mail ou Internet Protocol (IP) por
pessoas naturais, sem justificativa razoável para tal ocorrência;
m) informações e documentos apresentados pelo cliente conflitantes
com as informações públicas disponíveis;
n) sócios de empresas sem aparente capacidade financeira para o porte
da atividade empresarial declarada.

V - Situações relacionadas com operações de investimento no País:

a) operações ou conjunto de operações de compra ou de venda de
ativos financeiros a preços incompatíveis com os praticados no mercado ou
quando realizadas por pessoa natural ou jurídica cuja atividade declarada e
perfil não se coadunem ao tipo de negociação realizada;

[Página 186]

b) operações atípicas que resultem em elevados ganhos para os
agentes intermediários, em desproporção com a natureza dos serviços
efetivamente prestados;

c) investimentos significativos em produtos de baixa rentabilidade e
liquidez;

d) investimentos significativos não proporcionais à capacidade
financeira do cliente, ou cuja origem não seja claramente conhecida;

e) resgates de investimentos no curtíssimo prazo, independentemente
do resultado auferido.

IX - Situações relacionadas a pessoas ou entidades suspeitas de envolvimento
com financiamento ao terrorismo e a proliferação de armas de destruição em
massa:
a) movimentações financeiras envolvendo pessoas ou entidades
relacionadas a atividades terroristas listadas pelo Conselho de Segurança das
Nações Unidas (CSNU);
b) operações ou prestação de serviços, de qualquer valor, a pessoas ou
entidades que reconhecidamente tenham cometido ou intentado cometer atos
terroristas, ou deles participado ou facilitado o seu cometimento;
c) existência de recursos pertencentes ou controlados, direta ou
indiretamente, por pessoas ou entidades que reconhecidamente tenham
cometido ou intentado cometer atos terroristas, ou deles participado ou
facilitado o seu cometimento;
d) movimentações com indícios de financiamento ao terrorismo;
e) movimentações financeiras envolvendo pessoas ou entidades
relacionadas à proliferação de armas de destruição em massa listadas pelo
CSNU;
f) operações ou prestação de serviços, de qualquer valor, a pessoas ou
entidades que reconhecidamente tenham cometido ou intentado cometer
crimes de proliferação de armas de destruição em massa, ou deles participado
ou facilitado o seu cometimento;
g) existência de recursos pertencentes ou controlados, direta ou
indiretamente, por pessoas ou entidades que reconhecidamente tenham
cometido ou intentado cometer crimes de proliferação de armas de destruição
em massa, ou deles participado ou facilitado o seu cometimento;
h) movimentações com indícios de financiamento da proliferação de
armas de destruição em massa.

X - Situações relacionadas com atividades internacionais:
a) operação com pessoas naturais ou jurídicas, inclusive sociedades e
instituições financeiras, situadas em países que não apliquem ou apliquem

[Página 187]

insuficientemente as recomendações do Grupo de Ação contra a Lavagem de
Dinheiro e o Financiamento do Terrorismo (Gafi), ou que tenham sede em países
ou dependências com tributação favorecida ou regimes fiscais privilegiados, ou
em locais onde seja observada a prática contumaz dos crimes previstos na Lei nº
9.613, de 3 de março de 1998, não claramente caracterizadas em sua legalidade
e fundamentação econômica;
b) operações complexas e com custos mais elevados que visem a
dificultar o rastreamento dos recursos ou a identificação da natureza da
operação;
c) pagamentos de importação e recebimentos de exportação,
antecipados ou não, por empresa sem tradição ou cuja capacidade financeira
seja incompatível com o montante negociado;
d) pagamentos a terceiros não relacionados a operações de importação
ou de exportação;
e) transferências unilaterais que, pela habitualidade, valor ou forma, não
se justifiquem ou apresentem atipicidade;
f) transferências internacionais, inclusive a título de disponibilidade no
exterior, nas quais não se justifique a origem dos fundos envolvidos ou que se
mostrem incompatíveis com a capacidade financeira ou com o perfil do cliente;
g) exportações ou importações aparentemente fictícias ou com indícios
de superfaturamento ou subfaturamento, ou ainda em situações que não seja
possível obter informações sobre o desembaraço aduaneiro das mercadorias;
h) existência de informações na carta de crédito com discrepâncias em
relação a outros documentos da operação de comércio internacional;
i) pagamentos ao exterior após créditos em reais efetuados nas contas
de depósitos dos titulares das operações de câmbio por pessoas naturais ou
jurídicas que não demonstrem a existência de vínculo comercial ou econômico;
j) movimentações decorrentes de programa de repatriação de recursos
que apresentem inconsistências relacionadas à identificação do titular ou do
beneficiário
final, bem como ausência de informações confiáveis sobre a origem e a
fundamentação econômica ou legal;
k) pagamentos de frete ou de outros serviços que apresentem indícios de
atipicidade ou de incompatibilidade com a atividade ou capacidade econômico-
financeira do cliente;
l) transferências internacionais por uma ou mais pessoas naturais ou
jurídicas com indícios de fragmentação, como forma de ocultar a real origem ou
destino dos recursos;
m)
transações em uma mesma data, ou em curto período, de valores
idênticos ou aproximados, ou com outros elementos em comum, tais como
origem ou destino dos recursos, titulares, procuradores, endereço, número de
telefone, que configurem artificio de burla do limite máximo de operação;
n) transferência via facilitadora de pagamentos ou com a utilização do
cartão de crédito de uso internacional, que, pela habitualidade, valor ou forma,

[Página 188]

não se justifiquem ou apresentem atipicidade;
o) transferências relacionadas a investimentos não convencionais que,
pela habitualidade, valor ou forma, não se justifiquem ou apresentem
atipicidade;
p) pagamento de frete internacional sem amparo em documentação que
evidencie vínculo com operação comercial.

XI - Situações relacionadas com operações de crédito contratadas no exterior:
a) contratação de operações de crédito no exterior com cláusulas que
estabeleçam condições incompatíveis com as praticadas no mercado, como
juros destoantes da prática ou prazo muito longo;
b) contratação, no exterior, de várias operações de crédito consecutivas,
sem que a instituição tome conhecimento da quitação das anteriores;
c) contratação, no exterior, de operações de crédito que não sejam
quitadas por intermédio de operações na mesma instituição;
d) contratação, no exterior, de operações de crédito, quitadas sem
explicação aparente para a origem dos recursos;
e) contratação de empréstimos ou financiamentos no exterior,
oferecendo garantias em valores ou formas incompatíveis com a atividade ou
capacidade financeira do cliente ou em valores muito superiores ao valor das
operações contratadas ou cuja origem não seja claramente conhecida;
f) contratação de operações de crédito no exterior, cujo credor seja de
difícil identificação e sem que exista relação ou fundamentação para a operação
entre as partes.

XII - Situações relacionadas com operações de investimento externo:
a) recebimento de investimento externo direto, cujos recursos retornem
imediatamente a título de disponibilidade no exterior;
b) recebimento de investimento externo direto, com realização quase
imediata de remessas de recursos para o exterior a título de lucros e dividendos;
c) remessas de lucros e dividendos ao exterior em valores incompatíveis
com o valor investido;
d) remessas ao exterior a título de investimento em montantes
incompatíveis com a capacidade financeira do cliente;
e) remessas de recursos de um mesmo investidor situado no exterior
para várias empresas no País;
f) remessas de recursos de vários investidores situados no exterior para
uma mesma empresa no País;
g) recebimento de aporte de capital desproporcional ao porte ou à
natureza empresarial do cliente, ou em valores incompatíveis com a capacidade
financeira dos sócios;
h) retorno de investimento feito no exterior sem comprovação da

[Página 189]

remessa que lhe tenha dado origem.

XIII - Situações relacionadas com funcionários, parceiros e prestadores de
serviços terceirizados:
a) alteração inusitada nos padrões de vida e de comportamento do
empregado, do parceiro ou de prestador de serviços terceirizados, sem causa
aparente;
b) modificação inusitada do resultado operacional da pessoa jurídica do
parceiro, incluído correspondente no País, sem causa aparente;
c) qualquer negócio realizado de modo diverso ao procedimento formal
da instituição por funcionário, parceiro, incluído correspondente no País, ou
prestador de serviços terceirizados;
d) fornecimento de auxílio ou informações, remunerados ou não, a
cliente em prejuízo do programa de prevenção à lavagem de dinheiro e ao
financiamento do terrorismo da instituição, ou de auxílio para estruturar ou
fracionar operações, burlar limites regulamentares ou operacionais.

XVI - Situações relacionadas com a movimentação de contas correntes em
moeda estrangeira (CCME):
a) movimentação de recursos incompatível com a atividade econômica
e a capacidade financeira do cliente;
b) recebimentos
ou
pagamentos
de/para
terceiros
cujas
movimentações financeiras não apresentem fundamentação econômica ou
legal ou nas quais pareça não haver vinculação entre a atividade declarada do
titular da CCME e as outras partes envolvidas nas transações;
c) movimentação de recursos, em especial nas contas tituladas por
agentes autorizados a operar no mercado de câmbio, que denotem inobservância
a limites por operação cambial ou qualquer outra situação em que não se
justifiquem ou apresentem atipicidade, pela habitualidade, valor, forma ou
ausência de aderência às normas cambiais;
d) transações atípicas em CCME de movimentação restrita. Exemplos:
contas de agências de turismo e contas de administradoras de cartão de crédito.

XVII - Situações relacionadas com operações realizadas em municípios
localizados em regiões de risco:
a) operação atípica em municípios localizados em regiões de fronteira;
b) operação atípica em municípios localizados em regiões de extração
mineral;
c) operação atípica em municípios localizados em outras regiões de risco.

[Página 190]

§ 1º As operações ou as situações referidas no caput devem ser
comunicadas, nos termos da referida Circular 3.978, somente nos casos em que
os indícios forem confirmados ao término da execução dos procedimentos de
análise de operações e situações suspeitas.

§ 2º. Os procedimentos referidos no § 1º devem considerar todas as
informações disponíveis, inclusive aquelas obtidas por meio dos procedimentos
destinados a conhecer clientes, funcionários, parceiros e prestadores de serviços
terceirizados”.

Instrução Normativa BCB n° 461, de 2 de abril de 2024 (complementa a Carta
Circular 4.001)

Art. 1º A Carta Circular BCB nº 4.001, de 29 de janeiro de 2020, passa a figurar com
as seguintes alterações:
 Art.2º.................................................................
XVIII – Situações relacionadas com a primeira aquisição de ouro:
a) proposta de venda de ouro com pagamento em espécie;
b) proposta de venda de ouro com pagamento a terceiro;
c) proposta de venda de ouro sem a indicação do título minerário de
origem ou com a indicação de título minerário inativo;
d) proposta de venda de ouro oriundo de áreas com títulos minerários
para extração por meio de Permissão de Lavra Garimpeira (PLG), com
indicação de origem sem indícios de extração mineral, ou lavra
incompatível com capacidade produtiva declarada;
e) venda ou proposta de venda de ouro oriundo de áreas caracterizadas
por elevados índices de desmatamento ilegal;
f) proposta de venda de ouro com resistência no fornecimento de
informações acerca da origem do produto;
g) proposta de venda de ouro sem que o vendedor esteja identificado
no documento autorizativo para transporte de ouro emitido pelo
titular do direito minerário produtor da substância, nos termos do
§1º do art. 38 da Lei nº 12.844, de 19 de julho de 2013;
h) venda ou proposta de venda de ouro contendo indícios de falsidade
documental;
i) proposta de venda de ouro com informações incompatíveis com os
dados do título minerário registrados no Cadastro Mineiro da Agência
Nacional de Mineração (ANM);

[Página 191]

j) proposta de venda de ouro em região aurífera diferente da
autorizada para o título minerário produtor da substância, conforme
dados do Cadastro Mineiro da ANM.
XIX – Situações relacionadas com o mercado de ouro em geral:
a) venda ou compra de ouro com recursos em espécie, que apresentem
atipicidade em relação à atividade econômica do cliente ou
incompatibilidade com a sua capacidade financeira;
b) venda ou compra de ouro incompatível com o patrimônio, a
atividade econômica ou a ocupação profissional e a capacidade
financeira do cliente;
c) fracionamento de operações de venda de ouro visando burlar limites
regulamentares ou operacionais;
d) venda ou proposta de venda de ouro contendo informação sobre a
qualidade, a constituição, a pureza ou sobre qualquer outra
característica da substância comercializada divergente da descrição
contida na nota fiscal da operação”.

